    steps = "S\t\t\tvg=1;title=Run into southshore and grab the FP\nG\t\tHillsbrad Foothills\t49.0\t52.0\t\t\t\nI\t\tRun into southshore at |cffbbbbbb(49, 52)|r and grab the FP\nS\t\t\tvg=1\nI\t\tStop at the barn east of the FP, accept |cffffd100Costly Menace|r\nA\t\t564\t\nS\t\t\tvg=1\nI\t\tGo to the house in front of the barn, turn in |cffffd100Southshore|r SKIP the next part\nT\t\t538\t\nS\t\t\tvg=1\nI\t\tGo in front of the Inn, accept |cffffd100Hints of a New Plague|r\nA\t\t659\t\nS\t\t\tvg=1\nI\t\tGo in the Inn, make it your home\nA\t\t536\t\nS\t\t\tvg=1\nI\t\tIn front of the town hall, accept |cffffd100Crushridge Bounty|r\nA\t\t500\t\nS\t\t\tvg=1\nI\t\tGo in the town hall, accept |cffffd100Syndicate Assassins|r\nA\t\t505\t\nS\t\t\tvg=1\nI\t\tGo just SW of Southshore and do |cffffd100Down the Coast|r on the shore, killing murlocs. Turn it in at the Inn when you’re done, accept |cffffd100Farren's Proof pt.1|r\nC\t\t536\t\t\nS\t\t\tvg=1\nT\t\t536\t\nA\t\t559\t\nS\t\t\tvg=1\nI\t\tDo |cffffd100Farren's Proof pt.1|r again on the shore, if I’m not level 31 by the time I’m done getting heads, I grind till I am.\nC\t\t559\t\t\nS\t\t\tvg=1\nI\t\tGo back to the Inn, turn in |cffffd100Farren's Proof pt.1|r accept |cffffd100Farren’s Proof pt.2|r hand that in just out front of the Inn, accept |cffffd100Farren’s Proof pt.3|r Go back into the Inn, hand it in accept |cffffd100Stormwind ho!|r\nT\t\t559\t\nA\t\t560\t\nA\t\t561\t\nA\t\t562\t\nS\t\t\tvg=1\nI\t\tGo do |cffffd100Stormwind ho!|r just SE of the dock now, kill the naga along the shore.\nC\t\t562\t\t\nS\t\t\tvg=1\nI\t\tGo back to the Inn hand in Stormwind ho!\nT\t\t562\t\nA\t\t563\t" },
  { name = "31-31 Alterac Mountains (Alliance)", title = "31-31 Alterac Mountains", group = "VanillaGuide 20-40", faction = "Alliance", lo = 31, hi = 31, next = "31-32 Arathi Highlands (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tAlterac Mountains\t64.0\t38.0\t\t\t\nI\t\tRun up into Alterac Mountains near the AV entrance around |cffbbbbbb(64, 38)|r and kill lions for |cffffd100Costly Menace|r They’re all along the southern border near AV. I usually get all mine in front and West of AV\nC\t\t564\t\t\nS\t\t\tvg=1\nG\t\tAlterac Mountains\t55.0\t67.0\t\t\t\nI\t\tGo east of AV and do |cffffd100Syndicate Assassins|r at the camp around |cffbbbbbb(55, 67)|r. There is a camp close to AV but this one has a quest you can grab near the tents on the table. Clear the camp and touch the syndicate document, accept |cffffd100Foreboding Plans|r and |cffffd100Encrypted Letter|r\nC\t\t505\t\t\nA\t\t510\t\nA\t\t511\t\nS\t\t\tvg=1;title=Hearth to Southshore\nI\t\tHearth to Southshore\nS\t\t\tvg=1\nI\t\tGo into the town hall, turn in |cffffd100Syndicate Assassins|r and |cffffd100Foreboding Plans|r accept |cffffd100Noble Deaths|r\nT\t\t505\t\nT\t\t510\t\nA\t\t512\t\nS\t\t\tvg=1\nI\t\tStop at the house North of the Inn, turn in |cffffd100Encrypted Letter|r accept |cffffd100Letter to Stormpike|r\nT\t\t511\t\nA\t\t514\t\nS\t\t\tvg=1\nI\t\tGo to the barn and turn in |cffffd100Costly Menace|r\nT\t\t564\t\nS\t\t\tvg=1;title=Fly to Refuge Point\nI\t\tFly to Refuge Point" },
  { name = "31-32 Arathi Highlands (Alliance)", title = "31-32 Arathi Highlands", group = "VanillaGuide 20-40", faction = "Alliance", lo = 31, hi = 32, next = "32-32 Stranglethorn Vale (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tArathi Highlands\t33.0\t27.0\t\t\t\nI\t\tAccept |cffffd100Northfold Manor|r grind to it at |cffbbbbbb(33, 27)|r I grind here until I’m level 32\nA\t\t681\t\nS\t\t\tvg=1\nI\t\tHearth to Southshore, Fly to Refuge point, turn in |cffffd100Northfold Manor|r Fly to IF\nT\t\t681\t\nS\t\t\tvg=1\nG\t\tIronforge\t69.0\t20.0\t\t\t\nI\t\tGo to the hall of explorers at |cffbbbbbb(69, 20)|r in IF accept |cffffd100Reclaimers' Business|r in Desolace\nA\t\t1453\t\nS\t\t\tvg=1\nT\t\t514\t\nS\t\t\tvg=1\nA\t\t525\t\nS\t\t\tvg=1\nG\t\tIronforge\t72.0\t93.0\t\t\t\nI\t\tAccept |cffffd100The Brassbolts Brothers|r in The Hall of Arms at |cffbbbbbb(72, 93)|r get new skills\nA\t\t1179\t\nS\t\t\tvg=1;title=Make IF your home Buy some Bloodstone Ore for a quest later in...\nG\t\tArathi Highlands\t18.0\t51.0\t\t\t\nI\t\tMake IF your home at |cffbbbbbb(18, 51)|r Buy some |cff00ff25Bloodstone Ore|r for a quest later in STV. If there is none check the AH in Booty Bay\nS\t\t\tvg=1;title=Fly to SW\nI\t\tFly to SW\nS\t\t\tvg=1\nG\t\tStormwind City\t72.0\t15.0\t\t\t\nI\t\tGo to the Keep at |cffbbbbbb(72, 15)|r and hand in |cffffd100Reassignment|r\nT\t\t563\t\nS\t\t\tvg=1\nG\t\tStormwind City\t39.0\t27.0\t\t\t\nI\t\tGo to |cffbbbbbb(39, 27)|r in the Cathedral and hand in |cffffd100Cleansing the Eye|r\nT\t\t293\t\nS\t\t\tvg=1;title=Fly to Duskwood run and go south into STV\nG\t\tDuskwood\t44.0\t66.0\t\t\t\nI\t\tFly to Duskwood run to |cffbbbbbb(44, 66)|r and go south into STV" },
  { name = "32-32 Stranglethorn Vale (Alliance)", title = "32-32 Stranglethorn Vale", group = "VanillaGuide 20-40", faction = "Alliance", lo = 32, hi = 32, next = "32-33 Thousand Needles (Shimmering Flats) (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1;title=Run to the Rebel Camp at 37,3 its just west after you enter\nG\t\tStranglethorn Vale\t37.0\t3.0\t\t\t\nI\t\tRun to the Rebel Camp at 37,3 its just west after you enter.\nS\t\t\tvg=1\nA\t\t203\t\nA\t\t204\t\nS\t\t\tvg=1\nA\t\t210\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t35.0\t10.0\t\t\t\nI\t\tGo to Nessingway’s at |cffbbbbbb(35, 10)|r and accept |cffffd100Welcome to the Jungle|r turn it in behind you. This opens the 3 quest givers here.\nA\t\t583\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t35.0\t10.0\t\t\t\nC\t\t583\t\t\nS\t\t\tvg=1\nI\t\tNow Accept |cffffd100Raptor Mastery pt.1|r |cffffd100Panther Mastery pt.1|r |cffffd100Tiger Mastery pt.1|r Don’t accept the page-collecting quest until you have all the pages.\nT\t\t583\t\nA\t\t194\t\nA\t\t190\t\nA\t\t185\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t41.0\t9.0\t\t\t\nI\t\tDo |cffffd100Panther Mastery pt.1|r & |cffffd100Tiger Mastery pt.1|r Tigers are just behind Nessingway’s, and the Panthers are to the east some but centralized around 41,9\nC\t\t190\t\t\nC\t\t185\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t44.0\t10.0\t\t\t\nI\t\tGo to |cffbbbbbb(44, 10)|r and do |cffffd100The Second Rebellion|r and the Kurzen supply crate at 44,9 in front of the Inn for |cffffd100Bad Medicine|r the remedies are a low drop from medicine men.\nC\t\t203\t\t\nC\t\t204\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t37.0\t3.0\t\t\t\nI\t\tRun back up to the rebel camp at 37,3 Turn in |cffffd100The Second Rebellion|r and |cffffd100Bad Medicine|r SKIP |cffff6060Special Forces|r.\nT\t\t203\t\nT\t\t204\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t35.0\t10.0\t\t\t\nI\t\tGo back to Nessingway’s at |cffbbbbbb(35, 10)|r and hand in |cffffd100Panther Mastery|r pt.1 & |cffffd100Tiger Mastery pt.1|r accept |cffffd100Panther Mastery pt.2|r & |cffffd100Tiger Mastery pt.2|r.\nT\t\t190\t\nT\t\t185\t\nA\t\t191\t\nA\t\t186\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t29.0\t10.0\t\t\t\nI\t\tKill Stranglethorn Tigers for around |cffbbbbbb(29, 10)|r for |cffffd100Tiger Mastery pt.2|r and the Panthers around |cffbbbbbb(28, 12)|r for |cffffd100Panther Mastery pt.2|r.\nC\t\t186\t\t\nC\t\t191\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t26.0\t15.0\t\t\t\nI\t\tKill Stranglethorn Raptors for |cffbbbbbb(26, 15)|r |cffffd100Raptor Mastery pt.1|r\nC\t\t194\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t35.0\t10.0\t\t\t\nI\t\tGo back to Nessingway’s at |cffbbbbbb(35, 10)|r and turn in |cffffd100Tiger Mastery pt.2|r, |cffffd100Panther Mastery pt.2|r, and |cffffd100Raptor Mastery pt.1|r.\nT\t\t186\t\nT\t\t191\t\nT\t\t194\t\nA\t\t187\t\nA\t\t192\t\nA\t\t195\t\nS\t\t\tvg=1;title=Run to Booty Bay and get the FP\nI\t\tRun to Booty Bay and get the FP.\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Krazek's Cookery|r on the top floor of the inn, accept and hand back in (the bloodstone ores) |cffffd100Favor for Krazek|r accept |cffffd100Return to Corporal Kaleb|r (this quest gives you your first helm) also accept |cffffd100Investigate the Camp|r and |cffffd100Supplies to Private Thorsen|r\nT\t\t210\t\nA\t\t627\t\nA\t\t622\t\nA\t\t201\t\nA\t\t198\t\nS\t\t\tvg=1;title=Get on the Boat to Rachet\nI\t\tGet on the Boat to Rachet\nS\t\t\tvg=1;title=Grab the FP\nI\t\tGrab the FP\nS\t\t\tvg=1;title=Now for a little bit of a run through horde territory\nI\t\tNow for a little bit of a run through horde territory. Run all the way south in the barrens to the great lift and take it down into 1k needles. Jump off if you get attacked.\nS\t\t\tvg=1;title=Run all the way south in the barrens to the great lift and take...\nI\t\tRun all the way south in the barrens to the great lift and take it down into 1k needles. Jump off if you get attacked." },
  { name = "32-33 Thousand Needles (Shimmering Flats) (Alliance)", title = "32-33 Thousand Needles (Shimmering Flats)", group = "VanillaGuide 20-40", faction = "Alliance", lo = 32, hi = 33, next = "33-33 Stonetalon Mountains (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1;title=Now Get the FP on the west side of this zone at 8,18, it’s just...\nG\t\tThousand Needles\t8.0\t18.0\t\t\t\nI\t\tNow Get the FP on the west side of this zone at 8,18, it’s just inside Feralas. This will save a lot of time later on.\nS\t\t\tvg=1;title=You should be close to level 33 so grind to it on your way to...\nI\t\tYou should be close to level 33 so grind to it on your way to Shimmering Flats.\nS\t\t\tvg=1\nG\t\tThousand Needles\t78.0\t77.0\t\t\t\nT\t\t1179\t\nA\t\t1105\t\nA\t\t1104\t\nS\t\t\tvg=1\nI\t\tGo a little beside these guys and grab |cffffd100Rocket Car Parts|r, |cffffd100Wharfmaster Dizzywig|r and |cffffd100Hemet Nesingwary|r\nA\t\t1110\t\nA\t\t1111\t\nA\t\t5762\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t80.0\t75.0\t\t\t\nA\t\t1176\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t81.0\t77.0\t\t\t\nA\t\t1175\t\nS\t\t\tvg=1\nI\t\tNow the car parts for |cffffd100Rocket Car Parts|r are scattered all over here, so grab them as you quest. The Buzzards for |cffffd100Load Lightening|r are all over as well so kill one if you see it.\nC\t\t1110\t\t\nC\t\t1176\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t76.0\t87.0\t\t\t\nI\t\tStart off by going south and killing gazers and crystalhide at |cffbbbbbb(76, 87)|r for |cffffd100A Bump in the Road|r\nC\t\t1175\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t71.0\t74.0\t\t\t\nI\t\tKill scorpions at |cffbbbbbb(71, 74)|r and north of here for |cffffd100Salt Flat Venom|r\nC\t\t1104\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t73.0\t59.0\t\t\t\nI\t\tKill Basilisks around |cffbbbbbb(73, 59)|r for |cffffd100A Bump in the Road|r\nC\t\t1175\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t82.0\t54.0\t\t\t\nI\t\tKill Turtles at |cffbbbbbb(82, 54)|r for |cffffd100Hardened Shells|r\nC\t\t1105\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t86.0\t66.0\t\t\t\nI\t\tStop at |cffbbbbbb(86, 66)|r and do |cffffd100Load Lightening|r\nC\t\t1176\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t77.0\t77.0\t\t\t\nT\t\t1110\t\nS\t\t\tvg=1\nI\t\tGo to the 2 npc’s next east of here and hand in |cffffd100Salt Flat Venom|r and |cffffd100Hardened Shells|r\nT\t\t1104\t\nT\t\t1105\t\nA\t\t1106\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t80.0\t75.0\t\t\t\nT\t\t1176\t\nA\t\t1178\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t81.0\t77.0\t\t\t\nT\t\t1175\t\nS\t\t\tvg=1;title=Run south into Tanaris and Grab the FP at Gadgetzan\nI\t\tRun south into Tanaris and Grab the FP at Gadgetzan\nS\t\t\tvg=1;title=Hearth back to IF and fly to Menethil Harbor, get on the boat...\nI\t\tHearth back to IF and fly to Menethil Harbor, get on the boat to Theramore, Get FP and either fly to Stonetalon Mountains or go back and sail to Darkshore." },
  { name = "33-33 Stonetalon Mountains (Alliance)", title = "33-33 Stonetalon Mountains", group = "VanillaGuide 20-40", faction = "Alliance", lo = 33, hi = 33, next = "33-35 Desolace (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tStonetalon Mountains\t32.0\t66.0\t\t\t\nI\t\tAccept |cffffd100Reclaiming the Charred Vale|r in front of the moonwell go do it in the Charred Vale at |cffbbbbbb(32, 66)|r while going towards Desolace\nA\t\t1057\t" },
  { name = "33-35 Desolace (Alliance)", title = "33-35 Desolace", group = "VanillaGuide 20-40", faction = "Alliance", lo = 33, hi = 35, next = "35-36 Stranglethorn Vale (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tMake Nijel’s Point your home fly back to Stonetalon and hand in |cffffd100Reclaiming the Charred Vale|r SKIP the next part.\nT\t\t1057\t\nS\t\t\tvg=1;title=Hearth back to Desolace\nI\t\tHearth back to Desolace\nS\t\t\tvg=1\nI\t\tGo south of the Inn, hand in |cffffd100Reclaimers' Business|r in Desolace accept |cffffd100Reagents for Reclaimers Inc pt.1|r and |cffffd100The Karnitol Shipwreck pt.1|r\nT\t\t1453\t\nA\t\t1458\t\nA\t\t1454\t\nS\t\t\tvg=1;title=I SKIP both of the faction centaur quests\nI\t\tI SKIP both of the faction centaur quests. It’s just a useless grind for 2 quests that aren’t worth it.\nS\t\t\tvg=1\nA\t\t1387\t\nS\t\t\tvg=1\nI\t\tGo south a little bit more and accept |cffffd100Vahlarriel's Search pt.1|r\nA\t\t1437\t\nS\t\t\tvg=1\nG\t\tDesolace\t56.0\t17.0\t\t\t\nI\t\tRun west to |cffbbbbbb(56, 17)|r |cffffd100Vahlarriel's Search pt.1|r accept |cffffd100Vahlarriel’s Search pt.2|r\nT\t\t1437\t\nC\t\t1437\t\t\nA\t\t1465\t\nS\t\t\tvg=1\nG\t\tDesolace\t75.0\t20.0\t\t\t\nI\t\tRun east to Sargeron around |cffbbbbbb(75, 20)|r and kill the demons for |cffffd100Reagents for Reclaimers Inc pt.1|r\nC\t\t1458\t\t\nS\t\t\tvg=1\nI\t\tRun back to Nijel’s, hand in |cffffd100Vahlarriel’s Search pt.2|r accept |cffffd100Vahlarriel’s Search pt.3|r\nT\t\t1465\t\nA\t\t1438\t\nS\t\t\tvg=1\nI\t\tRun up a bit more, turn in |cffffd100Reagents for Reclaimers Inc pt.1|r accept |cffffd100Reagents for Reclaimers Inc pt.2|r\nT\t\t1458\t\nA\t\t1459\t\nS\t\t\tvg=1\nG\t\tDesolace\t62.0\t38.0\t\t\t\nI\t\tNow start grinding on the scorps and other stuff for |cffffd100Reagents for Reclaimers Inc pt.2|r as you head to |cffbbbbbb(62, 38)|r and accept |cffffd100Bone Collector|r since the scorps are a low drop rate just kill them as you’re running around\nC\t\t1459\t\t\nA\t\t5501\t\nS\t\t\tvg=1\nG\t\tDesolace\t72.0\t45.0\t\t\t\nI\t\tRun east until you’re at kolkar village around |cffbbbbbb(72, 45)|r. Kill them for |cffffd100Centaur Bounty|r If you’re not 34 when done with this, grind until you are\nC\t\t1387\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t60.0\t61.0\t\t\t\nI\t\tGrind down to |cffbbbbbb(60, 61)|r and accept |cffffd100Kodo Roundup|r This is a unique quest where you tame a kodo at the GY bring it back until you have 5.\nA\t\t5561\t\nS\t\t\tvg=1\nI\t\tIf you see the pack of aged kodo’s running around kill 3 of them for |cffffd100Reagents for Reclaimers Inc pt.2|r if not you can find some inside the kodo graveyard.\nC\t\t1459\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t51.0\t58.0\t\t\t\nI\t\tGo to the Kodo Graveyard around |cffbbbbbb(51, 58)|r. Do |cffffd100Bone Collector|r everytime you come to pick up a kodo for roundup.\nC\t\t5501\t\t\nS\t\t\tvg=1\nI\t\tOnce you’re done with |cffffd100Kodo Roundup|r hand it in and run NW of the GY towards the water. Killing scorps if you still need them.\nC\t\t5561\t\t\nS\t\t\tvg=1\nT\t\t5561\t\nS\t\t\tvg=1\nG\t\tDesolace\t38.0\t27.0\t\t\t\nI\t\tGrab |cffffd100Sceptre of Light|r at |cffbbbbbb(38, 27)|r near the big tower\nA\t\t5741\t\nS\t\t\tvg=1\nG\t\tDesolace\t36.0\t30.0\t\t\t\nI\t\tGo south on the beach to |cffbbbbbb(36, 30)|r and finish |cffffd100The Karnitol Shipwreck pt.1|r accept |cffffd100The Karnitol Shipwreck pt.2|r then accept |cffffd100Claim Rackmore's Treasure!|r from Rackmore’s log. If your quest log is full drop centaur bounty.\nT\t\t1454\t\nC\t\t1454\t\t\nA\t\t1455\t\nA\t\t6161\t\nS\t\t\tvg=1\nI\t\tKill Drysnaps in the waters right here for the silver key of |cffffd100Claim Rackmore's Treasure!|r and The Slitherblades just North of here for the golden key.\nC\t\t6161\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t54.0\t26.0\t\t\t\nI\t\tRun up to Thunder Axe Fortress at |cffbbbbbb(56, 29)|r and go in the main building in the center and turn in |cffffd100Vahlarriel’s Search pt.3|r at |cffbbbbbb(54, 26)|r accept |cffffd100Search for Tyranis|r\nT\t\t1438\t\nA\t\t1439\t\nS\t\t\tvg=1\nI\t\tRun out and right, kill a seer up in a tower for |cffffd100Sceptre of Light|r\nC\t\t5741\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t53.0\t29.0\t\t\t\nI\t\tGo to the building west of the entrance at |cffbbbbbb(53, 29)|r kill Tyranis Malem for |cffffd100Search for Tyranis|r then turn it back in inside the main building. Clear the way in the main building to the right because an escort is next.\nC\t\t1439\t\t\nS\t\t\tvg=1\nI\t\tAccept the escort quest |cffffd100Return to Vahlarriel|r DON’T attack anything unless it hits or or she’ll ignore it and keep walking. The reason it seems is melee just follow her, only the mages can hit her to start combat.\nT\t\t1439\t\nA\t\t1440\t\nS\t\t\tvg=1\nG\t\tDesolace\t62.0\t38.0\t\t\t\nT\t\t5501\t\nS\t\t\tvg=1\nG\t\tDesolace\t38.0\t27.0\t\t\t\nT\t\t5741\t\nA\t\t6027\t\nS\t\t\tvg=1\nG\t\tDesolace\t30.0\t9.0\t\t\t\nI\t\tSwim all the way NW on the map to Ranazjar Isle and open the chest at 30,9 for |cffffd100Claim Rackmore's Treasure!|r\nC\t\t6161\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t28.0\t7.0\t\t\t\nI\t\tGo to the back of the island and clear all around the serpent statue at 28,7. You’re gonna do |cffffd100Book of the Ancients|r This quest bugs if you do not click the gem in your inventory and then on the statue. Don’t just click on the statue. He’s 38 but super easy.\nC\t\t6027\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t38.0\t27.0\t\t\t\nI\t\tSwim back to |cffbbbbbb(38, 27)|r and turn in |cffffd100Book of the Ancients|r\nT\t\t6027\t\nS\t\t\tvg=1;title=Hearth to Nijel’s\nI\t\tHearth to Nijel’s\nS\t\t\tvg=1\nI\t\tGo south of the Inn and turn in |cffffd100Reagents for Reclaimers Inc pt.2|r SKIP pt.3 for now, and |cffffd100The Karnitol Shipwreck pt.2|r SKIP the rest.\nT\t\t1459\t\nA\t\t1455\t\nS\t\t\tvg=1\nI\t\tGo south a bit more, turn in |cffffd100Centaur Bounty|r\nT\t\t1387\t\nS\t\t\tvg=1\nI\t\tFinally turn in |cffffd100Return to Vahlarriel|r\nT\t\t1440\t\nS\t\t\tvg=1;title=You should be within 2 bars to level 35 now\nG\t\tDesolace\t37.0\t80.0\t\t\t\nI\t\tYou should be within 2 bars to level 35 now. I grind down on the Centaurs at Gelkis Village at |cffbbbbbb(37, 80)|r until level 35\nS\t\t\tvg=1;title=Head south into Feralas to get the FP, this will again save...\nI\t\tHead south into Feralas to get the FP, this will again save more time later on.\nS\t\t\tvg=1;title=Get on the Boat and grab the FP in Feathermoon\nG\t\tDesolace\t43.0\t42.0\t\t\t\nI\t\tGet on the Boat at |cffbbbbbb(43, 42)|r and grab the FP in Feathermoon. Fly to Theramore to Rachet.\nS\t\t\tvg=1\nG\t\tThe Barrens\t62.0\t36.0\t\t\t\nI\t\tGo to the engineer hut at |cffbbbbbb(62, 36)|r and hand in |cffffd100Goblin Sponsorship pt.1|r accept |cffffd100Goblin Sponsorship pt.2|r\nT\t\t1178\t\nA\t\t1180\t\nS\t\t\tvg=1\nI\t\tRun out on the dock and hand in |cffffd100Wharfmaster Dizzywig|r\nT\t\t1111\t\nS\t\t\tvg=1\nA\t\t1112\t\nS\t\t\tvg=1;title=Get on the boat to Booty Bay\nI\t\tGet on the boat to Booty Bay" },
  { name = "35-36 Stranglethorn Vale (Alliance)", title = "35-36 Stranglethorn Vale", group = "VanillaGuide 20-40", faction = "Alliance", lo = 35, hi = 36, next = "36-37 Alterac Mountains (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tHand in |cffffd100Goblin Sponsorship pt.2|r as you get off the boat, accept |cffffd100Goblin Sponsorship pt.3|r\nT\t\t1180\t\nA\t\t1181\t\nS\t\t\tvg=1\nI\t\tGo in the Inn make BB your home, Accept |cffffd100Singing Blue Shards|r\nA\t\t605\t\nS\t\t\tvg=1\nA\t\t213\t\nA\t\t189\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100The Haunted Isle|r and turn it in just outside the door, accept |cffffd100The Stone of the Tides|r\nA\t\t616\t\nA\t\t578\t\nT\t\t1181\t\nA\t\t1182\t\nS\t\t\tvg=1\nI\t\tGo into the shop Tan-Your-Hide Leatherworks and accept |cffffd100Supply and Demand|r (it’s down the ramp from the FP)\nA\t\t575\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t48.0\t21.0\t\t\t\nI\t\tGo around |cffbbbbbb(48, 21)|r and Kill Shadowmaw Panthers for |cffffd100Panther Mastery pt.3|r\nC\t\t192\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t43.0\t18.0\t\t\t\nI\t\tRun west to the Venture Co. Base Camp at |cffbbbbbb(43, 18)|r and Kill the goblins here for |cffffd100Hostile Takeover|r while you climb the Operations Tower behind the base for |cffffd100Goblin Sponsorship pt.4|r You’re going to climb it and kill Foreman Cozzle for his key.\nC\t\t213\t\t\nC\t\t1182\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t43.0\t20.0\t\t\t\nI\t\tIf you still don’t have all the crystals kill the goblins until you do, then enter the tiny shack next to the base at |cffbbbbbb(43, 20)|r and open the chest to get the blueprints for |cffffd100Goblin Sponsorship pt.4|r\nC\t\t1182\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t37.0\t22.0\t\t\t\nI\t\tKill Lashtail Raptors around |cffbbbbbb(37, 22)|r for |cffffd100Raptor Mastery pt.2|r\nC\t\t195\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t33.0\t18.0\t\t\t\nI\t\tKill Elter Tigers around |cffbbbbbb(33, 18)|r for |cffffd100Tiger Mastery pt.3|r\nC\t\t187\t\t\nS\t\t\tvg=1\nI\t\tRun towards Nessingways and kill the crocs in the river around it for |cffffd100Supply and Demand|r\nC\t\t575\t\t\nS\t\t\tvg=1\nI\t\tGo to Nessingways and turn in |cffffd100Tiger Mastery pt.3|r, |cffffd100Panther Mastery pt.3|r, |cffffd100Raptor Mastery pt.2|r, and |cffffd100Hemet Nesingwary|r, Accept |cffffd100Tiger Mastery pt.4|r |cffffd100Panther Mastery pt.4|r and |cffffd100Raptor Mastery pt.3|r\nT\t\t187\t\nT\t\t192\t\nT\t\t195\t\nT\t\t5762\t\nA\t\t188\t\nA\t\t193\t\nA\t\t196\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t32.0\t17.0\t\t\t\nI\t\tRun back south to the top of the hill at |cffbbbbbb(32, 17)|r and kill Sin’Dall for |cffffd100Tiger Mastery pt.4|r then turn it back in at Nessingways\nC\t\t188\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t37.0\t3.0\t\t\t\nI\t\tGo up to the rebel camp at 37,3 and hand in |cffffd100Supplies to Private Thorsen|r, If he’s not here look south of the camp, if you save him when he patrols you can also get |cffffd100Jungle Secrets|r u turn that in at the camp and get |cffffd100Bookie Herod|r\nT\t\t198\t\nA\t\t215\t\nA\t\t200\t\nS\t\t\tvg=1\nI\t\tHand in |cffffd100Return to Corporal Kaleb|r get your helm\nT\t\t622\t\nS\t\t\tvg=1\nA\t\t574\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t43.0\t9.0\t\t\t\nI\t\tGo to the Inn looking building at 43,9 touch the book on the 2nd floor and hand in |cffffd100Bookie Herod|r accept |cffffd100The Hidden Key|r\nT\t\t200\t\nA\t\t328\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t43.0\t9.0\t\t\t\nC\t\t328\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t45.0\t7.0\t\t\t\nI\t\tGo in the cave at 45,7 and kill the mobs in here for |cffffd100Special Forces|r and make your way to the chest for |cffffd100Bookie Herod|r , it’s down the first fork, only 1 level down then in the boxes. Accept |cffffd100The Spy Revealed!|r (Easy from here)\nT\t\t328\t\nC\t\t574\t\t\nC\t\t200\t\t\nA\t\t329\t\nS\t\t\tvg=1;title=Now grind back out since you should be close to level 36\nI\t\tNow grind back out since you should be close to level 36. Once your out go back to the rebel camp.\nS\t\t\tvg=1\nI\t\tHand in |cffffd100Special Forces|r SKIP the next part\nT\t\t574\t\nS\t\t\tvg=1\nI\t\tTurn around again and hand that back in (told you it was easy)\nT\t\t329\t\nA\t\t330\t\nA\t\t331\t\nS\t\t\tvg=1;title=You should definitely be level 36 by now\nI\t\tYou should definitely be level 36 by now. We’ll get skills soon\nS\t\t\tvg=1\nI\t\tGo south toward the GY, then go west north of the river and kill basalisks for |cffffd100Singing Blue Shards|r if you don’t get them all now don’t worry there is more south.\nC\t\t605\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t29.0\t19.0\t\t\t\nI\t\tKill Bloodscalp at |cffbbbbbb(29, 19)|r for |cffffd100Bloodscalp Ears|r You’ll probably have to clear it 2-3 times. They’re easy\nC\t\t189\t\t\nS\t\t\tvg=1\nI\t\tKill Basalisks to finish |cffffd100Singing Blue Shards|r just west of here above the shore.\nC\t\t605\t\t\nS\t\t\tvg=1\nI\t\tRun south on the Island till it says complete for |cffffd100The Stone of the Tides|r Go back up and kill basalisks if needed.\nC\t\t578\t\t\nS\t\t\tvg=1;title=Hearth to BB\nI\t\tHearth to BB\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Singing Blue Shards|r SKIP the next for now\nT\t\t605\t\nS\t\t\tvg=1\nI\t\tGo upstairs turn in |cffffd100Investigate the Camp|r, |cffffd100Bloodscalp Ears|r\nT\t\t201\t\nT\t\t189\t\nS\t\t\tvg=1\nT\t\t578\t\nT\t\t1182\t\nA\t\t601\t\nA\t\t1183\t\nS\t\t\tvg=1\nI\t\tGo into the shop Tan-Your-Hide Leatherworks and turn in |cffffd100Supply and Demand|r (it’s down the ramp from the FP) accept |cffffd100Some assembly required|r\nT\t\t575\t\nA\t\t577\t\nS\t\t\tvg=1;title=I’m half way to level 37 at this point\nI\t\tI’m half way to level 37 at this point\nS\t\t\tvg=1;title=Fly to IF get new skills fly to Menethil Harbor, make it your...\nI\t\tFly to IF get new skills fly to Menethil Harbor, make it your home, and sail to Theramore\nS\t\t\tvg=1\nI\t\tIf you’re first aid is at 225 go do |cffffd100Triage|r fly to Gadgetzan\nA\t\t6624\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t77.0\t77.0\t\t\t\nI\t\tRun out to Shimmering Flats at |cffbbbbbb(77, 77)|r and turn in |cffffd100Parts for Kravel|r accept |cffffd100Delivery to the Gnomes|r\nT\t\t1112\t\nA\t\t1114\t\nS\t\t\tvg=1\nI\t\tGo a little East and hand in |cffffd100Goblin Sponsorship pt.5|r accept |cffffd100The Eighteenth Pilot|r hand it in 2 feet away, accept |cffffd100Razzeric's Tweaking|r\nT\t\t1183\t\nA\t\t1186\t\nA\t\t1187\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t77.0\t77.0\t\t\t\nC\t\t1114\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t77.0\t77.0\t\t\t\nI\t\tHearth to Menethil Harbor\nT\t\t1114\t\nA\t\t1115\t" },
