    steps = "S\t\t\tvg=1\nI\t\tGo to the Town Hall and turn in |cffffd100Further Mysteries|r accept |cffffd100Dark Council|r and |cffffd100Noble Deaths|r\nT\t\t525\t\nA\t\t537\t\nA\t\t512\t\nS\t\t\tvg=1;title=Make Southshore your home\nI\t\tMake Southshore your home\nS\t\t\tvg=1;title=Run into Alterac Mountains and kill ogres for Crushridge Bounty\nG\t\tAlterac Mountains\t47.0\t55.0\t\t\t\nI\t\tRun into Alterac Mountains to |cffbbbbbb(47, 55)|r and kill ogres for Crushridge Bounty\nS\t\t\tvg=1\nG\t\tAlterac Mountains\t60.0\t43.0\t\t\t\nI\t\tGrind up to Strahnbrad around |cffbbbbbb(60, 43)|r and kill the syndicate and grab their rings for |cffffd100Noble Deaths|r You can also kill shadow mages here for |cffffd100Dark Council|r which is easier than killing them in the camps later\nC\t\t512\t\t\nC\t\t537\t\t\nS\t\t\tvg=1\nG\t\tAlterac Mountains\t39.0\t16.0\t\t\t\nI\t\tGrind your way west to to the house at |cffbbbbbb(39, 16)|r and kill |cff00ff25Nagaz|r for |cffffd100Dark Council|r. I take out the first camp you come across then grind anything in my way west that’s not in a camp.\nC\t\t537\t\t\nS\t\t\tvg=1;title=You wanna be at least 2 bars from level 37, if so hearth to SS\nI\t\tYou wanna be at least 2 bars from level 37, if so hearth to SS\nS\t\t\tvg=1\nI\t\tRun across from the Inn, turn in |cffffd100Crushridge Bounty|r SKIP the next\nT\t\t500\t\nS\t\t\tvg=1\nI\t\tGo in the Inn, turn in |cffffd100Dark Council|r and |cffffd100Noble Deaths|r\nT\t\t537\t\nT\t\t512\t\nS\t\t\tvg=1;title=Fly to Arathi Highlands\nI\t\tFly to Arathi Highlands" },
