    steps = "S\t\t\tvg=1\nI\t\tNear the moonwell accept |cffffd100The Twilight Mystery|r\nA\t\t8284\t\nS\t\t\tvg=1\nI\t\tIn front of the Inn, turn in |cffffd100Taking Back Silithus|r accept |cffffd100Securing the Supply Lines|r\nT\t\t8275\t\nA\t\t8280\t\nS\t\t\tvg=1;title=SKIP the quest on the sign unless you get a group\nI\t\tSKIP the quest on the sign unless you get a group\nS\t\t\tvg=1;title=Make Cenarion Hold your home\nI\t\tMake Cenarion Hold your home\nS\t\t\tvg=1\nI\t\tUpstairs accept |cffffd100Deadly Desert Venom|r\nA\t\t8277\t\nS\t\t\tvg=1;title=There seems to be a lot of white quests because there's many AQ...\nI\t\tThere seems to be a lot of white quests because there's many AQ quests that you don’t have to worry about yet.\nS\t\t\tvg=1\nG\t\tSilithus\t55.0\t24.0\t\t\t\nI\t\tGo do |cffffd100Securing the Supply Lines|r and |cffffd100Deadly Desert Venom|r North and NE of town all around |cffbbbbbb(55, 24)|r the dredges, scorpids, and skitterers for these 2 quests are all over this area.\nC\t\t8280\t\t\nC\t\t8277\t\t\nS\t\t\tvg=1\nG\t\tSilithus\t81.0\t18.0\t\t\t\nT\t\t1124\t\nA\t\t1125\t\nS\t\t\tvg=1\nG\t\tSilithus\t22.0\t9.0\t\t\t\nI\t\tRun up NW to around 22.9 and pick up the twilight tablet fragments for |cffffd100The Twilight Mystery|r They litter this spot\nC\t\t8284\t\t\nS\t\t\tvg=1;title=Hearth to Cenarion Hold\nI\t\tHearth to Cenarion Hold\nS\t\t\tvg=1\nI\t\tUp stairs turn in |cffffd100Deadly Desert Venom|r accept |cffffd100Noggle's Last Hope|r\nT\t\t8277\t\nA\t\t8278\t\nS\t\t\tvg=1\nI\t\tIn front of the Inn, turn in |cffffd100Securing the Supply Lines|r accept |cffffd100Stepping Up Security|r\nT\t\t8280\t\nA\t\t8281\t\nS\t\t\tvg=1\nI\t\tGo next to the moonwell and turn in |cffffd100The Twilight Mystery|r accept |cffffd100The Deserter|r\nT\t\t8284\t\nA\t\t8285\t\nS\t\t\tvg=1;title=You should be about 30-35% into level 56\nI\t\tYou should be about 30-35% into level 56\nS\t\t\tvg=1\nG\t\tSilithus\t62.0\t53.0\t\t\t\nI\t\tGo SE to |cffbbbbbb(62, 53)|r and kill the undead mobs here for |cffffd100The Spirits of Southwind|r be careful when they die they spawn 1-2 bugs\nC\t\t1125\t\t\nS\t\t\tvg=1\nG\t\tSilithus\t56.0\t58.0\t\t\t\nI\t\tKill the pincers for |cffffd100Noggle's Last Hope|r and drudges for |cffffd100The Deserter|r south of here around |cffbbbbbb(56, 58)|r\nC\t\t8278\t\t\nC\t\t8285\t\t\nS\t\t\tvg=1\nG\t\tSilithus\t67.0\t69.0\t\t\t\nI\t\tGo to the cave at |cffbbbbbb(67, 69)|r and turn in |cffffd100The Deserter|r accept |cffffd100The Twilight Lexicon|r\nT\t\t8285\t\nA\t\t8279\t\nS\t\t\tvg=1\nG\t\tSilithus\t43.0\t72.0\t\t\t\nI\t\tYou can find flayers and stalkers outside of the cave for |cffffd100Noggle's Last Hope|r they are also both around |cffbbbbbb(43, 72)|r on the other side of the hive\nC\t\t8278\t\t\nS\t\t\tvg=1;title=Hearth back to Cenarion Hold or die so you end up there\nI\t\tHearth back to Cenarion Hold or die so you end up there\nS\t\t\tvg=1\nI\t\tGo upstairs and turn in for |cffffd100Noggle's Last Hope|r accept |cffffd100Noggle's Lost Satchel|r\nT\t\t8278\t\nA\t\t8282\t\nS\t\t\tvg=1\nI\t\tOutside the Inn, turn in |cffffd100Stepping Up Security|r\nT\t\t8281\t\nS\t\t\tvg=1\nG\t\tSilithus\t29.0\t35.0\t\t\t\nI\t\tGo to |cffbbbbbb(29, 35)|r and kill Twilight Keeper Manya for |cffffd100The Twilight Lexicon|r she fears a bit. She’s at the SE corner of came\nC\t\t8279\t\t\nS\t\t\tvg=1\nG\t\tSilithus\t41.0\t41.0\t\t\t\nI\t\tGo to |cffbbbbbb(41, 41)|r and kill Twilight Keeper Havanuth for |cffffd100The Twilight Lexicon|r he’s on the east side of camp, he has a nasty aoe\nC\t\t8279\t\t\nS\t\t\tvg=1\nG\t\tSilithus\t42.0\t90.0\t\t\t\nI\t\tGo all the way down south to the little camp at |cffbbbbbb(42, 90)|r and go up the hill behind it, you’ll find Deathclasp, in the middle of the path on the wall is a pouch, grab it when deathclasp is in the back for |cffffd100Noggle's Lost Satchel|r\nC\t\t8282\t\t\nS\t\t\tvg=1\nG\t\tSilithus\t16.0\t87.0\t\t\t\nI\t\tHead to the SW to |cffbbbbbb(16, 87)|r and kill Twilight Keeper Exeter for |cffffd100The Twilight Lexicon|r he’s at the SW corner of camp\nC\t\t8279\t\t\nS\t\t\tvg=1\nG\t\tSilithus\t67.0\t69.0\t\t\t\nI\t\tGo back to the cave at |cffbbbbbb(67, 69)|r and turn in |cffffd100The Twilight Lexicon|r accept |cffffd100A Terrible Purpose|r He also offers another quest for 10 twilight texts, this is more for cen circle rep later on\nT\t\t8279\t\nA\t\t8287\t\nS\t\t\tvg=1\nG\t\tSilithus\t81.0\t18.0\t\t\t\nT\t\t1125\t\nA\t\t1126\t\nS\t\t\tvg=1\nG\t\tSilithus\t61.0\t52.0\t\t\t\nI\t\tGo to the top of the tower at |cffbbbbbb(61, 52)|r Be careful 3 bugs spawn when you enter. Shift right click the pod because as soon as you open it some amushers spawn. Kill at least 1 and loot it for |cffffd100Hive in the Tower|r\nC\t\t1126\t\t\nS\t\t\tvg=1\nG\t\tSilithus\t81.0\t18.0\t\t\t\nT\t\t1126\t\nA\t\t6844\t\nS\t\t\tvg=1;title=Hearth to Cenarion Hold\nI\t\tHearth to Cenarion Hold\nS\t\t\tvg=1\nI\t\tGo upstairs and turn in |cffffd100Noggle's Lost Satchel|r\nT\t\t8282\t\nS\t\t\tvg=1\nI\t\tGo into the long building and turn in |cffffd100A Terrible Purpose|r\nT\t\t8287\t\nS\t\t\tvg=1;title=Fly to Moonglade\nI\t\tFly to Moonglade\nS\t\t\tvg=1\nG\t\tMoonglade\t44.0\t35.0\t\t\t\nT\t\t6844\t\nA\t\t6845\t\nS\t\t\tvg=1\nG\t\tMoonglade\t44.0\t35.0\t\t\t\nI\t\tRun over to |cffbbbbbb(51, 44)|r and turn in |cffffd100Uncovering Past Secrets|r\nT\t\t6845\t\nS\t\t\tvg=1;title=You should now be 80-85% into leveling\nI\t\tYou should now be 80-85% into leveling\nS\t\t\tvg=1;title=Fly to Auberdine and sail to Menethil fly to IF\nI\t\tFly to Auberdine and sail to Menethil fly to IF\nS\t\t\tvg=1\nI\t\tMake IF your home find the wandering commander dwarf and accept |cffffd100A Call To Arms: The Plaguelands!|r\nA\t\t5066\t\nS\t\t\tvg=1;title=Fly to Southshore\nI\t\tFly to Southshore\nS\t\t\tvg=1;title=Run north into Alterac Mountains and over NE and run into...\nG\t\tAlterac Mountains\t80.0\t34.0\t\t\t\nI\t\tRun north into Alterac Mountains and over NE to |cffbbbbbb(80, 34)|r and run into Western Plaguelands (WPL)" },
  { name = "56-57 Western Plaguelands (Alliance)", title = "56-57 Western Plaguelands", group = "VanillaGuide 40-60", faction = "Alliance", lo = 56, hi = 57, next = "57-58 Eastern Plaguelands (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tNext to the shack accept |cffffd100A Plague Upon Thee pt.1|r\nA\t\t5903\t\nS\t\t\tvg=1;title=Grab the FP\nI\t\tGrab the FP\nS\t\t\tvg=1;title=Whenever you come back to camp here always check the vendor for...\nI\t\tWhenever you come back to camp here always check the vendor for the stormshroud pants recipe. It’s like 1.3g and you can easily sell it for 10 or 20g+ It’s a limited recipe that restocks 1 every hour.\nS\t\t\tvg=1\nI\t\tGo to the tent and turn in |cffffd100A Call To Arms: The Plaguelands!|r, accept |cffffd100Clear The Way|r\nT\t\t5066\t\nA\t\t5092\t\nS\t\t\tvg=1\nI\t\tGo to the 3 Argent Dawn people near the other tent and turn in |cffffd100The Everlook Report|r and also complete |cffffd100Argent Dawn Commission|r it’s not a quest you had she just uses it to give you the trinket which you should always wear when in WPL and EPL because it gives you AD rep and allows the scourge tokens to drop, which she also has 3 new quests on those for turn ins. You most likely won’t get anything past the first quest as the rest are mainly in the instances.\nT\t\t6028\t\nA\t\t5401\t\nS\t\t\tvg=1;title=Save the tokens until I say to hand them in\nI\t\tSave the tokens until I say to hand them in\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t51.0\t78.0\t\t\t\nI\t\tGo NE to around |cffbbbbbb(51, 78)|r and grind the ghouls here until you got enough for |cffffd100Clear The Way|r\nC\t\t5092\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t42.0\t84.0\t\t\t\nI\t\tGo back to Chillwind Camp at |cffbbbbbb(42, 84)|r and turn in |cffffd100Clear The Way|r accept |cffffd100All Along the Watchtowers|r and |cffffd100The Scourge Cauldrons|r\nT\t\t5092\t\nA\t\t5097\t\nA\t\t5215\t\nS\t\t\tvg=1\nT\t\t5215\t\nA\t\t5216\t\nS\t\t\tvg=1;title=You should now be about 5-10k from level 57\nI\t\tYou should now be about 5-10k from level 57\nS\t\t\tvg=1;title=Go back NE and go over the bridge\nG\t\tWestern Plaguelands\t48.0\t72.0\t\t\t\nI\t\tGo back NE to |cffbbbbbb(48, 72)|r and go over the bridge\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t47.0\t71.0\t\t\t\nI\t\tJust in the town on the left at |cffbbbbbb(47, 71)|r is the 4th tower for |cffffd100All Along the Watchtowers|r, there are elites inside but you can stand out of LOS on the edge and mark the doors easily. 1st tower West of here at |cffbbbbbb(40, 71)|r. 2nd tower NE of here at |cffbbbbbb(42, 66)|r. 3rd tower NE of here at |cffbbbbbb(44, 63)|r. Just behind this tower.\nC\t\t5097\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t37.0\t56.0\t\t\t\nI\t\tGo NW to |cffbbbbbb(37, 56)|r to Felstone field, kill |cff00ff25Cauldron Lord Bilemaw|r for his cauldron key. Then go right click the cauldron and turn in |cffffd100Target: Felstone Field|r accept |cffffd100Return to Chillwind Camp|r\nT\t\t5216\t\nA\t\t5220\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t38.0\t54.0\t\t\t\nI\t\tTheres 2 houses on the NE side of the field at |cffbbbbbb(38, 54)|r, enter the northern house and go upstairs.\nA\t\t5021\t\nS\t\t\tvg=1\nI\t\tGo in the barn next door and grab the box on the floor and turn in |cffffd100Better Late Than Never pt.1|r accept |cffffd100Better Late Than Never pt.2|r\nT\t\t5021\t\nA\t\t5022\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t42.0\t84.0\t\t\t\nI\t\tRun back to Chillwind Camp at |cffbbbbbb(42, 84)|r and turn in |cffffd100All Along the Watchtowers|r, accept |cffffd100Scholomance|r SKIP the other unless you get about 10-20 people.\nT\t\t5097\t\nA\t\t5533\t\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Scholomance|r just behind him, accept |cffffd100Skeletal Fragments Bones|r for this will take a while and drop off any skeletons.\nT\t\t5533\t\nS\t\t\tvg=1\nI\t\tNear the FP turn in |cffffd100Return to Chillwind Camp|r accept |cffffd100Target: Dalson's Tears|r\nT\t\t5220\t\nA\t\t5219\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t46.0\t52.0\t\t\t\nI\t\tGo up to |cffbbbbbb(46, 52)|r to Dalson’Tears, kill |cff00ff25Cauldron Lord Malvinious|r for his cauldron key. Then go right click the cauldron and turn in |cffffd100Target: Dalson's Tears|r accept |cffffd100Return to Chillwind Camp|r\nT\t\t5219\t\nA\t\t5220\t\nS\t\t\tvg=1;title=Enter the barn here and touch the diary on the floor and...\nG\t\tWestern Plaguelands\t47.0\t50.0\t\t\t\nI\t\tEnter the barn here at |cffbbbbbb(47, 50)|r and touch the diary on the floor and complete it, another quest that isn’t a quest.\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t47.0\t49.0\t\t\t\nI\t\tGo behind the barn and look for a Wandering Skeleton and get Dalson Outhouse Key off of him. Use this to open the outhouse back here and kill Farmer Dalson and get his Dalson Cabinet Key. Use the key on the locked cabinet upsairs in the house now at |cffbbbbbb(47, 49)|r next to the barn and complete the quest |cffffd100Locked Away|r\nT\t\t5059\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t42.0\t84.0\t\t\t\nI\t\tGo back to Chillwind Camp at |cffbbbbbb(42, 84)|r and turn in |cffffd100Return to Chillwind Camp|r accept |cffffd100Target: Writhing Haunt|r\nT\t\t5220\t\nA\t\t5222\t\nS\t\t\tvg=1;title=Hearth to IF fly to SW\nI\t\tHearth to IF fly to SW\nS\t\t\tvg=1\nG\t\tStormwind City\t48.0\t30.0\t\t\t\nI\t\tGo to the building at |cffbbbbbb(48, 30)|r on the 2nd floor of the cathedral area and turn in |cffffd100Better Late Than Never pt.2|r accept |cffffd100Good Natured Emma|r\nT\t\t5022\t\nA\t\t5048\t\nS\t\t\tvg=1\nI\t\tEmma travels between the cathedral and the trade district, find her and turn in |cffffd100Good Natured Emma|r accept |cffffd100Good Luck Charm|r\nT\t\t5048\t\nA\t\t5050\t\nS\t\t\tvg=1\nG\t\tStormwind City\t78.0\t17.0\t\t\t\nI\t\tGo into the keep at |cffbbbbbb(78, 17)|r and accept |cffffd100The First and the Last|r\nA\t\t6182\t\nS\t\t\tvg=1\nG\t\tStormwind City\t75.0\t79.0\t\t\t\nI\t\tTurn it right back in, accept |cffffd100Flint Shadowmore|r\nT\t\t6182\t\nA\t\t6183\t\nA\t\t6184\t\nS\t\t\tvg=1;title=Fly back to WPL\nI\t\tFly back to WPL\nS\t\t\tvg=1\nI\t\tIn front of the house turn in |cffffd100Flint Shadowmore|r accept |cffffd100The Eastern Plagues|r\nT\t\t6184\t\nA\t\t6185\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t38.0\t54.0\t\t\t\nI\t\tGo back to Felstone field to the house upstairs at |cffbbbbbb(38, 54)|r and turn in |cffffd100Good Luck Charm|r accept |cffffd100Two Halves Become One|r Go outside and look for a jabbering ghoul. You can’t miss him he carry’s a pitchfork. Keep clearing in front of the house until you find him. This will give you a good time to get those skeletal fragments\nT\t\t5050\t\nA\t\t5051\t\nS\t\t\tvg=1\nI\t\tCombine the halves and go back upstairs and turn in |cffffd100Two Halves Become One|r\nT\t\t5051\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t53.0\t65.0\t\t\t\nI\t\tGo SE to |cffbbbbbb(53, 65)|r to Writhing Haunt, kill |cff00ff25Cauldron Lord Razarch|r for his cauldron key. Then go right click the cauldron and turn in |cffffd100Target: Writhing Haunt|r accept |cffffd100Return to Chillwind Camp|r\nT\t\t5222\t\nA\t\t5220\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t54.0\t65.0\t\t\t\nI\t\tIn the house at |cffbbbbbb(54, 65)|r accept |cffffd100The Wildlife Suffers Too pt.1|r now go north of the haunt and kill the diseased wolves. Don’t go any farther east to find these just go North, maybe NW some.\nA\t\t4984\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t54.0\t65.0\t\t\t\nT\t\t4984\t\nA\t\t4985\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t42.0\t84.0\t\t\t\nI\t\tGo back to Chillwind Camp at |cffbbbbbb(42, 84)|r and turn in |cffffd100Return to Chillwind Camp|r accept |cffffd100Target: Gahrron's Withering|r\nT\t\t5220\t\nA\t\t5225\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t52.0\t56.0\t\t\t\nI\t\tGo just north of the Writhing Haunt between the mountains on the map at, |cffbbbbbb(52, 56)|r and kill diseased grizzleys on your way down to |cffbbbbbb(62, 58)|r for |cffffd100The Wildlife Suffers Too pt.2|r\nC\t\t4985\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t62.0\t58.0\t\t\t\nI\t\tGo NE to |cffbbbbbb(62, 58)|r to Gahrron’s Withering, kill |cff00ff25Cauldron Lord Soulwrath|r for his cauldron key. Then go right click the cauldron and turn in |cffffd100Target: Gahrron's Withering|r accept |cffffd100Return to Chillwind Camp|r\nT\t\t5225\t\nA\t\t5220\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t54.0\t65.0\t\t\t\nT\t\t4985\t\nA\t\t4986\t\nS\t\t\tvg=1;title=If you haven’t finished Skeletal Fragments yet go to the crypt...\nG\t\tWestern Plaguelands\t54.0\t79.0\t\t\t\nI\t\tIf you haven’t finished Skeletal Fragments yet go to the crypt at |cffbbbbbb(54, 79)|r and kill the skeletons until you have 15 fragments\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t42.0\t84.0\t\t\t\nI\t\tGo back to Chillwind Camp at |cffbbbbbb(42, 84)|r and turn in |cffffd100Return to Chillwind Camp|r\nT\t\t5220\t\nS\t\t\tvg=1\nI\t\tTurn around to the guy in front of the tent, and complete the quest |cffffd100Mission Accomplished!|r no link for it cuz it’s not a quest again lol. Now see that running back and forth seemed out of the way but there was a huge xp boost at the end, and nice xp throughout.\nT\t\t5237\t\nS\t\t\tvg=1\nI\t\tTo your right turn in |cffffd100Skeletal Fragments|r SKIP the next part unless you want to start on your scholo key.\nT\t\t5537\t\nS\t\t\tvg=1;title=Run east and enter the Eastern Plaguelands (EPL)\nG\t\tWestern Plaguelands\t70.0\t50.0\t\t\t\nI\t\tRun east to |cffbbbbbb(70, 50)|r and enter the Eastern Plaguelands (EPL)" },
  { name = "57-58 Eastern Plaguelands (Alliance)", title = "57-58 Eastern Plaguelands", group = "VanillaGuide 40-60", faction = "Alliance", lo = 57, hi = 58, next = "58-58 Western Plaguelands (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tEastern Plaguelands\t67.0\t4.0\t\t\t\nI\t\tRun up the west coast to 67,4 and accept the 3 quests |cffffd100Demon Dogs|r |cffffd100Blood Tinged Skies|r and |cffffd100Carrion Grubbage|r\nA\t\t5542\t\nA\t\t5543\t\nA\t\t5544\t\nS\t\t\tvg=1;title=These are annoying quests that can take a while\nI\t\tThese are annoying quests that can take a while. Anytime from now until these are done, kill any plaguehound runts, carrion worms, or plaguebats.\nS\t\t\tvg=1;title=From here on down to the bigger area, kill any dogs, worms, and...\nI\t\tFrom here on down to the bigger area, kill any dogs, worms, and bats. Focus on them while you head to the next step\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t28.0\t74.0\t\t\t\nI\t\tKeep killing the dogs and bats and head over to the skeleton at |cffbbbbbb(28, 74)|r open it and grab the insignia for |cffffd100The Eastern Plagues|r then run up a bit further to the next skeleton at |cffbbbbbb(27, 74)|r and grab the insignia, it’s practically right in front of him and you will also get the blightcaller found complete message. Now go down near the road to |cffbbbbbb(28, 79)|r and loot the last insignia off the skeleton\nC\t\t6185\t\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t36.0\t90.0\t\t\t\nI\t\tFocus on the dogs and bats while you head to Darrowshire at |cffbbbbbb(36, 90)|r in the broken down house.\nT\t\t5601\t\nA\t\t5149\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t36.0\t90.0\t\t\t\nI\t\tHead towards the houses here, in any of the houses can be any of the 3 doll parts. They are random. Ghosts spawn when you get near the parts so be aware. Once you have all 3 parts combine them and go back to |cffbbbbbb(36, 90)|r and turn in |cffffd100Pamela's Doll|r\nT\t\t5149\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t36.0\t90.0\t\t\t\nA\t\t5152\t\nA\t\t5241\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t48.0\t76.0\t\t\t\nI\t\tLook on your map at |cffbbbbbb(48, 76)|r This lines up with that middle ridge mountain. Don’t go past this spot east until you have your plaguehound runt kills for |cffffd100Demon Dogs|r and plaguebats for |cffffd100Blood Tinged Skies|r because there is none past that point.\nC\t\t5542\t\t\nC\t\t5543\t\t\nS\t\t\tvg=1\nI\t\tDon’t forget to kill the grubs along the way too for |cffffd100Carrion Grubbage|r, they’re not as important because they’re all over.\nC\t\t5544\t\t\nS\t\t\tvg=1;title=Kill Plaguehounds for Demon Dogs all this is north of the scar...\nG\t\tEastern Plaguelands\t56.0\t57.0\t\t\t\nI\t\tKill Plaguehounds for Demon Dogs all around |cffbbbbbb(56, 57)|r this is north of the scar and south of blackwood lake. Don’t forget the grubs\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t61.0\t41.0\t\t\t\nI\t\tKill Frenzied Plaguehounds for |cffffd100Demon Dogs|r all around |cffbbbbbb(61, 41)|r this is north of blackwood lake but now west of it.\nC\t\t5542\t\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t81.0\t58.0\t\t\t\nI\t\tHead to lights hope chapel at |cffbbbbbb(81, 58)|r if you still need grub meat for |cffffd100Carrion Grubbage|r, then kill them as you\nC\t\t5544\t\t\nS\t\t\tvg=1;title=Get the FP\nI\t\tGet the FP\nS\t\t\tvg=1\nT\t\t5241\t\nA\t\t5211\t\nS\t\t\tvg=1\nT\t\t6030\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t79.0\t63.0\t\t\t\nA\t\t6021\t\nS\t\t\tvg=1;title=Fly back to EPL\nI\t\tFly back to EPL\nS\t\t\tvg=1\nI\t\tIn front of the house turn in |cffffd100The Eastern Plagues|r accept |cffffd100The Blightcaller Cometh|r\nT\t\t6185\t\nA\t\t6186\t\nS\t\t\tvg=1;title=Go get new skills\nI\t\tGo get new skills\nS\t\t\tvg=1;title=If you’re within 6,600 to level Hearth to IF and fly to SW, if...\nI\t\tIf you’re within 6,600 to level Hearth to IF and fly to SW, if not grind until you’re within range.\nS\t\t\tvg=1;title=Fly back to WPL\nI\t\tFly back to WPL\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t78.0\t18.0\t\t\t\nI\t\tGo to |cffbbbbbb(78, 18)|r in the keep and turn in |cffffd100The Blightcaller Cometh|r now I SKIP the next part but it’s a good quest to do at 60\nT\t\t6186\t" },
  { name = "58-58 Western Plaguelands (Alliance)", title = "58-58 Western Plaguelands", group = "VanillaGuide 40-60", faction = "Alliance", lo = 58, hi = 58, next = "58-58 Eastern Plaguelands (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tEastern Plaguelands\t36.0\t90.0\t\t\t\nC\t\t5152\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t49.0\t78.0\t\t\t\nI\t\tGo NE to the house at |cffbbbbbb(49, 78)|r and go upstairs.\nT\t\t5152\t\nT\t\t5149\t\nA\t\t5153\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t49.0\t76.0\t\t\t\nI\t\tJust north of the house at |cffbbbbbb(49, 76)|r you’ll see an off color gravestone. Loot it and get the wedding ring for |cffffd100A Strange Historian|r\nC\t\t5153\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t39.0\t68.0\t\t\t\nI\t\tGo in the west entrance to Andorhal at |cffbbbbbb(39, 71)|rand you should see the only full building, looks like an Inn at |cffbbbbbb(39, 68)|r. Go upstairs and turn in |cffffd100A Strange Historian|r accept |cffffd100The Annals of Darrowshire|r also accept |cffffd100A Matter of Time|r\nT\t\t5153\t\nA\t\t5154\t\nA\t\t4971\t\nS\t\t\tvg=1\nI\t\tNow look all around the city here for busted up silo’s with a blue light coming out of them. Use the silo horn to summon the worms, it spawns 1-3 mobs for |cffffd100A Matter of Time|r. Once you kill the last one they have a tendency to spawn another. They’re more on the East side of town\nC\t\t4971\t\t\nS\t\t\tvg=1\nI\t\tGo to the Town Hall near all the mobs in the middle of town, you can sneak in from the SW side. Grab the books on the floor until you get the |cffffd100The Annals of Darrowshire|r Some will spawn mobs\nA\t\t5154\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t39.0\t68.0\t\t\t\nI\t\tGo back to the Inn at |cffbbbbbb(39, 68)|r and to the top floor, turn in |cffffd100A Matter of Time|r accept |cffffd100Counting Out Time|r also turn in |cffffd100The Annals of Darrowshire|r accept |cffffd100Brother Carlin|r\nT\t\t4971\t\nA\t\t4972\t\nT\t\t5154\t\nA\t\t5210\t\nS\t\t\tvg=1\nI\t\tGo outside and look around the busted houses for little metal lunchboxes for |cffffd100Counting Out Time|r\nC\t\t4972\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t39.0\t68.0\t\t\t\nI\t\tGo back to the Inn at |cffbbbbbb(39, 68)|r and turn in |cffffd100Counting Out Time|r you can now repeat this quest for a dampener. This is used vs the 61 elite\nT\t\t4972\t" },
  { name = "58-58 Eastern Plaguelands (Alliance)", title = "58-58 Eastern Plaguelands", group = "VanillaGuide 40-60", faction = "Alliance", lo = 58, hi = 58, next = "58-59 Western Plaguelands (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tEastern Plaguelands\t7.0\t43.0\t\t\t\nI\t\tRun out of here and into EPL up to the NW at 7,43 and turn in the 3 quests |cffffd100Demon Dogs|r |cffffd100Blood Tinged Skies|r and |cffffd100Carrion Grubbage|r accept |cffffd100Redemption|r listen to him and turn it back in.\nT\t\t5542\t\nT\t\t5543\t\nT\t\t5544\t\nA\t\t5742\t\nA\t\t5781\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t28.0\t86.0\t\t\t\nI\t\tGo to the Undercroft at |cffbbbbbb(28, 86)|r and run behind it. Touch the dirt pile to summon Mercutio and 3 guards. Easiest way to do this is to kite him away from his buddies or get a group. Loot his body for the hammer for |cffffd100Of Forgotten Memories|r\nC\t\t5781\t\t\nS\t\t\tvg=1\nI\t\tNow go to the bottom of the crypt and kill the very big troll for |cffffd100Zaeldarr the Outcast|r Only grab the scroll on the floor if u want\nC\t\t6021\t\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t7.0\t43.0\t\t\t\nT\t\t5781\t\nA\t\t5845\t\nS\t\t\tvg=1;title=Either Run to Light’s Hope Chapel or back to Chillwind and fly...\nI\t\tEither Run to Light’s Hope Chapel or back to Chillwind and fly there\nS\t\t\tvg=1\nT\t\t5210\t\nA\t\t5181\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t79.0\t63.0\t\t\t\nT\t\t6021\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t53.0\t65.0\t\t\t\nI\t\tGo down just North of Corin’s Crossing to |cffbbbbbb(53, 65)|r and grab the sword for |cffffd100Villains of Darrowshire|r It’s down in the scar. Don’t forget to do some of |cffffd100Defenders of Darrowshire|r at Corin’s Just get what you can\nC\t\t5181\t\t\nC\t\t5211\t\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t51.0\t49.0\t\t\t\nI\t\tGo north to Blackwood Lake at |cffbbbbbb(51, 49)|r and grab the skull under the water for |cffffd100Villains of Darrowshire|r\nC\t\t5181\t\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t65.0\t41.0\t\t\t\nI\t\tGo NE to around |cffbbbbbb(65, 41)|r and kill the zombies for part of |cffffd100Defenders of Darrowshire|r there are quite a lot here you could probably finish\nC\t\t5211\t\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t71.0\t33.0\t\t\t\nI\t\tGo to the lake at |cffbbbbbb(71, 33)|r and grab the flag next to the cage, it’s hard to see and is laying flat for |cffffd100Of Lost Honor|r\nC\t\t5845\t\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t56.0\t24.0\t\t\t\nI\t\tGo NW to the tower at |cffbbbbbb(56, 24)|r and turn in |cffffd100Troubled Spirits of Kel'Theril|r SKIP the next part\nT\t\t5245\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t45.0\t34.0\t\t\t\nI\t\tRun West to |cffbbbbbb(45, 34)|r and loot the termite mounds here for |cffffd100A Plague Upon Thee pt.1|r until you get 100 termites, also kill ghouls to finish up |cffffd100Defenders of Darrowshire|r\nC\t\t5903\t\t\nC\t\t5211\t\t\nS\t\t\tvg=1;title=Run to Lights Hope Chapel now\nI\t\tRun to Lights Hope Chapel now\nS\t\t\tvg=1\nI\t\tGo by the tent and turn in |cffffd100Defenders of Darrowshire|r and |cffffd100Villains of Darrowshire|r\nT\t\t5211\t\nT\t\t5181\t\nS\t\t\tvg=1;title=Fly to WPL\nI\t\tFly to WPL\nS\t\t\tvg=1\nI\t\tNext to the house turn in |cffffd100A Plague Upon Thee pt.1|r accept |cffffd100A Plague Upon Thee pt.2|r\nT\t\t5903\t\nA\t\t5904\t" },
  { name = "58-59 Western Plaguelands (Alliance)", title = "58-59 Western Plaguelands", group = "VanillaGuide 40-60", faction = "Alliance", lo = 58, hi = 59, next = "59-60 Winterspring (Alliance)", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tWestern Plaguelands\t52.0\t30.0\t\t\t\nI\t\tRun up to |cffbbbbbb(51, 28)|r and accept |cffffd100Unfinished Business pt.1|r\nA\t\t6004\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t47.0\t32.0\t\t\t\nI\t\tStart heading back SW around |cffbbbbbb(47, 32)|r and clear your way into the mill. Right click the box and place the termintes click the barrel and turn in |cffffd100A Plague Upon Thee pt.2|r accept |cffffd100A Plague Upon Thee pt.3|r\nT\t\t5904\t\nA\t\t6389\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t49.0\t42.0\t\t\t\nI\t\tGo just south of |cffbbbbbb(49, 42)|r and kill 2 knights and mages for |cffffd100Unfinished Business pt.1|r then |cffbbbbbb(51, 43)|r for the hunters and medics\nC\t\t6004\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t51.0\t28.0\t\t\t\nT\t\t6004\t\nA\t\t6023\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t57.0\t36.0\t\t\t\nI\t\tGo to |cffbbbbbb(57, 36)|r and kill Huntsman Radly for |cffffd100Unfinished Business pt.2|r then north to the tower at |cffbbbbbb(55, 23)|r and kill Cavalier Durgen at the top\nC\t\t6023\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t45.0\t18.0\t\t\t\nI\t\tGo straight out of the tower over the mountains to |cffbbbbbb(51, 28)|r and turn in |cffffd100Unfinished Business pt.2|r doing the 3rd part |cffffd100Unfinished Business pt.3|r is optional. Some classes can do it easier than others. You have to run north to hearthglen and run up into the big tower in the center of town at |cffbbbbbb(45, 18)|r and look over the edge until it says complete.\nT\t\t6023\t\nC\t\t6025\t\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t51.0\t28.0\t\t\t\nI\t\tRun back straight south over the mountains to |cffbbbbbb(51, 28)|r and turn in |cffffd100Unfinished Business pt.3|r\nT\t\t6025\t\nS\t\t\tvg=1\nG\t\tEastern Plaguelands\t7.0\t43.0\t\t\t\nI\t\tRun into EPL and up to 7,43 and turn in |cffffd100Of Lost Honor|r accept |cffffd100Of Love and Family pt.1|r\nT\t\t5845\t\nA\t\t5846\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t65.0\t75.0\t\t\t\nI\t\tGo back to WPL and run/swim to the island Scholo is on at |cffbbbbbb(65, 75)|r and turn in |cffffd100Of Love and Family pt.1|r SKIP the rest until you do strat\nT\t\t5846\t\nS\t\t\tvg=1\nG\t\tWestern Plaguelands\t43.0\t84.0\t\t\t\nI\t\tGo back to Chillwind Camp at |cffbbbbbb(43, 84)|r and turn in |cffffd100A Plague Upon Thee pt.3|r\nT\t\t6389\t\nS\t\t\tvg=1\nI\t\tNow you want to do 2 things here. Get friendly with Argent Dawn and get 8-8.5k from leveling. You can do |cffffd100Alas, Andorhal|r if you can find a group, it’s not that hard but can take 5-10 people. This will give you an easy 8300 xp instead of grinding.\nC\t\t211\t\t\nS\t\t\tvg=1;title=Now you want to go up to andorhal and just grind until you’re...\nI\t\tNow you want to go up to andorhal and just grind until you’re friendly, once you’re friendly go back to Chillwind Camp and turn in all your scourge tokens. This allows you to buy mana biscuits which restore mana and health and more than food can. If you still need to level go grind on mobs in andorhal again until you’re 8-8.5k from level 59\nS\t\t\tvg=1\nG\t\tThe Hinterlands\t80.0\t46.0\t\t\t\nI\t\tOnce you’re 8k-8.5k from leveling, fly to Hinterlands and run all the way NE to the waterfall at |cffbbbbbb(80, 46)|r and jump off. Under the water loot the chest and finish |cffffd100Cortello’s Riddle pt.3|r\nC\t\t626\t\t\nS\t\t\tvg=1;title=Hearth to IF\nI\t\tHearth to IF\nS\t\t\tvg=1\nG\t\tIronforge\t43.0\t52.0\t\t\t\nI\t\tGo to the throne room at |cffbbbbbb(43, 52)|r and accept |cffffd100An Earnest Proposition|r (pick your class from the list) You have to have your classes tier 0 bracers in order to do this quest. You can buy it on AH\nA\tDruid\t8905\t\nS\t\t\tvg=1;title=Fly to Menethil and sail to Auberdine, fly to Darnassus\nI\t\tFly to Menethil and sail to Auberdine, fly to Darnassus\nS\t\t\tvg=1\nG\t\tDarnassus\t35.0\t8.0\t\t\t\nI\t\tGo to 35,8 on the 2nd floor and turn in |cffffd100Glyphed Oaken Branch|r\nT\t\t4986\t\nS\t\t\tvg=1;title=You should be level 59, fly to Winterspring\nI\t\tYou should be level 59, fly to Winterspring" },
  { name = "59-60 Winterspring (Alliance)", title = "59-60 Winterspring", group = "VanillaGuide 40-60", faction = "Alliance", lo = 59, hi = 60, next = "", defaultFor = "", cond = "Alliance", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tOn your left after entering turn in |cffffd100Are We There, Yeti? pt.3|r\nT\t\t5163\t\nS\t\t\tvg=1\nI\t\tNear the back are 2 horde, accept |cffffd100Luck Be With You|r\nA\t\t969\t\nS\t\t\tvg=1\nT\t\t4808\t\nA\t\t4809\t\nS\t\t\tvg=1\nI\t\tDo |cffffd100An Earnest Proposition|r just kill the sabers until you have 15 blood\nC\tDruid\t8905\t\t\nS\t\t\tvg=1\nG\t\tWinterspring\t55.0\t18.0\t\t\t\nI\t\tGo just SE of here around |cffbbbbbb(55, 18)|r and kill the chimera’s for |cffffd100Chillwind Horns|r\nC\t\t4809\t\t\nS\t\t\tvg=1\nG\t\tWinterspring\t52.0\t30.0\t\t\t\nI\t\tRun to Starfall Village at |cffbbbbbb(52, 30)|r and accept |cffffd100Enraged Wildkin pt.1|r\nA\t\t6604\t\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Chillwind Horns|r SKIP the other unless you want to go there\nT\t\t4809\t\nS\t\t\tvg=1\nG\t\tWinterspring\t59.0\t59.0\t\t\t\nI\t\tGo south to |cffbbbbbb(59, 59)|r and touch the crate and turn in |cffffd100Enraged Wildkin pt.1|r accept |cffffd100Enraged Wildkin pt.2|r\nT\t\t6604\t\nA\t\t4861\t\nS\t\t\tvg=1\nG\t\tWinterspring\t61.0\t60.0\t\t\t\nI\t\tGo back to the roat at |cffbbbbbb(61, 60)|r and touch the wagon, turn in |cffffd100Enraged Wildkin pt.2|r accept |cffffd100Enraged Wildkin pt.3|r grab the box in the snow\nT\t\t4861\t\nA\t\t4863\t\nS\t\t\tvg=1\nG\t\tWinterspring\t63.0\t59.0\t\t\t\nT\t\t979\t\nA\t\t4901\t\nS\t\t\tvg=1\nI\t\tNow protect her while she does her thing. Make sure you get the feather off an owl for |cffffd100Enraged Wildkin pt.3|r When she stops in a cave, light the torch for her. If you don’t get the feather before you’re done keep killing until you got it.\nC\t\t4863\t\t\nS\t\t\tvg=1\nG\t\tWinterspring\t62.0\t69.0\t\t\t\nI\t\tGo south to |cffbbbbbb(62, 69)|r and loot the gems for |cffffd100Luck Be With You|r hunters and locks can use pet to distract mobs while you loot, other classes will have to group.\nC\t\t969\t\t\nS\t\t\tvg=1;title=Hearth to Everlook\nI\t\tHearth to Everlook\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Luck Be With You|r at the 2 horde near the back of everlook\nT\t\t969\t\nS\t\t\tvg=1;title=You should be about 25% into level 59 now\nI\t\tYou should be about 25% into level 59 now.\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Cache of Mau'Ari|r if you want to. This just gives you an item which allows the mobs here to drop stuff which you can turn in for buffs\nA\t\t975\t\nS\t\t\tvg=1\nG\t\tWinterspring\t52.0\t30.0\t\t\t\nI\t\tGo up to Starfall Village at |cffbbbbbb(52, 30)|r and turn in |cffffd100Enraged Wildkin pt.3|r\nT\t\t4863\t\nS\t\t\tvg=1\nG\t\tWinterspring\t31.0\t45.0\t\t\t\nT\t\t5085\t\nA\t\t5086\t\nS\t\t\tvg=1\nG\t\tFelwood\t48.0\t24.0\t\t\t\nI\t\tRun into Felwood and go to |cffbbbbbb(48, 24)|r and kill toxic horrors for |cffffd100Toxic Horrors|r these also drop essence of waters\nC\t\t5086\t\t\nS\t\t\tvg=1\nG\t\tTeldrassil\t55.0\t92.0\t\t\t\nI\t\tFly to Rut’theran Village and go to the house at |cffbbbbbb(55, 92)|r and turn in |cffffd100Guardians of the Altar|r accept |cffffd100Wildkin of Elune|r\nT\t\t4901\t\nA\t\t4902\t\nS\t\t\tvg=1\nG\t\tDarnassus\t34.0\t8.0\t\t\t\nI\t\tGo in Darnassus and up to the top of the tower at 34,8 and turn in |cffffd100Wildkin of Elune|r\nT\t\t4902\t\nS\t\t\tvg=1;title=Fly back to Felwood\nI\t\tFly back to Felwood\nS\t\t\tvg=1\nG\t\tWinterspring\t31.0\t45.0\t\t\t\nI\t\tRun back up into Winterspring and over to |cffbbbbbb(31, 45)|r turn in |cffffd100Toxic Horrors|r accept |cffffd100Winterfall Runners|r\nT\t\t5086\t\nA\t\t5087\t\nS\t\t\tvg=1;title=Now to find the runners\nG\t\tWinterspring\t53.0\t34.0\t\t\t\nI\t\tNow to find the runners. They travel anywhere from the Timbermaw Cave east to |cffbbbbbb(53, 34)|r up around the mountains north of everlook over to Winterfall Village. If you didn’t see them from the cave to here, head east. You don’t have to kill all 3\nS\t\t\tvg=1;title=Once you get the crate run back Turn in Winterfall Runners an...\nG\t\tWinterspring\t31.0\t45.0\t\t\t\nI\t\tOnce you get the crate run back to |cffbbbbbb(31, 45)|r Turn in Winterfall Runners an ambush will come from the lake, if you don’t move from the tent they won’t aggro you. SKIP the next part unless you get a group\nS\t\t\tvg=1;title=Hearth to Everlook\nI\t\tHearth to Everlook\nS\t\t\tvg=1;title=You should be 45-50% through level 59\nG\t\tWinterspring\t64.0\t62.0\t\t\t\nI\t\tYou should be 45-50% through level 59. Now I make sure I got my mana bisquits and I start grinding until im 6600 to level 60. Anywhere is fine where there is a lot of mobs It’s all a matter of preference. I choose the owl wing thicket at |cffbbbbbb(64, 62)|r or anything north of everlook. I like to kill the furlbogs for timbermaw rep also.\nS\t\t\tvg=1;title=If you don’t want to grind this large amount do BRD, scholo, or...\nI\t\tIf you don’t want to grind this large amount do BRD, scholo, or strat. You have a lot of quests in those spots to do\nS\t\t\tvg=1\nI\t\tOnce you’re 6600 to 60 go to IF and turn in |cffffd100An Earnest Proposition|r\nT\tDruid\t8905\t\nS\t\t\tvg=1;title=Grats on 60!\nI\t\tGrats on 60!" },
  { name = "1-6 Durotar (Horde)", title = "1-6 Durotar", group = "VanillaGuide 1-20", faction = "Horde", lo = 1, hi = 6, next = "6-9 Durotar (Horde)", defaultFor = "Orc/Troll", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=I do every single quest in Durotar!\nI\t\tI do every single quest in Durotar! Here's the fastest way to do em:\nS\t\t\tvg=1\nI\t\tStart off accepting |cffffd100Your Place In The World|r . (Right in front of you)\nA\t\t4641\t\nS\t\t\tvg=1\nI\t\tThen turn it in at COORD|cffbbbbbb(42, 68)|r ...\nA\t\t788\t\nS\t\t\tvg=1\nI\t\tGo start doing: |cffffd100Cutting Teeth|r (keep step 5 in mind)\nC\t\t788\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t40.0\t62.0\t\t\t\nI\t\tOnce you hit level 2, go accept |cffffd100Sarkoth|r at |cffbbbbbb(40, 62)|r\nA\t\t790\t\nS\t\t\tvg=1\nG\t\tDurotar\t40.0\t66.0\t\t\t\nI\t\tGo do |cffffd100Sarkoth|r at |cffbbbbbb(40, 66)|r.\nC\t\t790\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t40.0\t62.0\t\t\t\nI\t\tAccept |cffffd100Sarkoth|r pt.2\nT\t\t790\t\nA\t\t790\t\nS\t\t\tvg=1\nI\t\tMake sure |cffffd100Cutting Teeth|r is complete.\nC\t\t788\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t42.0\t68.0\t\t\t\nI\t\tGo turn in |cffffd100Sarkoth|r pt.2 and |cffffd100Cutting Teeth|r at |cffbbbbbb(42, 68)|r ...\nT\t\t790\t\nT\t\t788\t\nA\tHunter\t3082\t\nA\t\t789\t\nS\t\t\tvg=1\nG\t\tDurotar\t43.0\t69.0\t\t\t\nI\t\tTurn in |cffffd100Etched Tablet|r, around |cffbbbbbb(43, 69)|r, and get new spells/abilities for your class.\nA\tHunter\t3082\t\nS\t\t\tvg=1\nI\t\tThen accept and do the following: |cffffd100Sting of the Scorpid|r |cffffd100Vile Familiars|r |cffffd100Galgar's Cactus Apple Surprise|r and |cffffd100Lazy Peons|r (all these are done north and north-east of Valley of Trials)\nC\t\t789\t\t\nC\t\t792\t\t\nC\t\t4402\t\t\nC\t\t5441\t\t\nS\t\t\tvg=1\nA\t\t794\t\nA\t\t6394\t\nS\t\t\tvg=1\nG\t\tDurotar\t44.0\t56.0\t\t\t\nI\t\tGo do |cffffd100Burning Blade Medallion|r and |cffffd100Thazz'ril's Pick|r, these are done in the cave at |cffbbbbbb(44, 56)|r\nC\t\t794\t\t\nC\t\t6394\t\t\nS\t\t\tvg=1;title=Once those two quests are done use your hearthstone\nI\t\tOnce those two quests are done use your hearthstone.\nS\t\t\tvg=1\nT\t\t794\t\nA\t\t805\t\nS\t\t\tvg=1;title=The starting area is now completed\nI\t\tThe starting area is now completed. Leave starting noob zone (by heading east)." },
  { name = "6-9 Durotar (Horde)", title = "6-9 Durotar", group = "VanillaGuide 1-20", faction = "Horde", lo = 6, hi = 9, next = "9-12 Durotar (Horde)", defaultFor = "Orc/Troll", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tDurotar\t52.0\t68.0\t\t\t\nA\t\t2161\t\nS\t\t\tvg=1\nG\t\tDurotar\t54.0\t75.0\t\t\t\nA\t\t786\t\nS\t\t\tvg=1\nG\t\tDurotar\t55.0\t74.0\t\t\t\nI\t\tGo turn in |cffffd100Report to Sen'jin Village|r at Sen'jen Village, |cffbbbbbb(55, 74)|r\nT\t\t805\t\nS\t\t\tvg=1\nI\t\tThen collect all the quests in Sen'jin Village. (which include: |cffffd100A solvent Spirit|r |cffffd100Practical Prey|r |cffffd100Minshina's Skull|r |cffffd100Report to Orgnil|r and |cffffd100Zalazane|r )\nA\t\t818\t\nA\t\t817\t\nA\t\t808\t\nA\t\t823\t\nA\t\t826\t\nS\t\t\tvg=1;title=Do NOT do A solvent Spirit at the water around Sen'jin Village\nI\t\tDo NOT do |cff00ff25A solvent Spirit|r at the water around Sen'jin Village. Make sure the quest is accepted though.\nS\t\t\tvg=1;title=Run up to Razor Hill , grinding mobs along the way, and make...\nG\t\tDurotar\t52.0\t44.0\t\t\t\nI\t\tThen run up to Razor Hill |cffbbbbbb(52, 44)|r, grinding mobs along the way, and make sure you get to level 6 before you get up there for new spells.\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Report to Orgnil|r and collect all the quests at Razor Hill (|cffffd100Dark Storms|r |cffffd100Vanquish the Betrayers|r , |cffffd100Encroachment|r |cffffd100Break a Few Eggs|r\nT\t\t823\t\nA\t\t806\t\nA\t\t784\t\nA\t\t837\t\nA\t\t815\t\nS\t\t\tvg=1\nG\t\tDurotar\t49.0\t40.0\t\t\t\nI\t\tGo up to the watch tower north-west of Razor Hill, at |cffbbbbbb(49, 40)|r and accept |cffffd100Carry Your Weight|r\nA\t\t791\t\nS\t\t\tvg=1\nG\t\tDurotar\t51.0\t41.0\t\t\t\nI\t\tGo in the Inn |cffbbbbbb(51, 41)|r and turn in |cffffd100A Peon's Burden|r . And also make Razor Hill your home.\nT\t\t2161\t\nS\t\t\tvg=1;title=Get first aid\nG\t\tDurotar\t51.0\t41.0\t\t\t\nI\t\tGet first aid. at |cffbbbbbb(54, 41)|r\nS\t\t\tvg=1\nG\t\tDurotar\t57.0\t55.0\t\t\t\nI\t\tThen go do this: |cffffd100Vanquish the Betrayers|r along with |cffffd100Carry Your Weight|r. These are done at Tiragarde Keep, |cffbbbbbb(57, 55)|r\nC\t\t784\t\t\nC\t\t791\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t59.0\t58.0\t\t\t\nI\t\tAfter killing Benedict (he is up in the building at |cffbbbbbb(59, 58)|r), get his key, go up the steps, open the chest and grab the note that starts: |cffffd100The Admiral's Orders|r accept the quest.\nA\t\t831\t\nS\t\t\tvg=1\nG\t\tDurotar\t52.0\t44.0\t\t\t\nI\t\tGo turn in |cffffd100Vanquish the Betrayers|r |cffffd100The Admiral's Orders|r and |cffffd100Carry Your Weight|r at Razor Hill |cffbbbbbb(52, 44)|r, and accept |cffffd100From The Wreckage....|r |cffffd100The Admiral's Orders|r (part2).\nT\t\t784\t\nT\t\t831\t\nT\t\t791\t\nA\t\t825\t\nA\t\t831\t\nS\t\t\tvg=1\nG\t\tDurotar\t62.0\t50.0\t\t\t\nI\t\tGo do |cffffd100A solvent Spirit|r and |cffffd100From The Wreckage....|r Do these two quests at the water east of Tiragarde Keep, around |cffbbbbbb(62, 50)|r.\nC\t\t818\t\t\nC\t\t825\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t49.0\t49.0\t\t\t\nI\t\tThen do the first half of |cffffd100Encroachment|r at |cffbbbbbb(49, 49)|r.\nC\t\t837\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t52.0\t44.0\t\t\t\nI\t\tThen if you're not at least 3 bars away from lvl 8, grind till you are, go turn in |cffffd100From The Wreckage....|r at Razor Hill |cffbbbbbb(52, 44)|r and get new spells/abilities.\nT\t\t825\t\nS\t\t\tvg=1\nG\t\tDurotar\t48.0\t79.0\t\t\t\nI\t\tRun way down south and do |cffffd100Thwarting Kolkar Aggression|r at |cffbbbbbb(48, 79)|r\nC\t\t786\t\t\nS\t\t\tvg=1;title=Once that is done turn it in\nG\t\tDurotar\t54.0\t75.0\t\t\t\nI\t\tOnce that is done turn it in at |cffbbbbbb(54, 75)|r.\nS\t\t\tvg=1\nG\t\tDurotar\t55.0\t74.0\t\t\t\nI\t\tTurn in |cffffd100A solvent Spirit|r at Sen'jin |cffbbbbbb(55, 74)|r\nT\t\t818\t\nS\t\t\tvg=1;title=Go to Echo Isles (the islands south-east of Durotar) and do the...\nI\t\tThen go to Echo Isles (the islands south-east of Durotar) and do the following 4 quests together:\nS\t\t\tvg=1\nI\t\t|cffffd100Break a Few Egg|r\nC\t\t815\t\t\nS\t\t\tvg=1\nI\t\t|cffffd100Practical Prey|r\nC\t\t817\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t67.0\t87.0\t\t\t\nI\t\t|cffffd100Minshina's Skull|r at |cffbbbbbb(67, 87)|r\nC\t\t808\t\t\nS\t\t\tvg=1\nI\t\t|cffffd100Zalazane|r at |cffbbbbbb(67, 86)|r.\nC\t\t826\t\t\nS\t\t\tvg=1;title=After completing all these quests, die on purpose, so you end...\nG\t\tDurotar\t55.0\t74.0\t\t\t\nI\t\tAfter completing all these quests, die on purpose, so you end up right at Sen'jin Village |cffbbbbbb(55, 74)|r...\nS\t\t\tvg=1\nI\t\tSave the quest reward item |cff00ff25Faintly Glowing Skull|r for a later quest called |cff00ff25Burning Shadows|r\nT\t\t817\t\nT\t\t808\t\nT\t\t826\t\nS\t\t\tvg=1\nI\t\tHearth to Razor Hill.\nT\t\t815\t\nS\t\t\tvg=1\nG\t\tDurotar\t42.0\t38.0\t\t\t\nI\t\tThen do the second half of |cffffd100Encroachment|r (west of Razor Hill, at |cffbbbbbb(42, 38)|r)\nC\t\t837\t\t" },
  { name = "9-12 Durotar (Horde)", title = "9-12 Durotar", group = "VanillaGuide 1-20", faction = "Horde", lo = 9, hi = 12, next = "12-15 Barrens (Horde)", defaultFor = "Orc/Troll", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tDurotar\t43.0\t30.0\t\t\t\nI\t\tThen go up and accept |cffffd100Lost But Not Forgotten|r at the little hut at |cffbbbbbb(43, 30)|r\nA\t\t816\t\nS\t\t\tvg=1\nG\t\tDurotar\t46.0\t22.0\t\t\t\nI\t\tThen go up (grind mobs along the way) and accept |cffffd100Winds in the Desert|r at the goblin, |cffbbbbbb(46, 22)|r.\nA\t\t834\t\nS\t\t\tvg=1\nI\t\tThen do |cffffd100Winds in the Desert|r\nC\t\t834\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t46.0\t22.0\t\t\t\nT\t\t834\t\nA\t\t835\t\nS\t\t\tvg=1;title=Grind mobs to lvl 10\nI\t\tGrind mobs to lvl 10.\nS\t\t\tvg=1\nG\t\tDurotar\t52.0\t44.0\t\t\t\nI\t\tGo down to razor hill |cffbbbbbb(52, 44)|r, turn in |cffffd100Encroachment|r\nT\t\t837\t\nS\t\t\tvg=1;title=Get new spells/abilities\nI\t\tGet new spells/abilities.\nS\t\t\tvg=1;title=Do your level 10 class quests\nI\t\tDo your level 10 class quests.\nS\t\t\tvg=1\nG\t\tDurotar\t41.0\t18.0\t\t\t\nI\t\tThen go way west (grinding mobs along the way) and accept |cffffd100Need for a Cure|r at |cffbbbbbb(41, 18)|r\nA\t\t812\t\nS\t\t\tvg=1;title=Go to Orgrimmar\nG\t\tDurotar\t45.0\t11.0\t\t\t\nI\t\tGo to Orgrimmar at |cffbbbbbb(45, 11)|r\nS\t\t\tvg=1\nG\t\tOrgrimmar\t34.0\t36.0\t\t\t\nI\t\tThen turn in |cffffd100The Admiral's Orders|r in thrall's chamber |cffbbbbbb(34, 36)|r\nT\t\t830\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Hidden Enemies|r (Thrall gives it)\nA\t\t5726\t\nS\t\t\tvg=1\nG\t\tDurotar\t41.0\t18.0\t\t\t\nC\t\t812\t\t\nS\t\t\tvg=1\nG\t\tOrgrimmar\t46.0\t53.0\t\t\t\nI\t\tGo into Cleft of Shadow, accept |cffffd100Finding the Antidote|r |cffbbbbbb(46, 53)|r\nT\t\t812\t\nA\t\t813\t\nS\t\t\tvg=1\nG\t\tDurotar\t53.0\t23.0\t\t\t\nI\t\tThen go do |cffffd100Securing the Lines|r at |cffbbbbbb(53, 23)|r in Durotar\nC\t\t835\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t46.0\t22.0\t\t\t\nT\t\t835\t\nS\t\t\tvg=1\nI\t\tThen go do |cffffd100Finding the Antidote|r (the scorpids are all over the place) and |cffffd100Lost But Not Forgotten|r (all along the river west of Durotar)\nC\t\t813\t\t\nC\t\t816\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t41.0\t26.0\t\t\t\nI\t\tThen go do |cffffd100Dark Storms|r at |cffbbbbbb(41, 26)|r\nC\t\t806\t\t\nS\t\t\tvg=1\nG\t\tDurotar\t43.0\t30.0\t\t\t\nT\t\t816\t\nS\t\t\tvg=1\nG\t\tDurotar\t52.0\t44.0\t\t\t\nI\t\tTurn in |cffffd100Dark Storms|r at Razor Hill, |cffbbbbbb(52, 44)|r\nT\t\t806\t\nS\t\t\tvg=1\nA\t\t828\t\nS\t\t\tvg=1\nG\t\tDurotar\t56.0\t20.0\t\t\t\nT\t\t828\t\nA\t\t827\t\nS\t\t\tvg=1\nG\t\tDurotar\t54.0\t11.0\t\t\t\nI\t\tGo do |cffffd100Skull Rock|r along with |cffffd100Hidden Enemies|r in the cave at |cffbbbbbb(54, 11)|r\nC\t\t827\t\t\nC\t\t5726\t\t\nS\t\t\tvg=1\nI\t\tIf you can, try to kill Gazz'uz, he drops 'Eye of Burning Shadow' item which starts |cffffd100Burning Shadows|r quest. HINT: use the quest reward item |cff00ff25Faintly Glowing Skull|r to help you kill him, he's tough without it, also try to party up with somebody if you can.\nA\t\t832\t\nS\t\t\tvg=1\nG\t\tDurotar\t56.0\t20.0\t\t\t\nT\t\t827\t\nA\t\t829\t\nS\t\t\tvg=1;title=Go to into Orgrimmar\nI\t\tGo to into Orgrimmar.\nS\t\t\tvg=1\nG\t\tOrgrimmar\t33.0\t37.0\t\t\t\nI\t\tTurn in |cffffd100Hidden Enemies|r at |cffbbbbbb(33, 37)|r in Orgrimmar accept the next part to |cffffd100Hidden Enemies|r\nT\t\t5726\t\nA\t\t5726\t\nS\t\t\tvg=1\nG\t\tOrgrimmar\t47.0\t53.0\t\t\t\nI\t\tGo to Cleft of Shadows |cffbbbbbb(47, 53)|r and turn in |cffffd100Finding the Antidote|r\nT\t\t813\t\nS\t\t\tvg=1\nG\t\tOrgrimmar\t49.0\t50.0\t\t\t\nI\t\tTurn in |cffffd100Neeru Fireblade|r and |cffffd100Burning Shadows|r at Neeru Fireblade |cffbbbbbb(49, 50)|r accept |cffffd100Ak'Zeloth|r\nT\t\t829\t\nT\t\t832\t\nA\t\t809\t\nS\t\t\tvg=1\nI\t\tAlso keep talking to him to complete |cffffd100Hidden Enemies|r\nC\t\t5726\t\t\nS\t\t\tvg=1\nI\t\tThen go back to Thrall and turn in |cffffd100Hidden Enemies|r again. The 3rd part refers to RFC instance, which I skip.\nT\t\t5726\t\nS\t\t\tvg=1\nG\t\tDurotar\t40.0\t62.0\t\t\t\nI\t\tLeave Orgrimmar, and turn in |cffffd100Need for a Cure|r at |cffbbbbbb(41, 18)|r (you will most likely have to accept it again to turn it in)\nT\t\t812\t\nS\t\t\tvg=1;title=Hearth to Razor Hill\nI\t\tHearth to Razor Hill.\nS\t\t\tvg=1;title=Build up first aid\nI\t\tBuild up first aid.\nS\t\t\tvg=1;title=Get new spells/abilities\nI\t\tGet new spells/abilities.\nS\t\t\tvg=1\nG\t\tDurotar\t51.0\t44.0\t\t\t\nI\t\tAccept |cffffd100Conscript of the Horde|r at |cffbbbbbb(50, 43)|r in Razor Hill\nA\t\t840\t\nS\t\t\tvg=1;title=Run west into the Barrens\nG\t\tDurotar\t35.0\t42.0\t\t\t\nI\t\tRun west into the Barrens...at |cffbbbbbb(35, 42)|r" },
  { name = "1-6 Mulgore (Horde)", title = "1-6 Mulgore", group = "VanillaGuide 1-20", faction = "Horde", lo = 1, hi = 6, next = "6-10 Mulgore (Horde)", defaultFor = "Tauren", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=In reference to the Shamans, please look down the guide at the...\nI\t\tIn reference to the Shamans, please look down the guide at the class quest part and follow the link which will give you all the information on your class quests as you have them from level 4.\nS\t\t\tvg=1\nG\t\tMulgore\t44.0\t77.0\t\t\t\nI\t\tTalk to Grull Hawkwing |cffbbbbbb(44, 77)|r and accept |cffffd100The Hunt Begins|r\nA\t\t747\t\nS\t\t\tvg=1\nI\t\tGo outside the area kill Plainstriders and loot 7 feathers and 7 meat.\nT\t\t747\t\nS\t\t\tvg=1\nA\t\t750\t\nA\tHunter\t3092\t\nS\t\t\tvg=1\nI\t\tTalk to your class trainer and turn in |cffffd100Etched Note|r talk to Chief Hawkwind and accept |cffffd100A Humble Task|r.\nT\tHunter\t3092\t\nA\t\t753\t\nS\t\t\tvg=1\nG\t\tMulgore\t50.0\t81.0\t\t\t\nI\t\tGo to |cffbbbbbb(50, 81)|r and turn in |cffffd100A Humble Task|r at Greatmother Hawkwind, accept the next part click the water pouch on the fountain\nT\t\t753\t\nS\t\t\tvg=1\nT\t\t753\t\nS\t\t\tvg=1\nA\t\t755\t\nS\t\t\tvg=1\nI\t\tGrind to level 3 run back to Camp Narache and accept |cffffd100Break Sharptusk!|r.\nA\t\t3376\t\nS\t\t\tvg=1\nG\t\tMulgore\t44.0\t88.0\t\t\t\nI\t\tSouth of the camp around |cffbbbbbb(44, 88)|r kill 10 Cougars and loot their pelts run to |cffbbbbbb(42, 92)|r and talk to Seer Graytongue and turn in |cffffd100Rite of the Earthmother|r and accept |cffffd100Rite of Strength|r.\nT\t\t755\t\nA\t\t757\t\nS\t\t\tvg=1\nI\t\tRun back to Camp Narache to Chief Hawkwind |cffbbbbbb(44, 77)|r turn in |cffffd100The Hunt Continues|r and accept |cffffd100The Battleboars|r grinding mobs along the way until you hit level 4.\nT\t\t750\t\nA\t\t780\t\nS\t\t\tvg=1;title=Run and kill Battleboar until you have 8 Flank and 8 Snout\nG\t\tMulgore\t53.0\t81.0\t\t\t\nI\t\tRun to |cffbbbbbb(53, 81)|r and kill Battleboar until you have 8 Flank and 8 Snout.\nS\t\t\tvg=1\nG\t\tMulgore\t58.0\t85.0\t\t\t\nI\t\tRun to the cave at |cffbbbbbb(58, 85)|r kill the Quilboar for 12 Belts as you make your way to the tent at |cffbbbbbb(64, 77)|r and kill Sharptusk making sure to loot him for |cffffd100Break Sharptusk!|r then run to the little cave at |cffbbbbbb(63, 82)|r and on the inside is a Dirt-stained Map. Use it to start |cffffd100Attack on Camp Narache|r.\nC\t\t3376\t\t\nA\t\t781\t\nS\t\t\tvg=1\nG\t\tMulgore\t44.0\t77.0\t\t\t\nI\t\tHearth back to Camp Narache go to Chief Hawkwind |cffbbbbbb(44, 77)|r and turn in |cffffd100The Battleboars|r, |cffffd100Attack on Camp Narache|r and |cffffd100Rite of Strength|r\nT\t\t780\t\nT\t\t781\t\nT\t\t757\t\nA\t\t755\t\nS\t\t\tvg=1\nI\t\tTalk to Brave Windfeather and turn in |cffffd100Break Sharptusk!|r.\nT\t\t3376\t\nS\t\t\tvg=1\nG\t\tMulgore\t38.0\t81.0\t\t\t\nI\t\tGo to |cffbbbbbb(38, 81)|r and speak to Antur Fallow and accept |cffffd100A Task Unfinished|r continue following the road to Bloodhoof Village.\nA\t\t1656\t\nS\t\t\tvg=1\nI\t\tTalk to Innkeeper Kauth and turn in |cffffd100A Task Unfinished|r and make Bloodhoof Village your home.\nT\t\t1656\t\nS\t\t\tvg=1;title=You should be level 6 now, if not grind the little exp you...\nI\t\tYou should be level 6 now, if not grind the little exp you should need until you are." },
  { name = "6-10 Mulgore (Horde)", title = "6-10 Mulgore", group = "VanillaGuide 1-20", faction = "Horde", lo = 6, hi = 10, next = "10-12 Mulgore (Horde)", defaultFor = "Tauren", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tTalk to Baine Bloodhoof and turn in |cffffd100Rites of the Earthmother|r accept |cffffd100Sharing the Land|r, |cffffd100Rite of Vision|r and |cffffd100Dwarven Digging|r.\nT\t\t763\t\nA\t\t745\t\nA\t\t771\t\nA\t\t746\t\nS\t\t\tvg=1\nG\t\tMulgore\t48.0\t60.0\t\t\t\nI\t\tAccept |cffffd100Poison Water|r from Mull Thunderhorn |cffbbbbbb(48, 60)|r. Talk to Zarlman Two-Moons |cffbbbbbb(47, 57)|r turn in |cffffd100Rite of Vision|r and accept part 2.\nA\t\t748\t\nT\t\t771\t\nS\t\t\tvg=1\nG\t\tMulgore\t47.0\t62.0\t\t\t\nI\t\tTalk to Ruul Eagletalon |cffbbbbbb(47, 62)|r accept |cffffd100Dangers of the Windfury|r talk to Harken Windtotem |cffbbbbbb(48, 59)|r and accept |cffffd100Swoop Hunting|r. Talk to Maur Raincaller |cffbbbbbb(47, 57)|r accept |cffffd100Mazzranache|r.\nA\t\t743\t\nA\t\t761\t\nA\t\t766\t\nS\t\t\tvg=1;title=Go southeast and kill Trophy Swops for 8 Quills, Prairie Wolfs...\nG\t\tMulgore\t51.0\t66.0\t\t\t\nI\t\tGo southeast to |cffbbbbbb(51, 66)|r and kill Trophy Swops for 8 Quills, Prairie Wolfs for 6 Paws, Plainstriders for 4 Talons and underneath trees loot 2 Ambercorns and 2 Well Stones near the well |cffbbbbbb(53, 64)|r.\nS\t\t\tvg=1\nG\t\tMulgore\t52.0\t70.0\t\t\t\nI\t\tGo to |cffbbbbbb(52, 70)|r and kill the Palemane for |cffffd100Sharing the Land|r.\nC\t\t745\t\t\nS\t\t\tvg=1\nG\t\tMulgore\t33.0\t41.0\t\t\t\nI\t\tAt |cffbbbbbb(33, 41)|r kill Harpies for 8 Windfury Talons. Then to |cffbbbbbb(31, 50)|r and acquire broken tools for |cffffd100Dwarven Digging|r.\nC\t\t746\t\t\nS\t\t\tvg=1\nG\t\tMulgore\t59.0\t62.0\t\t\t\nI\t\tThen go to |cffbbbbbb(59, 62)|r and accept |cffffd100The Ravaged Caravan|r from Morin Cloudstalker. Go to |cffbbbbbb(54, 48)|r and click on the crates to turn it in accept the second part. Run back to Morin Cloudstalker |cffbbbbbb(59, 62)|r and turn it in\nA\t\t749\t\nA\t\t764\t\nA\t\t765\t\nS\t\t\tvg=1;title=Grind to level 8 if you aren't quite there yet\nI\t\tGrind to level 8 if you aren't quite there yet.\nS\t\t\tvg=1\nI\t\tGo back to Bloodhoof Village and turn in |cffffd100Poison Water|r, |cffffd100Dangers of the Windfury|r, |cffffd100Swoop Hunting|r\nT\t\t748\t\nT\t\t743\t\nT\t\t761\t\nT\t\t771\t\nA\t\t754\t\nS\t\t\tvg=1\nG\t\tMulgore\t53.0\t67.0\t\t\t\nI\t\tGo to |cffbbbbbb(53, 67)|r and cleanse it using Thunderhorn's item. Then run back to Mull Thunderhorn |cffbbbbbb(49, 60)|r and turn in |cffffd100Winterhoof Cleansing|r and accept |cffffd100Thunderhorn Totem|r.\nT\t\t754\t\nA\t\t756\t\nS\t\t\tvg=1;title=Go and drink Water of the Seers in your backpack\nG\t\tMulgore\t47.0\t57.0\t\t\t\nI\t\tGo to |cffbbbbbb(47, 57)|r and drink |cffffd100Water of the Seers|r in your backpack, then follow the wolf spirit.\nS\t\t\tvg=1\nG\t\tMulgore\t33.0\t36.0\t\t\t\nI\t\tTurn in |cffffd100Rite of Vision|r |cffbbbbbb(33, 36)|r when the spirit stops and accept |cffffd100Rite of Wisdom|r.\nT\t\t771\t\nA\t\t773\t\nS\t\t\tvg=1\nG\t\tMulgore\t59.0\t25.0\t\t\t\nI\t\tContinue to |cffbbbbbb(59, 25)|r to Lorekeeper Raintotem and accept |cffffd100A Sacred Burial|r.\nA\t\t833\t\nS\t\t\tvg=1\nG\t\tMulgore\t60.0\t21.0\t\t\t\nI\t\tGo to the Ancestral Spirit at the Red Rocks |cffbbbbbb(60, 21)|r turn in |cffffd100Rite of Wisdom|r accept |cffffd100Journey into Thunder Bluff|r and kill 8 Bristleback Interlopers nearby and once done speak to Lorekeeper Raintotem |cffbbbbbb(59, 25)|r and turn in |cffffd100A Sacred Burial|r.\nT\t\t773\t\nA\t\t775\t\nT\t\t833\t\nS\t\t\tvg=1;title=Go to Thunder Bluff to the Forge and destroy the Prospector's...\nG\t\tThunder Bluff\t39.0\t55.0\t\t\t\nI\t\tGo to Thunder Bluff to the Forge at |cffbbbbbb(39, 55)|r and destroy the Prospector's Picks here by clicking on them to destroy them.\nS\t\t\tvg=1\nG\t\tThunder Bluff\t69.0\t51.0\t\t\t\nI\t\tGo to |cffbbbbbb(69, 51)|r and talk to Cairne Bloodhoof to turn in |cffffd100Journey into Thunder Bluff|r accept |cffffd100Rise of the Earthmother|r.\nT\t\t775\t\nA\t\t763\t\nS\t\t\tvg=1;title=You should now be level 10, if not grind to it\nI\t\tYou should now be level 10, if not grind to it. Its time to do your class quest and below will tell you each class quest and how to do them but you can wait until you hit 12 before doing them to continue with Joana's 12-60 guide." },
  { name = "10-12 Mulgore (Horde)", title = "10-12 Mulgore", group = "VanillaGuide 1-20", faction = "Horde", lo = 10, hi = 12, next = "12-15 Barrens (Horde)", defaultFor = "Tauren", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tMulgore\t46.0\t60.0\t\t\t\nI\t\tHearth to Bloodhoof Village. Talk to Skorm Whitecloud |cffbbbbbb(46, 60)|r accept |cffffd100The Hunter's Way|r.\nA\t\t861\t\nS\t\t\tvg=1\nT\t\t746\t\nT\t\t756\t\nA\t\t758\t\nS\t\t\tvg=1\nG\t\tMulgore\t48.0\t60.0\t\t\t\nI\t\tGo to |cffbbbbbb(48, 60)|r and speak to Baine Bloodhoof and turn in |cffffd100Sharing the Land|r.\nT\t\t745\t\nS\t\t\tvg=1;title=Go to the Water Well and use it to cleanse your totem in your...\nG\t\tMulgore\t44.0\t45.0\t\t\t\nI\t\tGo to the Water Well at |cffbbbbbb(44, 45)|r and use it to cleanse your totem in your inventory.\nS\t\t\tvg=1;title=Go and kill Flatland Prowlers until you have 4 claws\nG\t\tMulgore\t45.0\t16.0\t\t\t\nI\t\tGo to |cffbbbbbb(45, 16)|r and kill Flatland Prowlers until you have 4 claws.\nS\t\t\tvg=1;title=Go and you should see the Venture Co\nG\t\tMulgore\t61.0\t47.0\t\t\t\nI\t\tGo to |cffbbbbbb(61, 47)|r and you should see the Venture Co. Mine. Kill 14 Workers and 6 Supervisors. Take a right at the first intersection and you should see Fizsprocket kill him.\nS\t\t\tvg=1\nG\t\tMulgore\t59.0\t62.0\t\t\t\nT\t\t764\t\nT\t\t765\t\nS\t\t\tvg=1\nG\t\tMulgore\t49.0\t60.0\t\t\t\nI\t\tGo to |cffbbbbbb(69, 51)|r and turn in |cffffd100Rites of the Earthmother|r.\nT\t\t758\t\nA\t\t759\t\nT\t\t776\t\nS\t\t\tvg=1\nG\t\tMulgore\t46.0\t60.0\t\t\t\nT\t\t861\t\nS\t\t\tvg=1\nG\t\tThunder Bluff\t38.0\t60.0\t\t\t\nI\t\tGo to |cffbbbbbb(38, 60)|r in Thunder Bluff and you should see Eyahn Eagletalon.\nA\t\t744\t\nS\t\t\tvg=1;title=Go behind Thunder Buff and kill Bluffwatchers until you have 6...\nG\t\tThunder Bluff\t38.0\t60.0\t\t\t\nI\t\tGo behind Thunder Buff and kill Bluffwatchers until you have 6 Azure and 6 Bronze Feathers run back to |cffbbbbbb(38, 60)|r and turn it in.\nS\t\t\tvg=1;title=Run back to Bloodhoof Village but make sure you kill Prairie...\nI\t\tRun back to Bloodhoof Village but make sure you kill Prairie Alphas along the way until you have 8 Teeth.\nS\t\t\tvg=1\nG\t\tMulgore\t49.0\t60.0\t\t\t\nT\t\t759\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t44.0\t58.0\t\t\t\nI\t\tYou should be level 12 now, if not grind to it run into the Barrens following the path until you come to Camp Taurajo. Talk to Kirge Sternhorn |cffbbbbbb(44, 58)|r and accept |cffffd100Journey to the Crossroads|r and get the Flight Path.\nA\t\t854\t\nS\t\t\tvg=1\nI\t\tRun north up the road until you get to the Crossroads and turn in |cffffd100Journey to the Crossroads|r get the Flight Path.\nT\t\t854\t\nS\t\t\tvg=1;title=Now you can continue with the 12-15 Barrens guide which is in...\nI\t\tNow you can continue with the 12-15 Barrens guide which is in the 1-60 guide." },
  { name = "1-6 Deathknell (Tirisfal Glades) (Horde)", title = "1-6 Deathknell (Tirisfal Glades)", group = "VanillaGuide 1-20", faction = "Horde", lo = 1, hi = 6, next = "6-10 Tirisfal Glades (Horde)", defaultFor = "Scourge", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=1-6 DeathKnell (Tirisfal Glades)\nI\t\t1-6 DeathKnell (Tirisfal Glades)\nS\t\t\tvg=1;title=Run up the steps and exit the Crypt\nI\t\tRun up the steps and exit the Crypt.\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t31.0\t66.0\t\t\t\nI\t\tTalk to |cff00ff25Undertaker Mordothen|r.\nA\t\t363\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t31.0\t66.0\t\t\t\nI\t\tRun down the hill and turn in |cffffd100Rude Awakening|r at |cff00ff25Shadow Priest Sarvis|r. |cffbbbbbb(31, 66)|r\nT\t\t363\t\nS\t\t\tvg=1\nA\t\t364\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t32.0\t63.0\t\t\t\nI\t\tGo down the hill to complete |cffffd100The Mindless Ones|r, then run back and turn them in.\nC\t\t364\t\t\nS\t\t\tvg=1\nT\t\t364\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Rattling the Rattlecages|r, |cffffd100Tainted Scroll, and |rGETThe Damned\nA\t\t3901\t\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Tainted Scroll|r at your class trainer get new spells/skills.\nT\tWarlock\t3099\t\nS\t\t\tvg=1\nI\t\tComplete |cffffd100The Damned|r along with |cffffd100Rattling the Rattlecages|r. These are found on the outskirts the village. When done, turn them in and accept |cffffd100Marla's Last Wish|r.\nC\t\t376\t\t\nC\t\t3901\t\t\nA\t\t6395\t\nS\t\t\tvg=1\nI\t\tGo outside the church, accept |cffffd100Night Web's Hollow|r and |cffffd100Scavenging Deathknell|r.\nA\t\t380\t\nA\t\t3902\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t37.0\t62.0\t\t\t\nI\t\tComplete |cffffd100Scavenging Deathknell|r which are found around and inside buildings in the village, then run down to |cffbbbbbb(37, 62)|r and kill Samuel Fipps for |cffffd100Marla's Last Wish|r.\nC\t\t3902\t\t\nC\t\t6395\t\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t27.0\t59.0\t\t\t\nI\t\tRun to the cave at |cffbbbbbb(27, 59)|r and do |cffffd100Night Web's Hollow|r.\nC\t\t380\t\t\nS\t\t\tvg=1;title=Run to the cemetery in the village and click the grave to bury...\nG\t\tTirisfal Glades\t31.0\t64.0\t\t\t\nI\t\tThen run to the cemetery in the village to |cffbbbbbb(31, 64)|r and click the |cfffca742grave|r to bury the skull.\nS\t\t\tvg=1\nI\t\tTurn in all the quests which are |cffffd100Night Web's Hollow|r, |cffffd100Scavenging Deathknell|r and |cffffd100Marla's Last Wish|r.\nT\t\t380\t\nT\t\t3902\t\nT\t\t6395\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t37.0\t67.0\t\t\t\nI\t\tAccept |cffffd100The Scarlet Crusade|r outside the church, go do it at |cffbbbbbb(37, 67)|r, then run back and turn it in.\nC\t\t381\t\t\nS\t\t\tvg=1\nT\t\t381\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t36.0\t68.0\t\t\t\nI\t\tAccept |cffffd100The Red Messenger|r and go and do it at |cffbbbbbb(36, 68)|r, killing |cff00ff25Meven Korgal|r.\nA\t\t382\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t36.5\t68.82\t\t\t\nC\t\t382\t\t\nS\t\t\tvg=1\nI\t\tGet new spells/skills if you are level 6, if not grind until level 6 and do this.\nT\t\t382\t\nA\t\t383\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t38.0\t57.0\t\t\t\nI\t\tRun to the north of Death Knell and accept |cffffd100A Rogue's Deal|r at |cffbbbbbb(38, 57)|r leave the starting area.\nA\t\t8\t" },
  { name = "6-10 Tirisfal Glades (Horde)", title = "6-10 Tirisfal Glades", group = "VanillaGuide 1-20", faction = "Horde", lo = 6, hi = 10, next = "10-12 Tirisfal Glades (Horde)", defaultFor = "Scourge", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tTirisfal Glades\t37.0\t52.0\t\t\t\nI\t\tGo down the hill and accept |cffffd100Fields of Grief|r from |cff00ff25Deathguard Simmer|r |cffbbbbbb(41, 54)|r go to the Pumpkin farm at |cffbbbbbb(37, 52)|r to loot 10 |cfffca742[Tirisfal Pumpkin]|r.\nA\t\t365\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t46.0\t57.0\t\t\t\nI\t\tGo back to the road around |cffbbbbbb(46, 57)|r to accept |cffffd100Gordo's Task|r. |cff00ff25Gordo|r is roaming along the road.\nA\t\t5481\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t44.43\t57.33\t\t\t\nC\t\t5481\t\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t58.0\t50.0\t\t\t\nI\t\tRun towards Brill picking up 3 |cfffca742[Gloom Weed]|r along the way.\nT\t\t5481\t\nA\t\t5482\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t58.0\t51.0\t\t\t\nA\t\t404\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t59.0\t52.0\t\t\t\nI\t\tTalk to |cff00ff25Apothecary Johaan|r.\nT\t\t365\t\nA\t\t407\t\nA\t\t368\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Wanted: Maggot Eye|r from the |cfffca742Wanted! sign|r just behind him.\nT\t\t383\t\nA\t\t427\t\nA\t\t398\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t33.73\t49.34\t\t\t\nC\t\t427\t\t\nS\t\t\tvg=1\nI\t\tTalk to |cff00ff25|r and |cff00ff25Magistrate Sevren|r.\nT\t\t427\t\nA\t\t374\t\nA\t\t358\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t62.0\t53.0\t\t\t\nI\t\tGo into the Inn |cffbbbbbb(62, 53)|r and turn in |cffffd100A Rogue's Deal|r at the |cff00ff25Innkeeper|r, and make it your home. Be sure to pick up First Aid from |cff00ff25Nurse Neela|r.\nT\t\t8\t\nS\t\t\tvg=1\nI\t\tGo to the basement of the Inn, and complete |cffffd100Fields of Grief part2|r at |cff00ff25Captured Scarlet Zealot|r.\nT\t\t407\t\nS\t\t\tvg=1;title=Go back to the bridge and kill the Scourge for 7 Putrid Claw\nG\t\tTirisfal Glades\t53.0\t53.0\t\t\t\nI\t\tGo back to the bridge at |cffbbbbbb(53, 53)|r and kill the Scourge for 7 |cfffca742[Putrid Claw]|r.\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t58.0\t51.0\t\t\t\nI\t\tYou should now be level 7.\nT\t\t404\t\nA\t\t426\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t62.0\t53.0\t\t\t\nI\t\tGo back into the Inn |cffbbbbbb(62, 53)|r and accept |cffffd100The Haunted Mills|r from |cff00ff25Coleman Farthing|r, at second floor, accept |cffffd100The Chill of Death|r from |cff00ff25Gretchen Dedmar|r.\nA\t\t362\t\nA\t\t375\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t32.0\t47.0\t\t\t\nI\t\tRun past the Pumpkin farm to the tower at |cffbbbbbb(32, 47)|r and kill |cff00ff25Scarlet Warrior|r for |cffffd100At War with the Scarlet Crusade|r. On your way, kill |cff00ff25Duskbats|r and |cff00ff25Darkhound|r for 5 |cfffca742[Duskbat Pelt]|r and 5 |cfffca742[Darkhound Blood]|r.\nC\t\t427\t\t\nS\t\t\tvg=1\nI\t\tWhen all these are done, Hearth back to Brill. Go outside to the trade supplies, and buy a |cfffca742[Coarse Thread]|r. Run back into the Inn and turn in |cffffd100The Chill of Death|r.\nT\t\t375\t\nS\t\t\tvg=1\nI\t\tRun back outside, and turn in |cffffd100Proof of Demise|r, |cffffd100At War with the Scarlet Crusade|r accept |cffffd100At War with the Scarlet Crusade pt.2|r, and turn in |cffffd100A New Plague|r, accepting |cffffd100A New Plague pt.2|r.\nT\t\t374\t\nT\t\t427\t\nA\t\t370\t\nT\t\t368\t\nA\t\t368\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t59.0\t30.0\t\t\t\nI\t\tRun north to |cffbbbbbb(59, 30)|r for |cffffd100Wanted: Maggot Eye|r, doing |cffffd100Graverobbers|r and |cffffd100Doom Weed|r along the way.\nC\t\t398\t\t\nC\t\t358\t\t\nC\t\t5482\t\t\nS\t\t\tvg=1;title=When those are done, go to the beach , and kill Murlocs until...\nG\t\tTirisfal Glades\t61.0\t29.0\t\t\t\nI\t\tWhen those are done, go to the beach at |cffbbbbbb(61, 29)|r, and kill |cff00ff25Murlocs|r until you have 5 |cfffca742[Vile Fin Scale]|r.\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t57.0\t49.0\t\t\t\nT\t\t5482\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t59.0\t52.0\t\t\t\nI\t\tGo back to Brill and turn in |cffffd100A New Plague|r and accept |cffffd100A New Plague pt.2|r at |cff00ff25Apothecary Johaan|r |cffbbbbbb(59, 52)|r\nT\t\t368\t\nA\t\t368\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t61.0\t52.0\t\t\t\nI\t\tTalk to |cff00ff25Executor Zygand|r and |cff00ff25Magistrate Sevren|r.\nT\t\t398\t\nT\t\t358\t\nA\t\t359\t\nA\t\t405\t\nS\t\t\tvg=1;title=Travel to the tower and kill 3 Scarlet Missionaries, 3 Scarlet...\nG\t\tTirisfal Glades\t51.0\t68.0\t\t\t\nI\t\tTravel to the tower at |cffbbbbbb(51, 68)|r and kill 3 |cff00ff25Scarlet Missionaries|r, 3 |cff00ff25Scarlet Zealots|r and |cff00ff25Captain Parrine|r.\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t47.0\t39.0\t\t\t\nI\t\tGo to Agamand Hills |cffbbbbbb(47, 39)|r, and kill |cff00ff25Devlin Agamand|r for |cffffd100The Haunted Mills|r.\nC\t\t362\t\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t61.0\t52.0\t\t\t\nI\t\tRun back to |cff00ff25Executor Zygand|r |cffbbbbbb(61, 52)|r in Brill, and turn in |cffffd100At War with the Scarlet Crusade pt.2|r and accept |cffffd100At War with the Scarlet Crusade pt.3|r\nT\t\t370\t\nT\t\t371\t\nS\t\t\tvg=1\nI\t\tThen talk to |cff00ff25Coleman Farthing|r inside the Inn, turn in |cffffd100The Haunted Mills|r and accept |cffffd100Deaths in the Family|r\nT\t\t362\t\nA\t\t354\t\nS\t\t\tvg=1;title=You should now be level 10, grab new spells, and accept your...\nI\t\tYou should now be level 10, grab new spells, and accept your |cffffd100Class quest|r, but don't do it yet." },
  { name = "10-12 Tirisfal Glades (Horde)", title = "10-12 Tirisfal Glades", group = "VanillaGuide 1-20", faction = "Horde", lo = 10, hi = 12, next = "12-15 Barrens (Horde)", defaultFor = "Scourge", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=Go to Agamand Hills and kill Rattlecage Soldiers and Darkeye...\nG\t\tTirisfal Glades\t47.0\t36.0\t\t\t\nI\t\tGo to Agamand Hills |cffbbbbbb(47, 36)|r and kill |cff00ff25Rattlecage Soldiers|r and |cff00ff25Darkeye Bonecasters|r, looting them for |cfffca742[Notched Ribs]|r and |cfffca742[Blackened Skulls]|r.\nS\t\t\tvg=1\nI\t\tIf |cfffca742[A Letter to Yvette]|r drops, pick it up, and accept |cffffd100A Letter Undelivered|r.\nA\t\t361\t\nS\t\t\tvg=1;title=Kill Nissa , Gregor and Thurman Agamand , making sure to loot...\nG\t\tTirisfal Glades\t44.0\t34.0\t\t\t\nI\t\tKill |cff00ff25Nissa|r |cffbbbbbb(49, 36)|r, |cff00ff25Gregor|r |cffbbbbbb(46, 29)|r and |cff00ff25Thurman Agamand|r |cffbbbbbb(44, 34)|r, making sure to loot all their remains.\nS\t\t\tvg=1;title=Run back to Deathguard Dillinger in Brill, and turn in IThe...\nG\t\tTirisfal Glades\t58.0\t51.0\t\t\t\nI\t\tRun back to |cff00ff25Deathguard Dillinger|r at |cffbbbbbb(58, 51)|r in Brill, and turn in IThe Mills Overrun\nS\t\t\tvg=1\nI\t\tRun into the Inn, and turn in |cffffd100A Letter Undelivered|r at |cff00ff25Yvette Farthing|r.\nT\t\t361\t\nT\t\t354\t\nA\t\t355\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t61.0\t51.0\t\t\t\nI\t\tTurn in |cffffd100Speak with Sevren|r at |cff00ff25Magistrate Sevren|r |cffbbbbbb(61, 51)|r, skip SKIPThe Family Crypt.\nT\t\t355\t\nS\t\t\tvg=1;title=Run to the Undercity\nG\t\tTirisfal Glades\t62.0\t65.0\t\t\t\nI\t\tRun to the Undercity. Do your class quest.\nS\t\t\tvg=1;title=Visit the Weapon Master to learn new weapon skills\nG\t\tUndercity\t57.0\t33.0\t\t\t\nI\t\tVisit the Weapon Master at |cffbbbbbb(57, 33)|r to learn new weapon skills.\nS\t\t\tvg=1\nG\t\tUndercity\t84.0\t17.0\t\t\t\nI\t\tGo to the Mage Quarter and speak with |cff00ff25Bethor Iceshard|r |cffbbbbbb(84, 17)|r and turn in |cffffd100The Prodical Lich|r, accept |cffffd100The Lich's Identity|r.\nT\t\t405\t\nA\t\t357\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t65.0\t60.0\t\t\t\nI\t\tExit Undercity, and go to |cffbbbbbb(65, 60)|r.\nT\t\t359\t\nA\t\t360\t\nA\t\t356\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t75.0\t61.0\t\t\t\nI\t\tGo to |cffbbbbbb(75, 61)|r and kill 8 |cff00ff25Bleeding Horrors|r and 8 |cff00ff25Wandering Spirits|r for |cffffd100Rear Guard Patrol|r\nC\t\t356\t\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t80.0\t56.0\t\t\t\nI\t\tRun north to |cffbbbbbb(80, 56)|r and kill 5 |cff00ff25Scarlet Friars|r and |cff00ff25Captain Vachon|r for |cffffd100At War with the Scarlet Crusade pt.3|r.\nC\t\t371\t\t\nS\t\t\tvg=1;title=Go east and kill Vicious Night Web Spiders until you get 4...\nG\t\tTirisfal Glades\t85.0\t53.0\t\t\t\nI\t\tGo east to |cffbbbbbb(85, 53)|r and kill |cff00ff25Vicious Night Web Spiders|r until you get 4 |cfffca742[Vicious Night Web Spider Venom]|r.\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t68.0\t42.0\t\t\t\nI\t\tGo to Brightwater Lake and swim to Gunther's Retreat. Click |cfffca742[Gunther's Books]|r at |cffbbbbbb(68, 42)|r to loot |cfffca742[The Lich's Spellbook]|r go back to |cffbbbbbb(65, 60)|r and turn in |cffffd100Rear Guard Patrol|r.\nT\t\t356\t\nS\t\t\tvg=1\nG\t\tUndercity\t84.0\t17.0\t\t\t\nI\t\tEnter the Undercity.\nT\t\t357\t\nA\t\t366\t\nS\t\t\tvg=1;title=Hearth or run back to Brill\nI\t\tHearth or run back to Brill.\nS\t\t\tvg=1\nI\t\tGo to the basement of the Inn, and turn in |cffffd100A New Plague pt.3|r.\nT\t\t371\t\nA\t\t372\t\nT\t\t368\t\nA\t\t369\t\nT\t\t360\t\nT\t\t369\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t68.0\t42.0\t\t\t\nI\t\tGo back to Gunther's Retreat at |cffbbbbbb(68, 42)|r and turn in |cffffd100Return the Book|r, accept |cffffd100Proving Allegiance|r. Grab a |cfffca742[Candle of Beckoning]|r from the |cfffca742Crate of Candles|r.\nT\t\t366\t\nA\t\t409\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t66.7\t45.05\t\t\t\nC\t\t409\t\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t67.0\t45.0\t\t\t\nI\t\tGo to the small island just south |cffbbbbbb(67, 45)|r, and use the candle on the |cfffca742Dinner Table|r to summon |cff00ff25Lillith Nefara|r. Kill her go back to |cff00ff25Gunther Arcanus|r and turn the quest in, accepting |cffffd100The Prodigal Lich Returns|r.\nT\t\t409\t\nA\t\t411\t\nS\t\t\tvg=1\nG\t\tTirisfal Glades\t79.0\t26.0\t\t\t\nI\t\tGo to the tower up the pathway at |cffbbbbbb(79, 26)|r and kill |cff00ff25Captain Melrache|r and 2 |cff00ff25Scarlet Bodyguard|r for |cffffd100At War with the Scarlet Crusade pt.4|r.\nC\t\t372\t\t\nS\t\t\tvg=1\nG\t\tUndercity\t84.0\t17.0\t\t\t\nI\t\tGo back to Brill and turn in |cffffd100At War with the Scarlet Crusade|r\nT\t\t371\t\nS\t\t\tvg=1\nG\t\tUndercity\t84.0\t17.0\t\t\t\nI\t\tRun to the Undercity and at the Mage Quarter |cffbbbbbb(84, 17)|r turn in |cffffd100The Prodigal Lich Returns|r.\nT\t\t411\t\nS\t\t\tvg=1;title=You should now be level 12, so get your training for level 12\nI\t\tYou should now be level 12, so get your training for level 12.\nS\t\t\tvg=1;title=Exit Undercity, and run to the Zeppelin Tower\nG\t\tTirisfal Glades\t61.0\t59.0\t\t\t\nI\t\tExit Undercity, and run to the Zeppelin Tower at |cffbbbbbb(61, 59)|r. Get on the zeppelin to Orgrimmar.\nS\t\t\tvg=1;title=Run in to Orgrimmar and get the flight path\nG\t\tOrgrimmar\t45.0\t64.0\t\t\t\nI\t\tRun in to Orgrimmar |cffbbbbbb(46, 12)|rand get the flight path |cffbbbbbb(45, 64)|r.\nS\t\t\tvg=1\nG\t\tDurotar\t51.0\t44.0\t\t\t\nI\t\tRun back out of Orgrimmar, and south to Razor Hill.\nA\t\t840\t\nS\t\t\tvg=1;title=Head west and in to the Barrens\nG\t\tDurotar\t35.0\t42.0\t\t\t\nI\t\tHead west and in to the Barrens, |cffbbbbbb(35, 42)|r." },
  { name = "12-15 Barrens (Horde)", title = "12-15 Barrens", group = "VanillaGuide 1-20", faction = "Horde", lo = 12, hi = 15, next = "15-16 Stonetalon Mountains (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tThe Barrens\t62.0\t19.0\t\t\t\nI\t\tTurn in |cffffd100Conscript of the Horde|r at |cffbbbbbb(62, 19)|r in the Barrens, accept |cffffd100Crossroads Conscription|r\nT\t\t840\t\nA\t\t842\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t62.0\t20.0\t\t\t\nI\t\tThen turn in |cffffd100Ak'Zeloth|r |cffbbbbbb(62, 20)|r I SKIP |cff00ff25The Demon Seed|r\nT\t\t809\t\nS\t\t\tvg=1;title=Run to XRs (Crossroads)\nG\t\tThe Barrens\t52.0\t30.0\t\t\t\nI\t\tRun to XRs (Crossroads) at |cffbbbbbb(52, 30)|r.\nS\t\t\tvg=1\nG\t\tThe Barrens\t52.0\t30.0\t\t\t\nI\t\tOnce at XRs at |cffbbbbbb(52, 30)|r turn in |cffffd100Crossroads Conscription|r accept all quests in XRs (which includes: |cffffd100Meats to Orgrimmar|r |cffffd100Plainstrider Menace|r |cffffd100The Forgotten Pools|r |cffffd100Raptor Thieves|r |cffffd100Wharfmaster Dizzywig|r |cffffd100Fungal Spores|r |cffffd100Disrupt the Attacks|r |cffffd100Supplies for the Crossroads|r and |cffffd100Harpy Raiders|r on top of the watch tower). Turn in |cffffd100Meats to Orgrimmar|r i SKIP |cff00ff25Ride to Orgrimmar|r\nT\t\t842\t\nA\t\t6365\t\nA\t\t844\t\nA\t\t870\t\nA\t\t869\t\nA\t\t1492\t\nA\t\t848\t\nA\t\t871\t\nA\t\t5041\t\nA\t\t867\t\nT\t\t6365\t\nS\t\t\tvg=1;title=Make XRs your home\nI\t\tMake XRs your home.\nS\t\t\tvg=1;title=Get FP (Flight Path)\nI\t\tGet FP (Flight Path)\nS\t\t\tvg=1\nG\t\tThe Barrens\t54.0\t26.0\t\t\t\nI\t\tThen go do: |cffffd100Disrupt the Attacks|r along with |cffffd100Plainstrider Menace|r and |cffffd100Raptor Thieves|r around |cffbbbbbb(54, 26)|r. NOTE: If you find |cffffd100Chen's Empty Keg|r accept it.\nC\t\t871\t\t\nC\t\t844\t\t\nC\t\t869\t\t\nA\t\t821\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t52.0\t30.0\t\t\t\nI\t\tOnce |cffffd100Disrupt the Attacks|r is completed go turn it in at |cffbbbbbb(52, 30)|r and accept GETSupplies for the Crossroads\nC\t\t871\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t52\t30\t\t\t\nT\t\t871\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t56.0\t26.0\t\t\t\nI\t\tGo do |cffffd100Supplies for the Crossroads|r at |cffbbbbbb(56, 26)|r, then run back to Thork and |cffffd100The Disruption Ends|r, you'll be going back up to the razormanes one more time.\nC\t\t5041\t\t\nA\t\t872\t\nS\t\t\tvg=1\nI\t\tIf you find |cffffd100Chen's Empty Keg|r accept it.\nA\t\t821\t\nS\t\t\tvg=1\nI\t\tOnce |cffffd100Plainstrider Menace|r & |cffffd100The Disruption Ends|r and are complete...\nC\t\t844\t\t\nC\t\t872\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t63.0\t37.0\t\t\t\nI\t\tGo to Ratchet, get the Flight Path there |cffbbbbbb(63, 37)|r and accept |cffffd100Raptor Horns|r |cffffd100Samophlange|r |cffffd100Southsea Freebooters|r |cffffd100The Guns of Northwatch|r . Turn in |cffffd100Chen's Empty Keg|r if you have it ... accept the next part to it, and focus on doing this quest while throughout the Barrens.\nA\t\t865\t\nA\t\t894\t\nA\t\t887\t\nA\t\t891\t\nT\t\t821\t\nS\t\t\tvg=1\nI\t\tGrab the quest |cffffd100WANTED: Baron Longshore|r (the wanted sign by the bank)\nA\t\t895\t\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Wharfmaster Dizzywig|r (goblin on the docks) accept |cffffd100Miner's Fortune|r\nT\t\t1492\t\nA\t\t896\t\nS\t\t\tvg=1\nI\t\tThen go do |cffffd100Southsea Freebooters|r along with |cffffd100WANTED: Baron Longshore|r (along the shore just south of Ratchet)\nC\t\t887\t\t\nC\t\t895\t\t\nS\t\t\tvg=1;title=Once those are done, turn them in , accept new ones go do\nG\t\tThe Barrens\t63.0\t36.0\t\t\t\nI\t\tOnce those are done, turn them in at |cffbbbbbb(63, 36)|r, accept new ones go do:\nS\t\t\tvg=1\nI\t\t|cffffd100The Missing Shipment|r (just turn this in at the goblin at the docks) accept |cffffd100The Missing Shipment|r part2\nT\t\t887\t\nT\t\t890\t\nA\t\t890\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t63.0\t36.0\t\t\t\nI\t\tRun back, to Gazlowe |cffbbbbbb(63, 36)|r, turn in |cffffd100The Missing Shipment|r part2 accept |cffffd100Stolen Booty|r\nT\t\t890\t\nA\t\t888\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t63.0\t50.0\t\t\t\nI\t\tThen go do |cffffd100Stolen Booty|r south of Ratchet. Telescopic Lens=|cffbbbbbb(64, 49)|r, and Shipment of Boots=|cffbbbbbb(63, 50)|r\nC\t\t888\t\t\nS\t\t\tvg=1\nI\t\tOnce |cffffd100Stolen Booty|r is completed hearth to XRs. (don't turn it in yet)\nC\t\t888\t\t\nS\t\t\tvg=1\nT\t\t872\t\nT\t\t5041\t\nS\t\t\tvg=1\nT\t\t844\t\nA\t\t845\t\nA\t\t899\t\nA\t\t4921\t\nS\t\t\tvg=1;title=At this point, I make sure I have three/four 6 slot bags, if I...\nI\t\tAt this point, I make sure I have three/four 6 slot bags, if I don't, I buy them at the bag vendor.\nS\t\t\tvg=1;title=Run west from XRs, go to the guy in the hut\nG\t\tThe Barrens\t45.0\t28.0\t\t\t\nI\t\tRun west from XRs, go to the guy in the hut... at |cffbbbbbb(45, 28)|r\nS\t\t\tvg=1\nA\t\t850\t\nA\t\t855\t\nS\t\t\tvg=1;title=Go start doing\nI\t\tThen go start doing:\nS\t\t\tvg=1\nI\t\t|cffffd100Kolkar Leaders|r |cffffd100Centaur Bracers|r |cffffd100Raptor Thieves|r |cffffd100The Zhevra|r |cffffd100Fungal Spores|r and |cffffd100The Forgotten Pools|r (all of these are done just slightly north of where you are)\nC\t\t850\t\t\nC\t\t855\t\t\nC\t\t869\t\t\nC\t\t845\t\t\nC\t\t848\t\t\nC\t\t870\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t43.0\t24.0\t\t\t\nI\t\tOnce |cffffd100Kolkar Leaders|r is done.. Barak is at |cffbbbbbb(43, 24)|r.\nC\t\t850\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t38.0\t17.0\t\t\t\nI\t\tGo do: |cffffd100Harpy Raiders|r at |cffbbbbbb(38, 17)|r\nC\t\t867\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t35.0\t27.0\t\t\t\nI\t\tOnce |cffffd100Harpy Raiders|r is done, grind your way down into Stonetalon Mountains, at |cffbbbbbb(35, 27)|r in the Barrens...\nC\t\t867\t\t" },
  { name = "15-16 Stonetalon Mountains (Horde)", title = "15-16 Stonetalon Mountains", group = "VanillaGuide 1-20", faction = "Horde", lo = 15, hi = 16, next = "16-20 Barrens (part 1) (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tThe Barrens\t35.0\t27.0\t\t\t\nI\t\tAccept |cffffd100Goblin Invaders|r (you should first accept |cffffd100Spirits of Stonetalon|r from Zor Lonetree in Orgrimmar, but this is a lvl13 quest. Grab it if you're in Orgrimmar at that level) and |cffffd100Avenge My Village|r at |cffbbbbbb(35, 27)|r in the Barrens\nA\t\t1062\t\nA\t\t1061\t\nA\t\t6548\t\nS\t\t\tvg=1\nI\t\tGo do: |cffffd100Avenge My Village|r then turn it in.\nC\t\t6548\t\t\nS\t\t\tvg=1\nT\t\t6548\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t73.0\t86.0\t\t\t\nI\t\tThen do: |cffffd100Kill Grundig Darkcloud|r at |cffbbbbbb(73, 86)|r.\nC\t\t6629\t\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t73.0\t85.0\t\t\t\nI\t\tNOTE: I usually skip the escort quest there (|cffffd100Protect Kaya|r |cffbbbbbb(73, 85)|r in the hut), This quest can be a little tough, kill the Sorcerer first that pops out during the one battle you have to fight. If it's too hard for you, you can skip it.\nC\t\t6523\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t35.0\t28.0\t\t\t\nI\t\tTurn in |cffffd100Kill Grundig Darkcloud|r and |cffffd100Protect Kaya|r if you did it, at |cffbbbbbb(35, 28)|r in the Barrens ...\nT\t\t6629\t\nT\t\t6523\t\nA\t\t6401\t\nS\t\t\tvg=1;title=Go back to the Barrens\nI\t\tThen go back to the Barrens.." },
  { name = "16-20 Barrens (part 1) (Horde)", title = "16-20 Barrens (part 1)", group = "VanillaGuide 1-20", faction = "Horde", lo = 16, hi = 20, next = "16-20 Barrens (part 2) (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=16-20 Barrens Part 1\nI\t\t16-20 Barrens Part 1\nS\t\t\tvg=1;title=Grind your way back to the guy in the hut\nG\t\tThe Barrens\t45.0\t28.0\t\t\t\nI\t\tGrind your way back to the guy in the hut at |cffbbbbbb(45, 28)|r\nS\t\t\tvg=1\nI\t\tAlso turn in |cffffd100Centaur Bracers|r if it is done, if not don't worry.\nT\t\t850\t\nA\t\t851\t\nT\t\t855\t\nS\t\t\tvg=1\nI\t\tMake sure you finish up |cffffd100Raptor Thieves|r |cffffd100The Zhevra|r |cffffd100Fungal Spores|r and |cffffd100The Forgotten Pools|r before returning to the XRs.\nC\t\t869\t\t\nC\t\t845\t\t\nC\t\t848\t\t\nC\t\t870\t\t\nS\t\t\tvg=1;title=Run to Cross Roads\nG\t\tThe Barrens\t52.0\t30.0\t\t\t\nI\t\tRun to Cross Roads, at |cffbbbbbb(52, 30)|r\nS\t\t\tvg=1;title=Turn in ALL quests, grab ALL new ones\nI\t\tTurn in ALL quests, grab ALL new ones...\nS\t\t\tvg=1\nI\t\tThen do |cffffd100Apothecary Zamah|r Which has you run all the way to Thunder Bluff (TB) at the spirt rise cave. Do these along the way:\nT\t\t848\t\nA\t\t853\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t49.0\t50.0\t\t\t\nI\t\tGrind your way down south to |cffbbbbbb(49, 50)|r, and do |cffffd100Lost in Battle|r (Manrik's Wife) She's laying dead by the hut, west of the bridge.\nC\t\t4921\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t44.0\t59.0\t\t\t\nI\t\tGo down to Camp Taurajo (CT) accept |cffffd100Tribes at War|r from the gnoll in the cage |cffbbbbbb(44, 59)|r, and get FP there.\nA\t\t878\t\nS\t\t\tvg=1\nG\t\tMulgore\t39.0\t27.0\t\t\t\nI\t\tThen do |cffffd100Apothecary Zamah|r Which has you run all the way to Thunder Bluff (TB) in Mulgore, at |cffbbbbbb(39, 27)|r.\nC\t\t853\t\t\nS\t\t\tvg=1;title=Once at TB, go to the Weapon Master and get what weapon skills...\nI\t\tOnce at TB, go to the |cff00ff25Weapon Master|r |cffbbbbbb(40, 62)|r and get what weapon skills you need for your class.\nS\t\t\tvg=1;title=Get new spells/abilities\nI\t\tGet new spells/abilities.\nS\t\t\tvg=1\nG\t\tThe Barrens\t29.0\t29.0\t\t\t\nI\t\tTurn in |cffffd100Apothecary Zamah|r the cave below the spirit rise at |cffbbbbbb(29, 29)|r.\nT\t\t853\t\nS\t\t\tvg=1;title=Go to first aid guy at spirit rise to build up first aid\nI\t\tGo to first aid guy at spirit rise to build up first aid.\nS\t\t\tvg=1;title=Go up to the tower in middle of town to get FP, but DON'T fly...\nI\t\tGo up to the tower in middle of town to get FP, but DON'T fly back to XRs.\nS\t\t\tvg=1;title=Hearth back to XRs\nI\t\tHearth back to XRs.\nS\t\t\tvg=1\nT\t\t4921\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t37.0\t20.0\t\t\t\nI\t\tThen go north west of XRs and do |cffffd100Prowlers of the Barrens|r |cffbbbbbb(37, 20)|r\nC\t\t903\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t38.0\t14.0\t\t\t\nI\t\tThen |cffffd100Harpy Lieutenants|r |cffbbbbbb(38, 14)|r\nC\t\t875\t\t\nS\t\t\tvg=1\nI\t\tThen grind your way east and do |cffffd100Samophlange|r |cffbbbbbb(52, 11)|r complete the whole chain, which in the end has you kill the goblin for the key.\nC\t\t902\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t56.0\t8.0\t\t\t\nI\t\tThen go east to Sludge Fen and do |cffffd100Ignition|r (56.8)\nC\t\t858\t\t\nS\t\t\tvg=1\nI\t\tThen do |cffffd100The Escape|r (|cffff6060See video on how I do Ignition and Escape|r)\nC\t\t863\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t61.0\t5.0\t\t\t\nI\t\tThen go north-east and do |cffffd100Miner's Fortune|r (61.5)\nC\t\t896\t\t\nS\t\t\tvg=1;title=Grind your way south to Ratchet\nG\t\tThe Barrens\t63.0\t37.0\t\t\t\nI\t\tThen grind your way south to Ratchet |cffbbbbbb(63, 37)|r...\nS\t\t\tvg=1\nI\t\tAnd SKIP |cff00ff25Wenikee Boltbucket|r\nT\t\t888\t\nT\t\t902\t\nT\t\t863\t\nA\t\t1483\t\nS\t\t\tvg=1\nT\t\t896\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t54.0\t43.0\t\t\t\nI\t\tThen go west of ratchet and do |cffffd100The Stagnant Oasis|r and |cffffd100Verog the Dervish|r at |cffbbbbbb(54, 43)|r\nC\t\t877\t\t\nC\t\t851\t\t\nS\t\t\tvg=1;title=Run to XRs\nG\t\tThe Barrens\t52.0\t30.0\t\t\t\nI\t\tThen run to XRs |cffbbbbbb(52, 30)|r..\nS\t\t\tvg=1\nT\t\t903\t\nT\t\t875\t\nT\t\t877\t\nA\t\t880\t\nA\t\t881\t\nA\t\t876\t\nA\t\t6541\t\nA\t\t868\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t45.0\t28.0\t\t\t\nI\t\tGo west of XRs |cffbbbbbb(45, 28)|r, to turn in: |cffffd100Centaur Bracers|r and |cffffd100Verog the Dervish|r ... I SKIP |cff00ff25Hezrul Bloodmark|r\nT\t\t855\t\nT\t\t851\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t38.0\t11.0\t\t\t\nI\t\tThen grind your way north and do: |cffffd100Serena Bloodfeather|r at |cffbbbbbb(38, 11)|r\nC\t\t876\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t55.0\t17.0\t\t\t\nI\t\tThen go east (grind mobs along the way) and do |cffffd100Echeyakee|r at |cffbbbbbb(55, 17)|r.\nC\t\t881\t\t\nS\t\t\tvg=1;title=Hearth to XRs\nI\t\tHearth to XRs.\nS\t\t\tvg=1\nT\t\t881\t\nA\t\t905\t\nS\t\t\tvg=1\nI\t\tMake sure that |cffffd100Consumed by Hatred|r is also accepted.\nT\t\t876\t\nA\t\t1060\t\nA\t\t899\t" },
  { name = "16-20 Barrens (part 2) (Horde)", title = "16-20 Barrens (part 2)", group = "VanillaGuide 1-20", faction = "Horde", lo = 16, hi = 20, next = "20-21 Stonetalon Mountains (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=16-20 Barrens Part 2\nI\t\t16-20 Barrens Part 2\nS\t\t\tvg=1;title=Go down south and do\nI\t\tGo down south and do:\nS\t\t\tvg=1\nG\t\tThe Barrens\t55.0\t42.0\t\t\t\nI\t\t|cffffd100Altered Beings|r |cffbbbbbb(55, 42)|r\nC\t\t880\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t57.0\t54.0\t\t\t\nI\t\t|cffffd100Raptor Horns|r along with |cffffd100Stolen Silver|r at |cffbbbbbb(57, 54)|r\nC\t\t865\t\t\nC\t\t3281\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t51.0\t46.0\t\t\t\nI\t\t|cffffd100The Angry Scytheclaws|r |cffbbbbbb(51, 46)|r\nC\t\t905\t\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t51.0\t54.0\t\t\t\nI\t\t|cffffd100Tribes at War|r along with |cffffd100Consumed by Hatred|r at |cffbbbbbb(51, 54)|r\nC\t\t878\t\t\nC\t\t899\t\t\nS\t\t\tvg=1;title=Grind your way to Camp Taurajo\nG\t\tThe Barrens\t45.0\t58.0\t\t\t\nI\t\tThen grind your way to Camp Taurajo |cffbbbbbb(45, 58)|r\nS\t\t\tvg=1\nA\t\t893\t\nS\t\t\tvg=1;title=Go to gnoll in the cage\nI\t\tGo to gnoll in the cage...\nS\t\t\tvg=1\nT\t\t878\t\nA\t\t5052\t\nA\t\t879\t\nS\t\t\tvg=1\nT\t\t5052\t\nS\t\t\tvg=1\nI\t\tTurn in 10 bloodshards for |cffffd100Spirit of the Wind|r (repeatable quest) for fast run speed.\nT\t\t889\t\nS\t\t\tvg=1;title=At this point, you should be about half way to level 20\nI\t\tAt this point, you should be about half way to level 20.\nS\t\t\tvg=1;title=Now comes the fun part: Wailing Caverns Instance!\nI\t\tNow comes the fun part: |cff00ff25Wailing Caverns|r Instance! at |cffbbbbbb(46, 36)|r. You will need a full group to do this. OPTIONAL: GRIND all the way to level 20! (which is what I do, but it's not recommended). I grind away at beasts and brisstlebacks just north of CT.\nS\t\t\tvg=1\nI\t\tKeep an eye out for the mobs named |cff00ff25Lakota'mani|r (a big grey kodo around |cffbbbbbb(45, 53)|r) and |cff00ff25Owatanka|r. They drops |cff00ff25Hoof of Lakota'mani|r which starts |cffffd100Lakota'mani|r and |cff00ff25Owatanka's Tailspike|r which starts |cffffd100Owatanka|r. Turn these in at CT when you get the chance.\nC\t\t883\t\t\nC\t\t884\t\t\nS\t\t\tvg=1;title=Once you are at least 5 bars away from 20, run to XRs\nI\t\tOnce you are at least 5 bars away from 20, run to XRs...\nS\t\t\tvg=1\nI\t\tSKIP |cff00ff25Mura Runetotem|r . You should be lvl 20 now.\nT\t\t3281\t\nT\t\t899\t\nT\t\t880\t\nT\t\t905\t\nS\t\t\tvg=1;title=Fly to Orgrimmar, get new spells/abilities\nI\t\tFly to Orgrimmar, get new spells/abilities.\nS\t\t\tvg=1\nA\t\t6382\t\nS\t\t\tvg=1;title=Hearth back to XRs\nI\t\tHearth back to XRs.\nS\t\t\tvg=1;title=Fly to Ratchet\nI\t\tFly to Ratchet...\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Chen's Empty Keg|r (if you did it, if not don't worry) ...\nT\t\t821\t\nS\t\t\tvg=1\nT\t\t865\t\nA\t\t1069\t\nA\t\t1483\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t60.0\t55.0\t\t\t\nI\t\tThen go do: |cffffd100The Guns of Northwatch|r at |cffbbbbbb(60, 55)|r (|cffff6060See complete video on this quest along with the escort quest|r)\nC\t\t891\t\t\nS\t\t\tvg=1\nI\t\tThen once |cffffd100The Guns of Northwatch|r is done, do:\nC\t\t891\t\t\nS\t\t\tvg=1\nI\t\t|cffffd100Free From the Hold|r (escort quest)\nC\t\t898\t\t\nS\t\t\tvg=1;title=Turn in both quests at Ratchet, then\nI\t\tTurn in both quests at Ratchet, then..\nS\t\t\tvg=1;title=Hearth to XRs\nI\t\tHearth to XRs. (if hearth stone is still on a cooldown, fly to XRs)\nS\t\t\tvg=1;title=Run west into Stonetalon Mountains\nI\t\tRun west into Stonetalon Mountains..." },
  { name = "20-21 Stonetalon Mountains (Horde)", title = "20-21 Stonetalon Mountains", group = "VanillaGuide 20-40", faction = "Horde", lo = 20, hi = 21, next = "21-21 Ashenvale (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=Run to Malaka'Jin\nG\t\tStonetalon Mountains\t71.0\t94.0\t\t\t\nI\t\tRun to Malaka'Jin at |cffbbbbbb(71, 94)|r\nS\t\t\tvg=1\nA\t\t6461\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t74.0\t97.0\t\t\t\nI\t\tTurn in |cffffd100Letter to Jin'Zil|r at |cffbbbbbb(74, 97)|r in the cave ...\nT\t\t1060\t\nA\t\t1058\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t59.0\t75.0\t\t\t\nI\t\tThen go accept |cffffd100Arachnophobia|r from the Wanted poster at |cffbbbbbb(59, 75)|r\nA\t\t6284\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t54.0\t76.0\t\t\t\nI\t\tGo do |cffffd100Blood Feeders|r along with |cffffd100Deepmoss Spider Eggs|r and |cffffd100Arachnophobia|r around |cffbbbbbb(54, 76)|r NOTE: you can skip Arachnophobia for now, you'll return here later...\nC\t\t6461\t\t\nC\t\t1069\t\t\nC\t\t6284\t\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t58.0\t62.0\t\t\t\nI\t\tThen turn in |cffffd100Ziz Fizziks|r at the goblin in the hut at Windshear Crag, |cffbbbbbb(58, 62)|r ...\nT\t\t1483\t\nA\t\t1093\t\nS\t\t\tvg=1\nI\t\tThen do: |cffffd100Goblin Invaders|r and |cffffd100Super Reaper 6000|r (the mobs are just north in Windshear Crag)\nC\t\t1062\t\t\nC\t\t1093\t\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t58.0\t62.0\t\t\t\nT\t\t1093\t\nA\t\t1094\t\nS\t\t\tvg=1;title=Run to Sun Rock Retreat\nG\t\tStonetalon Mountains\t46.0\t59.0\t\t\t\nI\t\tRun to Sun Rock Retreat at |cffbbbbbb(46, 59)|r.\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Arachnophobia|r and |cffffd100Kaya's Alive|r if you did the escort quest\nT\t\t6284\t\nT\t\t6401\t\nS\t\t\tvg=1;title=Get FP there\nI\t\tGet FP there.\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t47.0\t64.0\t\t\t\nI\t\tRun up the little |cffff6060pathway|r and accept |cffffd100Boulderslide Ravine|r and |cffffd100Trouble in the Deeps|r at |cffbbbbbb(47, 64)|r\nA\t\t6421\t\nA\t\t6562\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t61.0\t92.0\t\t\t\nI\t\tThen go do |cffffd100Boulderslide Ravine|r at |cffbbbbbb(61, 92)|r\nC\t\t6421\t\t\nS\t\t\tvg=1\nG\t\tStonetalon Mountains\t71.0\t95.0\t\t\t\nT\t\t6461\t\nS\t\t\tvg=1\nG\t\tThe Barrens\t35.0\t27.0\t\t\t\nI\t\tTurn in |cffffd100Goblin Invaders|r at |cffbbbbbb(35, 27)|r in the Barrens ... accept |cffffd100Shredding Machines|r (I SKIP |cff00ff25The Elder Crone|r )\nT\t\t1062\t\nA\t\t1068\t\nS\t\t\tvg=1;title=Hearth to XRs\nI\t\tHearth to XRs.\nS\t\t\tvg=1\nG\t\tThe Barrens\t48.0\t5.0\t\t\t\nI\t\tRun north to Ashenvale (stopping along the way to turn in |cffffd100Report to Kadrak|r (at 48.5) but SKIP |cff00ff25The Warsong Reports|r\nT\t\t6541\t" },
  { name = "21-21 Ashenvale (Horde)", title = "21-21 Ashenvale", group = "VanillaGuide 20-40", faction = "Horde", lo = 21, hi = 21, next = "22-23 Southern Barrens (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=Run to Splintertree Post\nG\t\tAshenvale\t73.0\t65.0\t\t\t\nI\t\tRun to Splintertree Post at |cffbbbbbb(73, 65)|r\nS\t\t\tvg=1\nT\t\t6383\t\nT\t\t6383\t\nS\t\t\tvg=1;title=Get FP in Splintertree Post\nI\t\tGet FP in Splintertree Post.\nS\t\t\tvg=1;title=Run all the way to Zoram Strand , grind mobs along the way\nG\t\tAshenvale\t13.0\t31.0\t\t\t\nI\t\tRun all the way to Zoram Strand at |cffbbbbbb(13, 31)|r, grind mobs along the way.\nS\t\t\tvg=1\nG\t\tAshenvale\t12.0\t33.0\t\t\t\nI\t\tGet FP there. |cffbbbbbb(12, 33)|r. i SKIP |cff00ff25The Essence of Aku'Mai|r\nT\t\t6562\t\nS\t\t\tvg=1;title=Do the following quests\nI\t\tDo the following quests:\nS\t\t\tvg=1\nI\t\tAccept and do |cffffd100Naga at the Zoram Strand|r then turn it in.\nC\t\t6442\t\t\nS\t\t\tvg=1\nT\t\t6442\t\nS\t\t\tvg=1;title=Hearth back to XRs, if hearth stone is still on a cooldown, fly...\nI\t\tHearth back to XRs, if hearth stone is still on a cooldown, fly there." },
