    steps = "S\t\t\tvg=1\nT\t\t1196\t\nA\t\t1196\t\nS\t\t\tvg=1;title=I do the following order\nI\t\tI do the following order:\nS\t\t\tvg=1\nG\t\tThousand Needles\t44.0\t37.0\t\t\t\nI\t\t|cffffd100The sacred Flame|r, charge the brazier in the cave at |cffbbbbbb(44, 37)|r.\nC\t\t1197\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t21.0\t32.0\t\t\t\nI\t\tGo to Whitereach Post |cffbbbbbb(21, 32)|r, accept |cffffd100Hypercapacitor Gizmo|r , Turn in |cffffd100Serpent Wild|r ...accept |cffffd100Sacred Fire|r\nA\t\t5151\t\nT\t\t4865\t\nA\t\t5062\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t35.0\t36.0\t\t\t\nI\t\tGo do: |cffffd100Sacred Fire|r |cffbbbbbb(35, 36)|r\nC\t\t5062\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t11.0\t36.0\t\t\t\nI\t\t|cffffd100Wind Rider|r |cffbbbbbb(11, 36)|r\nC\t\t4767\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t17.0\t40.0\t\t\t\nI\t\t|cffffd100Homeward Bound|r, escort starts at |cffbbbbbb(17, 40)|r. (If the Elite gets in the way, skip it).\nC\t\t4770\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t16.0\t25.0\t\t\t\nI\t\t|cffffd100Steelsnap|r, he patrols around |cffbbbbbb(16, 25)|r.\nC\t\t1131\t\t\nS\t\t\tvg=1;title=Hearth to Thunder Bluff\nI\t\tHearth to Thunder Bluff.\nS\t\t\tvg=1;title=Get new spells/abilities\nI\t\tGet new spells/abilities.\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Steelsnap|r (on Hunter Rise) ...\nT\t\t1131\t\nA\t\t1136\t\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Sacred Fire|r (on Elder Rise) ...\nT\t\t5062\t\nA\t\t5088\t\nS\t\t\tvg=1;title=Fly back to 1K Needles\nI\t\tFly back to 1K Needles.\nS\t\t\tvg=1;title=Make Freewind Post your home\nI\t\tMake Freewind Post your home.\nS\t\t\tvg=1\nT\t\t1197\t\nT\t\t4767\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t31.0\t36.0\t\t\t\nI\t\tGo to the Darkcloud Pinnacle (the entrance ramp is at |cffbbbbbb(31, 36)|r), and do the following quests: |cffffd100Grimtotem Spying|r, the notes are up in the rises at |cffbbbbbb(31, 32)|r, |cffbbbbbb(33, 39)|r, and |cffbbbbbb(39, 41)|r\nC\t\t5064\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t37.0\t35.0\t\t\t\nI\t\t|cffffd100Arikara|r done at |cffbbbbbb(37, 35)|r.\nC\t\t5088\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t38.0\t27.0\t\t\t\nI\t\t|cffffd100Wanted - Arnak Grimtotem|r, at |cffbbbbbb(38, 27)|r.\nC\t\t5147\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t38.0\t27.0\t\t\t\nI\t\t|cffffd100Free at Last|r, escort quest starts at |cffbbbbbb(38, 27)|r.\nC\t\t4904\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t21.0\t32.0\t\t\t\nI\t\tGo to Whitereach Post |cffbbbbbb(21, 32)|r, turn in |cffffd100Arikara|r and |cffffd100Homeward Bound|r\nT\t\t5088\t\nT\t\t4770\t\nS\t\t\tvg=1;title=You should be level 29 by now, if not grind to level 29, I...\nG\t\tThousand Needles\t18.0\t23.0\t\t\t\nI\t\tYou should be level 29 by now, if not grind to level 29, I grind away at centuars around Camp E'Thok |cffbbbbbb(18, 23)|r\nS\t\t\tvg=1\nG\t\tThousand Needles\t22.0\t24.0\t\t\t\nI\t\tThen do |cffffd100Hypercapacitor Gizmo|r (Elite) at |cffbbbbbb(22, 24)|r. Clear mobs around the cage, free him and kill him.\nC\t\t5151\t\t\nS\t\t\tvg=1\nI\t\tKill the |cff00ff25Galak Messenger|r, he drops 'Assassination Note' which starts |cffffd100Assassination Plot|r Turn in for Easy XP.\nA\t\t4881\t\nT\t\t5151\t\nS\t\t\tvg=1\nI\t\tThen do: |cffffd100Protect Kanati Greycloud|r\nC\t\t4966\t\t\nS\t\t\tvg=1;title=If you are not at least 4 bars from level 30, grind until you...\nI\t\tIf you are not at least 4 bars from level 30, grind until you are. Then hearth back to Freewind Post.\nS\t\t\tvg=1\nT\t\t4904\t\nT\t\t5147\t\nT\t\t5064\t\nS\t\t\tvg=1;title=NOTE: I skip Test of Endurance\nI\t\tNOTE: I skip |cff00ff25Test of Endurance|r\nS\t\t\tvg=1;title=Fly to Orgrimmar\nI\t\tFly to Orgrimmar\nS\t\t\tvg=1;title=Make Orgrimmar your home\nI\t\tMake Orgrimmar your home.\nS\t\t\tvg=1;title=Get new spells/abilities\nI\t\tGet new spells/abilities.\nS\t\t\tvg=1;title=Go to Undercity (UC)\nI\t\tGo to Undercity (UC). You need to get on the zeppelin just right outside of Orgrimmar.\nS\t\t\tvg=1;title=Run to Tarren Mill in Hillsbrad Foothills\nI\t\tRun to Tarren Mill in Hillsbrad Foothills.. (You can just bypass the UC for now if you like and just follow the path south out of Tirisfal Glades and into Silverpine Forest)" },
  { name = "29-30 Hillsbrad Foothills (Horde)", title = "29-30 Hillsbrad Foothills", group = "VanillaGuide 20-40", faction = "Horde", lo = 29, hi = 30, next = "30-30 Alterac Mountains (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tAccept |cffffd100Time To Strike|r (at the Southpoint Tower, right when u enter Hillsbrad)\nA\t\t494\t\nS\t\t\tvg=1;title=Once at Tarren Mill\nI\t\tOnce at Tarren Mill:\nS\t\t\tvg=1\nT\t\t494\t\nS\t\t\tvg=1\nA\t\t552\t\nS\t\t\tvg=1\nA\t\t501\t\nS\t\t\tvg=1;title=GET FLIGHT PATH THERE!!!!\nI\t\tGET FLIGHT PATH THERE!!!!\nS\t\t\tvg=1;title=Go start killing Yetis\nI\t\tGo start killing Yetis...\nS\t\t\tvg=1;title=I keep grinding away at Yetis until I hit 30\nI\t\tI keep grinding away at Yetis until I hit 30. (OPTIONAL: you could go do RFK instead of the grinding)\nS\t\t\tvg=1;title=Also, the Helcular's Rod should have dropped before hitting 30...\nI\t\tAlso, the |cff00ff25Helcular's Rod|r should have dropped before hitting 30, if not keep grinding away till it does.\nS\t\t\tvg=1;title=As soon as i hit 30, I hearth to Orgrimmar to get new...\nI\t\tAs soon as i hit 30, I hearth to Orgrimmar to get new spells/abilities.\nS\t\t\tvg=1;title=Go back to Hillsbrad\nI\t\tThen go back to Hillsbrad.\nS\t\t\tvg=1\nT\t\t552\t\nS\t\t\tvg=1;title=Go back to the Yeti cave\nI\t\tGo back to the Yeti cave...\nS\t\t\tvg=1\nI\t\tCharge The Flame of Azel and the Flame of Veraz, for the quest |cffffd100Helcular's Revenge|r\nC\t\t552\t\t\nS\t\t\tvg=1;title=I keep grinding away at Yetis until my pet levels up\nI\t\tI keep grinding away at Yetis until my pet levels up.\nS\t\t\tvg=1;title=Go up into Alterac Mountains\nI\t\tGo up into Alterac Mountains..." },
  { name = "30-30 Alterac Mountains (Horde)", title = "30-30 Alterac Mountains", group = "VanillaGuide 20-40", faction = "Horde", lo = 30, hi = 30, next = "30-30 Arathi Highlands (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tDo |cffffd100Elixir of Pain|r, killing the level 32-34 |cff00ff25Mountain Lions|r on the plateaus.\nC\t\t501\t\t\nS\t\t\tvg=1\nI\t\tCharge the third flame |cfffca742Flame of Uzel|r, for the quest |cffffd100Helcular's Revenge|r\nC\t\t552\t\t\nS\t\t\tvg=1;title=Kill Frostmaw (level 37 mob), it's a tough battle so prepare...\nI\t\tKill |cff00ff25Frostmaw|r (level 37 mob), it's a tough battle so prepare yourself! A group may be needed.\nS\t\t\tvg=1\nI\t\tRun down to Southshore, to drive the rod into |cfffca742Helcular's grave|r, completing |cffffd100Helcular's Revenge|r\nT\t\t552\t\nS\t\t\tvg=1;title=Run back to Tarren Mill\nI\t\tRun back to Tarren Mill\nS\t\t\tvg=1\nT\t\t501\t\nS\t\t\tvg=1\nA\t\t676\t\nS\t\t\tvg=1;title=Run into Arathi Highlands\nI\t\tRun into Arathi Highlands." },
  { name = "30-30 Arathi Highlands (Horde)", title = "30-30 Arathi Highlands", group = "VanillaGuide 20-40", faction = "Horde", lo = 30, hi = 30, next = "30-31 Stranglethorn Vale (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tArathi Highlands\t34.0\t45.0\t\t\t\nI\t\tDo |cffffd100The Hammer May Fall|r at |cffbbbbbb(34, 45)|r\nC\t\t676\t\t\nS\t\t\tvg=1;title=Run to Hammerfall\nG\t\tArathi Highlands\t73.0\t36.0\t\t\t\nI\t\tThen run to Hammerfall at |cffbbbbbb(73, 36)|r\nS\t\t\tvg=1\nA\t\t655\t\nS\t\t\tvg=1\nT\t\t655\t\nA\t\t672\t\nS\t\t\tvg=1\nT\t\t676\t\nS\t\t\tvg=1;title=Get the flightpath there\nI\t\tGet the flightpath there.\nS\t\t\tvg=1\nG\t\tArathi Highlands\t64.0\t37.0\t\t\t\nI\t\tThen do |cffffd100Raising Spirits|r, just to the left of Hammerfall all around |cffbbbbbb(64, 37)|r. Turn it in and accept |cffffd100Raising Spirits pt.2|r\nC\t\t672\t\t\nS\t\t\tvg=1\nT\t\t672\t\nA\t\t674\t\nS\t\t\tvg=1\nT\t\t674\t\nA\t\t675\t\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Raising Spirits pt.3|r, skip SKIPGuile of the Raptor for now\nT\t\t675\t\nS\t\t\tvg=1;title=Hearth to Orgrimmar\nI\t\tHearth to Orgrimmar. Put |cfffca742[Frostmaw's Mane]|r into the bank to save bagspace. It will not be turned in until level 43.\nS\t\t\tvg=1;title=Fly to Crossroads\nI\t\tFly to Crossroads.\nS\t\t\tvg=1\nI\t\tRun west in the Crossroads, accept |cffffd100The Swarm Grows|r\nA\t\t1145\t\nS\t\t\tvg=1\nI\t\tThen run west from the Crossroads to the guy in the hut, accept |cffffd100The Kolkar of Desolace|r\nA\t\t1362\t\nS\t\t\tvg=1;title=Run back to Crossroads and make it your home\nI\t\tRun back to Crossroads and make it your home.\nS\t\t\tvg=1;title=Fly to Ratchet and get on the boat to Booty Bay\nI\t\tFly to Ratchet and get on the boat to Booty Bay." },
  { name = "30-31 Stranglethorn Vale (Horde)", title = "30-31 Stranglethorn Vale", group = "VanillaGuide 20-40", faction = "Horde", lo = 30, hi = 31, next = "31-32 TN (Shimmering Flats) (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=Get the flightpath in Booty Bay, and run up to Grom'Gol...\nI\t\tGet the flightpath in Booty Bay, and run up to Grom'Gol, getting the flightpath there too.\nS\t\t\tvg=1;title=Go up north and start doing the Stranglethorn hunting quests\nG\t\tStranglethorn Vale\t35.0\t10.0\t\t\t\nI\t\tGo up north |cffbbbbbb(35, 10)|r and start doing the Stranglethorn hunting quests\nS\t\t\tvg=1\nI\t\t|cffffd100Welcome to the Jungle|r, accept and turn it in.\nC\t\t583\t\t\nS\t\t\tvg=1\nT\t\t583\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t33.0\t10.0\t\t\t\nI\t\t|cffffd100Tiger Mastery|r, |cff00ff25Young Stranglethorn Tigers|r at |cffbbbbbb(33, 10)|r\nC\t\t185\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t41.0\t9.0\t\t\t\nI\t\t|cffffd100Panther Mastery|r, |cff00ff25Young Panthers|r at COORD[41.09]\nC\t\t190\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t30.0\t11.0\t\t\t\nI\t\t|cffffd100Panther Mastery|r, |cff00ff25Panthers|r at |cffbbbbbb(30, 11)|r\nC\t\t190\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t30.0\t11.0\t\t\t\nI\t\t|cffffd100Tiger Mastery|r, |cff00ff25Stranglethorn Tigers|r at |cffbbbbbb(30, 10)|r\nC\t\t185\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t25.0\t15.0\t\t\t\nI\t\t|cffffd100Raptor Mastery|r, |cff00ff25Stranglethorn Raptors|r at |cffbbbbbb(25, 15)|r\nC\t\t194\t\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Tiger Mastery|r, |cff00ff25Elder Stranglethorn Tigers|r, but don't do it now.\nA\t\t185\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Raptor Mastery|r, |cff00ff25Lashtail Raptors|r, but don't do it now.\nA\t\t194\t\nS\t\t\tvg=1;title=Skip the rest for now\nI\t\tSkip the rest for now.\nS\t\t\tvg=1;title=You should be level 31 for sure, if not grind to it\nI\t\tYou should be level 31 for sure, if not grind to it\nS\t\t\tvg=1;title=Hearth to Crossroads\nI\t\tHearth to Crossroads.\nS\t\t\tvg=1;title=Fly to Thousand Needles\nI\t\tFly to Thousand Needles.\nS\t\t\tvg=1;title=Go east into Shimmering Flats\nG\t\tThousand Needles\t77.0\t77.0\t\t\t\nI\t\tGo east into Shimmering Flats at |cffbbbbbb(77, 77)|r." },
  { name = "31-32 TN (Shimmering Flats) (Horde)", title = "31-32 TN (Shimmering Flats)", group = "VanillaGuide 20-40", faction = "Horde", lo = 31, hi = 32, next = "32-34 Desolace (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=31-32 Thousand Needles (Shimmering Flats)\nI\t\t31-32 Thousand Needles (Shimmering Flats)\nS\t\t\tvg=1\nA\t\t5762\t\nA\t\t1111\t\nS\t\t\tvg=1\nI\t\tAccept and do the following together: |cffffd100A Bump in the Road|r, |cffffd100Hardened Shells|r, |cffffd100Load Lightening|r, |cffffd100Rocket Car Parts|r, |cffffd100Salt Flat Venom|r.\nC\t\t1175\t\t\nC\t\t1105\t\t\nC\t\t1176\t\t\nC\t\t1110\t\t\nC\t\t1104\t\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Goblin Sponsorship|r and |cffffd100Martk the Exiled|r, SKIP SKIPEncrusted Tail Fins (Elite).\nA\t\t1178\t\nA\t\t1106\t\nS\t\t\tvg=1;title=Go south into Tanaris to get flightpath in Gadgetzan\nG\t\tTanaris\t51.0\t25.0\t\t\t\nI\t\tGo south into Tanaris to get flightpath in Gadgetzan at |cffbbbbbb(51, 25)|r\nS\t\t\tvg=1;title=Hearth to Crossroads fly to Orgrimmar\nI\t\tHearth to Crossroads fly to Orgrimmar.\nS\t\t\tvg=1\nC\t\t1145\t\t\nS\t\t\tvg=1\nG\t\tOrgrimmar\t75.0\t34.0\t\t\t\nT\t\t1145\t\nT\t\t1146\t\nA\t\t1146\t\nS\t\t\tvg=1\nG\t\tOrgrimmar\t47.0\t50.0\t\t\t\nI\t\tAccept |cffffd100Alliance Relations|r from |cff00ff25Craven Drok|r in the Cleft of Shadow, |cffbbbbbb(47, 50)|r\nA\t\t1431\t\nS\t\t\tvg=1\nG\t\tOrgrimmar\t47.0\t50.0\t\t\t\nC\t\t1431\t\t\nS\t\t\tvg=1\nG\t\tOrgrimmar\t23.0\t53.0\t\t\t\nI\t\tThen go to |cff00ff25Keldran|r in Orgrimmar |cffbbbbbb(23, 53)|r to accept |cffffd100Alliance Relations pt.2|r.\nT\t\t1431\t\nA\t\t1432\t\nS\t\t\tvg=1;title=Fly to Stonetalon Mountains, and run in to Desolace\nI\t\tFly to Stonetalon Mountains, and run in to Desolace." },
  { name = "32-34 Desolace (Horde)", title = "32-34 Desolace", group = "VanillaGuide 20-40", faction = "Horde", lo = 32, hi = 34, next = "34-35 Stranglethorn Vale (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tDesolace\t55.0\t24.0\t\t\t\nI\t\tFirst thing to do here is start killing mobs at the Thunder Axe Fortress |cffbbbbbb(55, 24)|r until |cfffca742[Flayed Demon Skin]|r dropps, which starts |cffffd100The Corrupter|r.\nA\t\t1481\t\nS\t\t\tvg=1\nG\t\tDesolace\t60.0\t61.0\t\t\t\nI\t\tAfter you got it, go do |cffffd100Kodo Roundup|r, it starts at |cffbbbbbb(60, 61)|r.\nC\t\t5561\t\t\nS\t\t\tvg=1;title=Go to Ghost Walker Post\nG\t\tDesolace\t56.0\t59.0\t\t\t\nI\t\tThen go to Ghost Walker Post |cffbbbbbb(56, 59)|r\nS\t\t\tvg=1\nT\t\t1362\t\nA\t\t1365\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Gelkis Alliance|r, skip SKIPMagram Alliance.\nA\t\t1368\t\nS\t\t\tvg=1\nG\t\tOrgrimmar\t23.0\t53.0\t\t\t\nC\t\t1432\t\t\nS\t\t\tvg=1\nT\t\t1432\t\nA\t\t5386\t\nT\t\t1433\t\nA\t\t1432\t\nA\t\t1434\t\nS\t\t\tvg=1\nT\t\t1481\t\nA\t\t1481\t\nS\t\t\tvg=1\nT\t\t1432\t\nA\t\t1435\t\nS\t\t\tvg=1\nG\t\tDesolace\t75.0\t22.0\t\t\t\nI\t\tGo do |cffffd100Befouled by Satyr|r and |cffffd100The Corrupter pt.2|r at |cffbbbbbb(75, 22)|r.\nC\t\t1434\t\t\nC\t\t1481\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t73.0\t48.0\t\t\t\nI\t\tDo |cffffd100Khan Dez'hepah|r, at |cffbbbbbb(73, 48)|r\nC\t\t1365\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t68.0\t71.0\t\t\t\nI\t\tDo |cffffd100Gelkis Alliance|r, at |cffbbbbbb(68, 71)|r\nC\t\t1368\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t56.0\t59.0\t\t\t\nI\t\tGo back to Ghost Walker Post |cffbbbbbb(56, 59)|r, and turn in |cffffd100Khan Dez'hepah|r, accept |cffffd100Centaur Bounty|r.\nT\t\t1365\t\nA\t\t1366\t\nT\t\t1434\t\nT\t\t1481\t\nA\t\t1482\t\nS\t\t\tvg=1\nG\t\tDesolace\t36.0\t79.0\t\t\t\nI\t\tThen run to Shadowprey Village, stopping along the way to turn in |cffffd100Gelkis Alliance|r at |cffbbbbbb(36, 79)|r, accept |cffffd100Stealing Supplies|r\nT\t\t1368\t\nA\t\t1370\t\nS\t\t\tvg=1\nG\t\tDesolace\t24.0\t71.0\t\t\t\nI\t\tAccept all quests at Shadowprey Village at |cffbbbbbb(24, 71)|r;\nA\t\t5763\t\nA\t\t5381\t\nA\t\t6142\t\nA\t\t6143\t\nS\t\t\tvg=1;title=Make Shadowprey Village your home\nI\t\tMake Shadowprey Village your home.\nS\t\t\tvg=1;title=Go in the water and collect 10 Shellfish, from the Shellfish...\nI\t\tGo in the water and collect 10 |cff00ff25Shellfish|r, from the Shellfish traps.\nS\t\t\tvg=1;title=Turn those in at Jinar'Zillen for 2 Bloodbelly Fish\nI\t\tTurn those in at |cff00ff25Jinar'Zillen|r for 2 |cfffca742Bloodbelly Fish|r.\nS\t\t\tvg=1\nI\t\tTravel up the water, collecting |cfffca742Soft-shelled Clam Meat|r for the quest |cffffd100Clam Bait|r along the way\nC\t\t6142\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t36.0\t30.0\t\t\t\nI\t\tAccept |cffffd100Claim Rackmore's Treasure!|r at the chest/wrecked boat along the shore, |cffbbbbbb(36, 30)|r. The |cfffca742[Silver Key]|r is dropped by a |cff00ff25Drysnap|r, and the |cfffca742[Golden Key]|r is dropped by a |cff00ff25Slitherblade|r.\nA\t\t6161\t\nS\t\t\tvg=1\nG\t\tDesolace\t38.0\t27.0\t\t\t\nI\t\tTalk to |cff00ff25Azore Aldamort|r.\nA\t\t5741\t\nS\t\t\tvg=1\nG\t\tDesolace\t54.0\t29.0\t\t\t\nI\t\tThen go to Thunder Axe Fortress |cffbbbbbb(54, 29)|r and do |cffffd100The Burning of Spirits|r, |cffffd100Sceptre of Light|r and |cffffd100Hand of Iruxos|r.\nC\t\t1435\t\t\nC\t\t5741\t\t\nC\t\t5381\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t38.0\t27.0\t\t\t\nI\t\tGrind your way back to |cff00ff25Azore Aldamort|r |cffbbbbbb(38, 27)|r, turn in |cffffd100Sceptre of Light|r in and get |cffffd100Book of the Ancients|r.\nT\t\t5741\t\nA\t\t6027\t\nS\t\t\tvg=1\nG\t\tDesolace\t27.0\t6.0\t\t\t\nI\t\tThen head off to do |cffffd100Other Fish to Fry|r, |cffffd100Clam Bait|r, |cffffd100The Corrupter pt.3|r, |cffffd100Claim Rackmore's Treasure!|r and |cffffd100Book of the Ancients|r from the shore and out to |cffbbbbbb(27, 06)|r\nC\t\t6143\t\t\nC\t\t6142\t\t\nC\t\t1482\t\t\nC\t\t6161\t\t\nC\t\t6027\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t29.0\t8.0\t\t\t\nI\t\tTurn in |cffffd100Claim Rackmore's Treasure!|r at the little chest at |cffbbbbbb(29, 08)|r.\nT\t\t6161\t\nS\t\t\tvg=1\nG\t\tDesolace\t38.0\t27.0\t\t\t\nT\t\t6027\t\nS\t\t\tvg=1\nG\t\tDesolace\t62.0\t38.0\t\t\t\nI\t\tThen go accept |cffffd100Bone Collector|r at |cffbbbbbb(62, 38)|r, grinding mobs along the way.\nA\t\t5501\t\nS\t\t\tvg=1\nG\t\tDesolace\t56.0\t59.0\t\t\t\nI\t\tGo to Ghost Walker Post |cffbbbbbb(56, 59)|r, turn in |cffffd100Catch of the Day|r accept and turn in |cffffd100The Burning of Spirits|r, turn in |cffffd100The Corrupter pt.3|r, accept and turn in |cffffd100The Corrupter pt.4|r. Accept |cffffd100Alliance Relations|r Skip SKIPThe Corrupter pt.5.\nT\t\t5386\t\nT\t\t1435\t\nT\t\t1482\t\nT\t\t1484\t\nA\t\t1433\t\nS\t\t\tvg=1\nG\t\tDesolace\t51.0\t58.0\t\t\t\nI\t\tThen do |cffffd100Bone Collector|r at the kodo graveyard |cffbbbbbb(51, 58)|r\nC\t\t5501\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t70.0\t74.0\t\t\t\nI\t\tThen |cffffd100Centaur Bounty|r and |cffffd100Stealing Supplies|r |cffbbbbbb(70, 74)|r\nC\t\t1366\t\t\nC\t\t1370\t\t\nS\t\t\tvg=1\nG\t\tDesolace\t56.0\t59.0\t\t\t\nT\t\t1366\t\nS\t\t\tvg=1\nG\t\tDesolace\t62.0\t38.0\t\t\t\nT\t\t5501\t\nS\t\t\tvg=1;title=Hearth to Shadowprey Village\nI\t\tHearth to Shadowprey Village.\nS\t\t\tvg=1\nI\t\tYou should be level 34 by now.\nT\t\t5381\t\nT\t\t6143\t\nT\t\t6142\t\nS\t\t\tvg=1\nG\t\tDesolace\t36.0\t79.0\t\t\t\nT\t\t1370\t\nA\t\t1373\t\nS\t\t\tvg=1;title=Fly to Camp Taurajo (Barrens) run south-east into Dustwallow...\nG\t\tThe Barrens\t51.0\t79.0\t\t\t\nI\t\tFly to Camp Taurajo (Barrens) run south-east into Dustwallow Marsh |cffbbbbbb(51, 79)|r.\nS\t\t\tvg=1;title=Collect the 3 quest-objects at the Shady Rest Inn\nI\t\tCollect the 3 quest-objects at the Shady Rest Inn\nS\t\t\tvg=1\nI\t\t|cffffd100Suspicious Hoofprints|r, just right outside in front of the inn.\nA\t\t1268\t\nS\t\t\tvg=1\nI\t\t|cffffd100Lieutenant Paval Reethe|r, laying on one of the planks on the ground.\nA\t\t1269\t\nS\t\t\tvg=1\nI\t\t|cffffd100The Black Shield|r, on top of the fireplace.\nA\t\t1251\t\nS\t\t\tvg=1;title=Now run to Brackenwall Village\nG\t\tDustwallow Marsh\t35.0\t29.0\t\t\t\nI\t\tNow run to Brackenwall Village |cffbbbbbb(35, 29)|r\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100The Black Shield pt.2|r Skip SKIPThe Black Shield pt.3.\nT\t\t1268\t\nT\t\t1269\t\nT\t\t1251\t\nT\t\t1321\t\nS\t\t\tvg=1;title=Stop at the troll vendor, buy the 3 first aid books\nI\t\tStop at the troll vendor, buy the 3 first aid books.\nS\t\t\tvg=1\nI\t\tFly to Ratchet to turn in |cffffd100Goblin Sponsorship|r and |cffffd100Wharfmaster Dizzywig|r, accept |cffffd100Goblin Sponsorship pt.2|r and |cffffd100Parts for Kravel|r.\nT\t\t1178\t\nT\t\t1111\t\nA\t\t1180\t\nA\t\t1112\t\nS\t\t\tvg=1;title=Get on the boat to Booty Bay\nI\t\tGet on the boat to Booty Bay." },
  { name = "34-35 Stranglethorn Vale (Horde)", title = "34-35 Stranglethorn Vale", group = "VanillaGuide 20-40", faction = "Horde", lo = 34, hi = 35, next = "35-37 Arathi Highlands (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tTurn in |cffffd100Goblin Sponsorship pt.2|r, accept |cffffd100Goblin Sponsorship pt.3|r Make Booty Bay your home!\nT\t\t1180\t\nA\t\t1181\t\nA\t\t605\t\nA\t\t189\t\nA\t\t213\t\nA\t\t201\t\nT\t\t1181\t\nA\t\t1182\t\nS\t\t\tvg=1\nI\t\tFly to Grom'gol, and grab all the quests there; |cffffd100The Defense of Grom'gol|r, |cffffd100Mok'thardin's Enchantment|r, |cffffd100Bloodscalp Insight|r, |cffffd100Hunt for Yenniku|r, |cffffd100Trollbane|r, |cffffd100Bloody Bone Necklaces|r, |cffffd100The Vile Reef|r.\nA\t\t568\t\nA\t\t570\t\nA\t\t581\t\nA\t\t638\t\nA\t\t596\t\nA\t\t629\t\nS\t\t\tvg=1;title=Make sure you save any Green Hills of Stranglethorn pages you...\nI\t\tMake sure you save any |cfffca742[Green Hills of Stranglethorn]|r pages you find and mail them to your alt for storage, you will need them for a later quest.\nS\t\t\tvg=1;title=You will need following: Chapter 1: 1, 4, 6 and 8\nI\t\tYou will need following: Chapter 1: 1, 4, 6 and 8. Chapter 2: 10, 11, 14 and 16. Chapter 3: 18, 20, 21 and 24. Chapter 4: 25, 26, and 27.\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t25.0\t19.0\t\t\t\nI\t\tDo |cffffd100Singing Blue Shards|r at |cffbbbbbb(25, 19)|r\nC\t\t605\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t31.0\t19.0\t\t\t\nI\t\tDo |cffffd100Tiger Mastery|r, killing |cff00ff25Elder Stranglethorn Tigers|r at |cffbbbbbb(31, 19)|r\nC\t\t187\t\t\nS\t\t\tvg=1\nI\t\tDo |cffffd100Bloodscalp Ears|r, |cffffd100Hunt for Yenniku|r and |cffffd100Bloody Bone Necklaces|r (no need to complete latter at this time).\nC\t\t189\t\t\nC\t\t581\t\t\nC\t\t596\t\t\nS\t\t\tvg=1\nI\t\tDo |cffffd100Raptor Mastery|r and |cffffd100The Defense of Grom'gol|r killing |cff00ff25Lashtail Raptors|r just outside Grom'gol.\nC\t\t194\t\t\nC\t\t568\t\t\nS\t\t\tvg=1\nI\t\tGo to Grom'gol and turn in |cffffd100Hunt for Yenniku|r, accept |cffffd100Headhunting|r, turn in |cffffd100The Defense of Grom'gol|r, accept |cffffd100The Defense of Grom'gol pt.2|r\nT\t\t581\t\nA\t\t582\t\nT\t\t568\t\nA\t\t569\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t21.0\t14.0\t\t\t\nI\t\tDo |cffffd100Headhunting|r while finishing up |cffffd100Bloody Bone Necklaces|r at |cffbbbbbb(21, 14)|r\nC\t\t582\t\t\nC\t\t596\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t24.0\t24.0\t\t\t\nI\t\tDo |cffffd100The Vile Reef|r along with |cffffd100Encrusted Tail Fins|r at |cffbbbbbb(24, 24)|r. Be careful not to drown.\nC\t\t629\t\t\nC\t\t1107\t\t\nS\t\t\tvg=1;title=Go to Nesingwary's Expedition , turn in ALL quests and accept...\nG\t\tStranglethorn Vale\t35.0\t10.0\t\t\t\nI\t\tThen go to Nesingwary's Expedition |cffbbbbbb(35, 10)|r, turn in ALL quests and accept all new ones, except SKIPThe Green Hills of Stranglethorn.\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t31.0\t17.0\t\t\t\nI\t\tDo |cffffd100Tiger Mastery|r killing |cff00ff25Sin'Dall|r, he is usually on top of the hill at |cffbbbbbb(31, 17)|r. Go turn it in when done.\nC\t\t187\t\t\nS\t\t\tvg=1\nT\t\t187\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t44.0\t19.0\t\t\t\nI\t\tDo |cffffd100Hostile Takeover|r along with |cffffd100Goblin Sponsorship|r at |cffbbbbbb(44, 19)|r\nC\t\t213\t\t\nC\t\t1181\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t48.0\t21.0\t\t\t\nI\t\tDo |cffffd100Panther Mastery|r along with |cffffd100Mok'thardin's Enchantment|r, kill |cff00ff25Shadowmaw Panthers|r at |cffbbbbbb(48, 21)|r\nC\t\t191\t\t\nC\t\t570\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t36.0\t30.0\t\t\t\nI\t\tDo |cffffd100The Defense of Grom'gol pt.2|r at |cffbbbbbb(36, 30)|r\nC\t\t569\t\t\nS\t\t\tvg=1\nI\t\tHead up north and turn in |cffffd100Panther Mastery|r,accept |cffffd100Panther Mastery|r, |cff00ff25Bhag'thera|r, but don't do it now.\nT\t\t191\t\nA\t\t191\t\nS\t\t\tvg=1\nI\t\tHearth to Booty Bay, turn in |cffffd100Singing Blue Shards|r, |cffffd100Hostile Takeover|r, |cffffd100Bloodscalp Ears|r and |cffffd100Investigate the Camp|r.\nT\t\t605\t\nT\t\t213\t\nT\t\t189\t\nT\t\t201\t\nS\t\t\tvg=1\nT\t\t1182\t\nA\t\t1183\t\nS\t\t\tvg=1\nI\t\tFly to Grom'gol and turn in all quests, |cffffd100The Defense of Grom'gol|r, |cffffd100Mok'thardin's Enchantment|r, |cffffd100Headhunting|r, |cffffd100Bloody Bone Necklaces|r and |cffffd100The Vile Reef|r.\nT\t\t568\t\nT\t\t570\t\nT\t\t582\t\nT\t\t596\t\nT\t\t629\t\nS\t\t\tvg=1\nI\t\tYou should be level 36 now, if not, grind to it.\nA\t\t638\t\nS\t\t\tvg=1;title=Get on the zeppelin to the Undercity\nI\t\tGet on the zeppelin to the Undercity.\nS\t\t\tvg=1\nG\t\tUndercity\t63.0\t49.0\t\t\t\nA\t\t1164\t\nS\t\t\tvg=1;title=Fly to Hammerfall\nI\t\tThen fly to Hammerfall." },
  { name = "35-37 Arathi Highlands (Horde)", title = "35-37 Arathi Highlands", group = "VanillaGuide 20-40", faction = "Horde", lo = 35, hi = 37, next = "37-37 Alterac Mountains (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=Make Hammerfall your home\nI\t\tMake Hammerfall your home.\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Trollbane|r, SKIP SKIPSigil of Strom.\nT\t\t638\t\nS\t\t\tvg=1\nA\t\t678\t\nA\t\t671\t\nA\t\t701\t\nS\t\t\tvg=1\nI\t\tGrind your way down south and do |cffffd100Call to Arms|r.\nC\t\t678\t\t\nS\t\t\tvg=1\nG\t\tArathi Highlands\t62.0\t33.0\t\t\t\nI\t\tThen go west of Hammerfall and accept |cffffd100The Princess Trapped|r |cffbbbbbb(62, 33)|r\nA\t\t642\t\nS\t\t\tvg=1\nI\t\tThen go do |cffffd100The Princess Trapped|r while grinding your way inside the cave.\nC\t\t642\t\t\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100The Princess Trapped|r in the cave, and accept |cffffd100Stones of Binding|r.\nT\t\t642\t\nA\t\t651\t\nS\t\t\tvg=1\nT\t\t678\t\nA\t\t678\t\nS\t\t\tvg=1\nG\t\tArathi Highlands\t66.0\t29.0\t\t\t\nI\t\tDo |cffffd100Stones of Binding|r First key, just west of Hammerfall at |cffbbbbbb(66, 29)|r\nC\t\t651\t\t\nS\t\t\tvg=1\nG\t\tArathi Highlands\t54.0\t40.0\t\t\t\nI\t\tDo |cffffd100To Steal From Thieves|r at |cffbbbbbb(54, 40)|r\nC\t\t1164\t\t\nS\t\t\tvg=1\nG\t\tArathi Highlands\t52.0\t50.0\t\t\t\nI\t\tGo down south a little and get the next key for |cffffd100Stones of Binding|r, at |cffbbbbbb(52, 50)|r\nC\t\t651\t\t\nS\t\t\tvg=1\nG\t\tArathi Highlands\t50.0\t75.0\t\t\t\nI\t\tDo |cffffd100Call to Arms pt.2|r killing |cff00ff25Ogres|r, and |cffffd100Guile of the Raptor|r killing |cff00ff25Highland Fleshstalkers|r around |cffbbbbbb(50, 75)|r\nC\t\t678\t\t\nC\t\t701\t\t\nS\t\t\tvg=1\nG\t\tArathi Highlands\t31.0\t28.0\t\t\t\nI\t\tDo |cffffd100Foul Magics|r at |cffbbbbbb(31, 28)|r\nC\t\t671\t\t\nS\t\t\tvg=1\nG\t\tArathi Highlands\t25.0\t31.0\t\t\t\nI\t\tThen go west and get the last key for |cffffd100Stones of Binding|r at |cffbbbbbb(25, 31)|r\nC\t\t651\t\t\nS\t\t\tvg=1\nG\t\tArathi Highlands\t36.0\t57.0\t\t\t\nI\t\tGo discover Stromguard, and turn in |cffffd100Stones of Binding|r, at the Circle of Inner Binding |cffbbbbbb(36, 57)|r. SKIP SKIPBreaking the Keystone (Elite), unless you get a group for it.\nT\t\t651\t\nS\t\t\tvg=1;title=Hearth to Hammerfall\nI\t\tHearth to Hammerfall.\nS\t\t\tvg=1\nT\t\t671\t\nT\t\t701\t\nT\t\t678\t\nS\t\t\tvg=1\nI\t\tComplete the |cffffd100Guile of the Raptor|r quest chain by running back and forth.\nC\t\t701\t\t\nS\t\t\tvg=1;title=Fly to Tarren Mill\nI\t\tFly to Tarren Mill." },
  { name = "37-37 Alterac Mountains (Horde)", title = "37-37 Alterac Mountains", group = "VanillaGuide 20-40", faction = "Horde", lo = 37, hi = 37, next = "37-37 Thousand Needles (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nI\t\tOnce at Tarren Mill, accept |cffffd100Stone Tokens|r and |cffffd100Prison Break In|r go do them in Alterac Mountains at Dalaran.\nA\t\t556\t\nA\t\t544\t\nS\t\t\tvg=1\nG\t\tAlterac Mountains\t19.93\t85.94\t\t\t\nC\t\t544\t\t\nS\t\t\tvg=1\nG\t\tAlterac Mountains\t19.4\t75.6\t\t\t\nC\t\t556\t\t\nS\t\t\tvg=1\nI\t\tThen turn them in and accept |cffffd100Dalaran Patrols|r and |cffffd100Bracers of Binding|r, doing them a bit further north the last two.\nT\t\t544\t\nT\t\t556\t\nA\t\t545\t\nA\t\t557\t\nS\t\t\tvg=1;title=Once they are both completed, die on purpose, so you end up at...\nI\t\tOnce they are both completed, die on purpose, so you end up at Tarren Mill.\nS\t\t\tvg=1;title=Turn them in fly to Undercity\nI\t\tTurn them in fly to Undercity.\nS\t\t\tvg=1\nI\t\tOnce in Undercity, turn in |cffffd100To Steal From Thieves|r and buy 3xNPCSoothing Spices\nT\t\t1164\t\nS\t\t\tvg=1;title=Get on zeppelin to Orgrimmar\nI\t\tGet on zeppelin to Orgrimmar.\nS\t\t\tvg=1\nG\t\tOrgrimmar\t21.0\t53.0\t\t\t\nI\t\tOnce in Orgrimmar, turn in |cffffd100Alliance Relations|r at |cff00ff25Keldran|r at |cffbbbbbb(21, 53)|r\nT\t\t1431\t\nS\t\t\tvg=1;title=Fly to Crossroads, making it your home\nI\t\tFly to Crossroads, making it your home.\nS\t\t\tvg=1;title=Fly to Freewind Post (Thousand Needles)\nI\t\tFly to Freewind Post (Thousand Needles)." },
  { name = "37-37 Thousand Needles (Horde)", title = "37-37 Thousand Needles", group = "VanillaGuide 20-40", faction = "Horde", lo = 37, hi = 37, next = "37-38 Dustwallow Marsh (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=Run towards the Shimmering Flats\nI\t\tRun towards the Shimmering Flats..\nS\t\t\tvg=1\nG\t\tThousand Needles\t67.0\t63.0\t\t\t\nT\t\t1147\t\nA\t\t1146\t\nS\t\t\tvg=1\nC\t\t1183\t\t\nS\t\t\tvg=1\nI\t\tStop at the goblins and turn in |cffffd100Parts for Kravel|r, accept |cffffd100Delivery to the Gnomes|r, turn in |cffffd100Delivery to the Gnomes|r, turn in |cffffd100Goblin Sponsorship pt.3|r, accept |cffffd100The Eighteenth Pilot|r, turn in |cffffd100The Eighteenth Pilot|r, accept |cffffd100Razzeric's Tweaking|r, turn in |cffffd100Encrusted Tail Fins|r, lastly accept |cffffd100The Rumormonger|r.\nT\t\t1183\t\nT\t\t1112\t\nA\t\t1114\t\nT\t\t1114\t\nT\t\t1181\t\nA\t\t1186\t\nT\t\t1186\t\nA\t\t1187\t\nT\t\t1107\t\nA\t\t1115\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t71.0\t85.0\t\t\t\nI\t\tDo |cffffd100The Swarm Grows|r and |cffffd100Parts of the Swarm|r (quest starts from an item drop) at |cffbbbbbb(71, 85)|r\nC\t\t1147\t\t\nC\t\t1148\t\t\nS\t\t\tvg=1\nG\t\tThousand Needles\t67.0\t63.0\t\t\t\nT\t\t1147\t\nS\t\t\tvg=1;title=Hearth to Crossroads\nI\t\tHearth to Crossroads\nS\t\t\tvg=1\nT\t\t1148\t\nA\t\t1184\t\nS\t\t\tvg=1;title=Fly to Dustwallow Marsh\nI\t\tFly to Dustwallow Marsh." },
  { name = "37-38 Dustwallow Marsh (Horde)", title = "37-38 Dustwallow Marsh", group = "VanillaGuide 20-40", faction = "Horde", lo = 37, hi = 38, next = "38-40 Stranglethorn Vale (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nA\t\t1201\t\nA\t\t1322\t\nS\t\t\tvg=1\nG\t\tDustwallow Marsh\t35.0\t37.0\t\t\t\nI\t\tGo slightly south of Brackenwall Village and accept |cffffd100Hungry!|r from the ogre at |cffbbbbbb(35, 37)|r\nA\t\t1177\t\nS\t\t\tvg=1\nG\t\tDustwallow Marsh\t58.0\t23.0\t\t\t\nI\t\tDo |cffffd100Theramore Spies|r and |cffffd100The Black Shield pt.3|r. Do |cffffd100Hungry!|r at |cffbbbbbb(58, 23)|r\nC\t\t1201\t\t\nC\t\t1322\t\t\nC\t\t1177\t\t\nS\t\t\tvg=1\nG\t\tDustwallow Marsh\t55.0\t25.0\t\t\t\nI\t\tStop at Jarl's cabin |cffbbbbbb(55, 25)|r, get |cffffd100The Lost Report|r by clicking the dirt mound next to his cabin, turn in |cffffd100Soothing Spices|r and accept |cffffd100Jarl Needs Eyes|r.\nA\t\t1238\t\nT\t\t1218\t\nA\t\t1206\t\nS\t\t\tvg=1;title=Go south to retrive the Seaforium Booster for Razzeric\nG\t\tDustwallow Marsh\t54.0\t56.0\t\t\t\nI\t\tGo south at |cffbbbbbb(54, 56)|r to retrive the |cfffca742[Seaforium Booster]|r for Razzeric.\nS\t\t\tvg=1\nI\t\tDo |cffffd100Jarl Needs Eyes|r.\nC\t\t1206\t\t\nS\t\t\tvg=1\nG\t\tDustwallow Marsh\t47.0\t18.0\t\t\t\nI\t\tDo the escort quest |cffffd100Stinky's Escape|r that starts at |cffbbbbbb(47, 18)|r.\nC\t\t1270\t\t\nS\t\t\tvg=1\nI\t\tStop at Brackenwall Village and turn in all quests, accept new ones.\nT\t\t1177\t\nS\t\t\tvg=1\nG\t\tDustwallow Marsh\t55.0\t25.0\t\t\t\nC\t\t1238\t\t\nS\t\t\tvg=1\nG\t\tDustwallow Marsh\t55.0\t25.0\t\t\t\nI\t\tGo to Jarl's cabin at |cffbbbbbb(55, 25)|r, go to the |cfffca742Dirt Mound|r once again to get |cffffd100The Severed Head|r, turn in |cffffd100Jarl Needs Eyes|r, SKIP SKIPJarl Needs a Blade\nT\t\t1238\t\nA\t\t1239\t\nT\t\t1206\t\nS\t\t\tvg=1;title=Grind some at the raptors and such, at this point you should be...\nI\t\tGrind some at the raptors and such, at this point you should be a little over half way to 39.\nS\t\t\tvg=1\nG\t\tDustwallow Marsh\t71.0\t51.0\t\t\t\nI\t\tDo |cffffd100The Theramore Docks|r, the |cfffca742[Captain's Documents]|r are under the water at |cffbbbbbb(71, 51)|r\nC\t\t1202\t\t\nS\t\t\tvg=1;title=Die on purpose, so you end up right at Brackenwall Village\nI\t\tThen die on purpose, so you end up right at Brackenwall Village.\nS\t\t\tvg=1\nT\t\t1202\t\nT\t\t1239\t\nA\t\t1240\t\nS\t\t\tvg=1\nI\t\tHearth to Crossroads, fly to Ratchet and turn in |cffffd100Stinky's Escape|r get on the boat to Booty Bay.\nT\t\t1270\t" },
  { name = "38-40 Stranglethorn Vale (Horde)", title = "38-40 Stranglethorn Vale", group = "VanillaGuide 20-40", faction = "Horde", lo = 38, hi = 40, next = "40-41 Badlands (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nA\t\t595\t\nA\t\t600\t\nA\t\t606\t\nS\t\t\tvg=1\nI\t\tMake Booty Bay your home go up the steps and turn in |cffffd100The Rumormonger|r. Fly to Grom'gol.\nT\t\t1115\t\nS\t\t\tvg=1\nI\t\tRight click the cauldron and accept |cffffd100Marg Speaks|r.\nA\t\t570\t\nT\t\t1240\t\nA\t\t1261\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t31.0\t41.0\t\t\t\nI\t\tDo |cffffd100Raptor Mastery|r along with |cffffd100Mok'thardin's Enchantment|r at |cffbbbbbb(31, 41)|r, kill |cff00ff25Jungle Stalkers|r.\nC\t\t196\t\t\nC\t\t570\t\t\nS\t\t\tvg=1;title=Grind away at raptors/cold eye ballisks till level 39\nI\t\tGrind away at raptors/cold eye ballisks till level 39.\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t40.0\t42.0\t\t\t\nI\t\tDo |cffffd100Venture Company Mining|r at |cffbbbbbb(40, 42)|r\nC\t\t600\t\t\nS\t\t\tvg=1\nI\t\tOnce that is done, go back to Grom'Gol and turn in |cffffd100Mok'thardin's Enchantment pt.2|r, accept |cffffd100Mok'thardin's Enchantment pt.3|r.\nT\t\t572\t\nA\t\t571\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t48.0\t20.0\t\t\t\nI\t\tDo |cffffd100Panther Mastery|r, kill |cff00ff25Bhag'thera|r (he has 3 different spawn points, |cffbbbbbb(48, 20)|r, |cffbbbbbb(49, 23)|r, and |cffbbbbbb(47, 26)|r)\nC\t\t192\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t35.0\t10.0\t\t\t\nI\t\tTurn in |cffffd100Panther Mastery|r and |cffffd100Raptor Mastery|r at Nesingwary's Expedition |cffbbbbbb(35, 10)|r\nT\t\t192\t\nT\t\t196\t\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Raptor Mastery|r for |cff00ff25Tethis|r, but don't do it now.\nA\t\t196\t\nS\t\t\tvg=1\nI\t\tHearth to Booty Bay, turn in |cffffd100Venture Company Mining|r.\nT\t\t600\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t27.0\t69.0\t\t\t\nI\t\tGo do |cffffd100The Bloodsail Buccaneers|r north-west of Booty Bay at |cffbbbbbb(27, 69)|r, there's a little note on a barrel, click on it, accept new quest.\nC\t\t595\t\t\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t32.0\t66.0\t\t\t\nI\t\tDo |cffffd100Scaring Shaky|r along with |cffffd100Mok'thardin's Enchantment pt.3|r at |cffbbbbbb(32, 66)|r.\nC\t\t606\t\t\nC\t\t571\t\t\nS\t\t\tvg=1\nI\t\tRun back to Booty Bay, turn in |cffffd100Scaring Shaky|r, accept |cffffd100Return to MacKinley|r, turn in |cffffd100The Bloodsail Buccaneers|r, accept |cffffd100The Bloodsail Buccaneers pt.2|r, turn in |cffffd100Return to MacKinley|r\nT\t\t606\t\nA\t\t607\t\nT\t\t595\t\nA\t\t597\t\nT\t\t607\t\nT\t\t595\t\nS\t\t\tvg=1\nI\t\tFly to Grom'gol, turn in |cffffd100Mok'thardin's Enchantment pt.3|r, accept |cffffd100Mok'thardin's Enchantment pt.4|r\nT\t\t571\t\nA\t\t573\t\nS\t\t\tvg=1;title=You should be level 40 for sure now\nI\t\tYou should be level 40 for sure now. If not, grind the rest of the way to 40 on Raptors/Cold Eye Basilisks.\nS\t\t\tvg=1;title=Get on the zeppelin to Undercity\nI\t\tThen get on the zeppelin to Undercity.\nS\t\t\tvg=1;title=Check the Aution House for Frost Oil, Gyrochronatom, Healing...\nI\t\tCheck the Aution House for |cfffca742[Frost Oil]|r, |cfffca742[Gyrochronatom]|r, |cfffca742[Healing Potion]|r, |cfffca742[Lesser Invisibility Potion]|r and |cfffca742[Patterned Bronze Bracers]|r for some fast quests in Badlands.\nS\t\t\tvg=1;title=Fly to Hammerfall run all the way to Badlands\nI\t\tFly to Hammerfall run all the way to Badlands." },
  { name = "40-41 Badlands (Horde)", title = "40-41 Badlands", group = "VanillaGuide 40-60", faction = "Horde", lo = 40, hi = 41, next = "41-42 Swamp of Sorrows (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1;title=The goal here is not to leave till you're level 41, so grind...\nG\t\tBadlands\t42.0\t52.0\t\t\t\nI\t\tThe goal here is not to leave till you're level 41, so grind mobs everywhere you go. As you enter Badlands, run southwest to |cffbbbbbb(42, 52)|r.\nS\t\t\tvg=1\nG\t\tBadlands\t42.0\t52.0\t\t\t\nT\t\t1106\t\nA\t\t1108\t\nA\t\t703\t\nS\t\t\tvg=1\nG\t\tBadlands\t51.0\t67.0\t\t\t\nI\t\tGo down south a little and do |cffffd100Indurium|r |cffbbbbbb(51, 67)|r\nC\t\t1108\t\t\nS\t\t\tvg=1\nT\t\t1108\t\nA\t\t1137\t\nS\t\t\tvg=1\nG\t\tBadlands\t25.0\t44.0\t\t\t\nI\t\tNOTE: If you have the |cfffca742[Frost Oil]|r, the |cfffca742[Gyrochronatom]|r, the |cfffca742[Healing Potion]|r, the |cfffca742[Lesser Invisibility Potion]|r and the |cfffca742[Patterned Bronze Bracers]|r items, accept and complete all the quests there.\nA\t\t711\t\nS\t\t\tvg=1;title=Grind your way west to Kargath\nG\t\tBadlands\t4.0\t46.0\t\t\t\nI\t\tGrind your way west to Kargath |cffbbbbbb(04, 46)|r.\nS\t\t\tvg=1;title=Get flightpath at Kargath\nI\t\tGet flightpath at Kargath. Do NOT make Kargath your home, it should still be Booty Bay.\nS\t\t\tvg=1\nA\t\t1419\t\nA\t\t1420\t\nA\t\t782\t\nA\t\t2258\t\nS\t\t\tvg=1\nG\t\tBadlands\t14.0\t60.0\t\t\t\nI\t\tGo do |cffffd100Coyote Thieves|r and |cffffd100Barbecued Buzzard Wings|r around |cffbbbbbb(14, 60)|r\nC\t\t1419\t\t\nC\t\t703\t\t\nS\t\t\tvg=1\nI\t\tDo |cffffd100Broken Alliances|r, |cff00ff25 Tho'grun|r patrols the area counter-clockwise. (skip the next part of this quest).\nC\t\t782\t\t\nS\t\t\tvg=1\nI\t\tDo |cffffd100Badlands Reagent Run|r.\nC\t\t2258\t\t\nS\t\t\tvg=1\nG\t\tBadlands\t19.0\t43.0\t\t\t\nI\t\tDo |cffffd100Study of the Elements: Rock|r, kill |cff00ff25Lesser Rock Elemental|r at |cffbbbbbb(19, 43)|r. Turn in, accept next.\nC\t\t711\t\t\nS\t\t\tvg=1\nG\t\tBadlands\t13.0\t35.0\t\t\t\nI\t\tDo |cffffd100Study of the Elements: Rock|r, kill |cff00ff25Rock Elemental|r at |cffbbbbbb(13, 35)|r. Turn in, accept next.\nC\t\t711\t\t\nS\t\t\tvg=1\nG\t\tBadlands\t8.0\t84.0\t\t\t\nI\t\tDo |cffffd100Study of the Elements: Rock|r, kill |cff00ff25Greater Rock Elemental|r at |cffbbbbbb(8, 84)|r.\nC\t\t711\t\t\nS\t\t\tvg=1\nI\t\tThen make sure all Badlands quests besides |cffffd100Report to Helgrum|r are done and turned in.\nA\t\t1420\t\nS\t\t\tvg=1;title=You should be about level 41 right now, if not grind to it\nI\t\tYou should be about level 41 right now, if not grind to it.\nS\t\t\tvg=1\nG\t\tStranglethorn Vale\t27.0\t77.0\t\t\t\nI\t\tHearth to BB and check if you have |cffffd100Dream Dust in the Swamp|r in your questlog. If not, go accept it from |cff00ff25Krazek|r at |cffbbbbbb(27, 77)|r\nC\t\t1116\t\t\nS\t\t\tvg=1;title=Fly to Grom'gol\nI\t\tFly to Grom'gol.\nS\t\t\tvg=1;title=Go turn in all the The Green Hills of Stranglethorn...\nG\t\tBadlands\t35.0\t10.0\t\t\t\nI\t\tGo turn in all the |cff00ff25The Green Hills of Stranglethorn Chapters/Quests|r at Nesingwary's Expedition |cffbbbbbb(35, 10)|r if you have all the pages for it, if not you have another chance to turn this in again later. You can also look in the AH for your missing pages.\nS\t\t\tvg=1\nG\t\tDuskwood\t87.0\t35.0\t\t\t\nI\t\tThen run all the way to Swamp of Sorrows, stopping along the way to accept |cffffd100Nothing But the Truth|r in Duskwood at |cffbbbbbb(87, 35)|r\nA\t\t1372\t\nS\t\t\tvg=1\nI\t\tTurn in |cffffd100Nothing But the Truth|r at the guy next to the questiver. run to Swamp of Sorrows.\nT\t\t1372\t\nA\t\t1383\t" },
  { name = "41-42 Swamp of Sorrows (Horde)", title = "41-42 Swamp of Sorrows", group = "VanillaGuide 40-60", faction = "Horde", lo = 41, hi = 42, next = "42-43 Stranglethorn Vale (Horde)", defaultFor = "", cond = "Horde", vanilla = true,
    steps = "S\t\t\tvg=1\nG\t\tSwamp of Sorrows\t14.0\t59.0\t\t\t\nI\t\tStart off by doing |cffffd100Dream Dust in the Swamp|r |cffbbbbbb(14, 59)|r.\nC\t\t1116\t\t\nS\t\t\tvg=1\nG\t\tSwamp of Sorrows\t6.0\t32.0\t\t\t\nI\t\t|cffffd100Nothing But the Truth|r kill the |cff00ff25Mire Lord|r for the |cfffca742[Mire Lord Fungus]|r at |cffbbbbbb(06, 32)|r\nC\t\t1372\t\t\nS\t\t\tvg=1\nG\t\tSwamp of Sorrows\t48.0\t38.0\t\t\t\nI\t\tFind and kill |cff00ff25Cudgel|r, he drops |cfffca742[Noboru's Cudgel]|r, which starts |cffffd100Noboru the Cudgel|r. Spawns at |cffbbbbbb(48, 38)|r, but roams the area.\nA\t\t40030\t\nS\t\t\tvg=1\nG\t\tSwamp of Sorrows\t25.0\t31.0\t\t\t\nT\t\t40030\t\nA\t\t1389\t\nS\t\t\tvg=1;title=Grind your way to Stonard , make it your home, and pick up the...\nG\t\tSwamp of Sorrows\t45.0\t54.0\t\t\t\nI\t\tGrind your way to Stonard |cffbbbbbb(45, 54)|r, make it your home, and pick up the flightpath\nS\t\t\tvg=1\nI\t\tAccept |cffffd100Lack of Surplus|r and |cffffd100Fresh Meat|r, turn in |cffffd100Report to Helgrum|r, accept |cffffd100Pool of Tears|r (Elite).\nA\t\t699\t\nA\t\t1430\t\nT\t\t1420\t\nA\t\t1424\t\nS\t\t\tvg=1\nI\t\tDo |cffffd100Pool of Tears|r, |cfffca742[Atal'ai Artifact]|r is looted in the water around temple of Atal'hakkar (Sunken Temple).\nC\t\t1424\t\t\nS\t\t\tvg=1\nG\t\tSwamp of Sorrows\t81.0\t80.0\t\t\t\nI\t\tDo |cffffd100Lack of Surplus|r then turn it in at |cffbbbbbb(81, 80)|r, accept |cffffd100Lack of Surplus pt.2|r and go do it.\nC\t\t699\t\t\nS\t\t\tvg=1\nG\t\tSwamp of Sorrows\t81\t80\t\t\t\nT\t\t699\t\nA\t\t699\t\nS\t\t\tvg=1\nI\t\tGo do |cffffd100Fresh Meat|r and |cffffd100Nothing But the Truth|r, |cff00ff25Shadow Panthers|r' hearts.\nC\t\t1430\t\t\nC\t\t1372\t\t\nS\t\t\tvg=1\nG\t\tSwamp of Sorrows\t25.0\t31.0\t\t\t\nI\t\tDo |cffffd100Draenethyst Crystals|r, then turn it in at |cffbbbbbb(25, 31)|r\nC\t\t1389\t\t\nS\t\t\tvg=1\nG\t\tSwamp of Sorrows\t25\t31\t\t\t\nT\t\t1389\t\nS\t\t\tvg=1\nI\t\tDo |cffffd100Ongeku|r.\nC\t\t1373\t\t\nS\t\